// ---------- 0.1.80: the Treetop trio, the Gorilla ----------

// The ape measure as exhibits.js runs it for gorillas (geometry.js floodApe), on a pen from ringOf and boxOf.
// The walking measure sees climb categories as it would (logs, frames and glass solid; panes and fences barriers).
async function apeMeasure(blocks, seed = { x: 2, y: 1, z: 2 }) {
  const { floodApe } = await import("../packs/BP/scripts/exhibits/geometry.js");
  const read = climbReader(blocks);
  const walkView = (x, y, z) => {
    const c = read(x, y, z);
    return c === "log" || c === "frame" || c === "glass" ? "solid" : c === "pane" || c === "rail" ? "barrier" : c;
  };
  const walk = newResult(seed);
  const w = floodTerrestrial(walkView, seed, { halfWidth: 32, halfHeight: 16, maxDrop: 3, minHeight: 2, cellsPerYield: 1e9 }, walk);
  while (!w.next().done);
  const out = newClimbResult();
  const f = floodApe(read, walk.cells, { rise: BALANCE.climb.rise, reach: BALANCE.gorilla.reach, cellsPerYield: 50 }, out);
  while (!f.next().done);
  return { walk, out, read };
}

test("Gorilla strong walls: 4 blocks of solid or glass hold one, 3 don't; fences are climbed; a frame or a tree by the wall is a way out", async () => {
  const pen = (layers) => {
    const b = new Map();
    let y = 1;
    for (const [cat, h] of layers) {
      ringOf(b, cat, 4, y, y + h - 1);
      y += h;
    }
    return b;
  };
  const proof = async (layers) => (await apeMeasure(pen(layers))).out.proof;
  // Solid blocks or glass: a top 3 up is within its reach (3.5), 4 up isn't.
  assert.equal(await proof([["glass", 4]]), true, "4 of glass");
  assert.equal(await proof([["solid", 4]]), true, "4 of stone");
  assert.equal(await proof([["glass", 3]]), false, "3 of glass");
  assert.equal(await proof([["solid", 3]]), false, "3 of stone");
  // A fence (a rail it grips) anywhere within reach is a ladder; a fence or wall block's top counts a block and a half.
  assert.equal(await proof([["rail", 1]]), false, "a fence");
  assert.equal(await proof([["rail", 6]]), false, "a tall fence: climbed");
  assert.equal(await proof([["solid", 2], ["rail", 1]]), false, "2 of stone and a fence: 3.5 to the top");
  assert.equal(await proof([["solid", 3], ["rail", 1]]), false, "a fence 3 up: in reach to grip");
  assert.equal(await proof([["solid", 4], ["rail", 1]]), true, "a fence 4 up: out of reach");
  // Stone walls and bars (barriers) aren't gripped: only their top, a block and a half each.
  assert.equal(await proof([["barrier", 3]]), false, "3 of wall: its top 3.5 up");
  assert.equal(await proof([["barrier", 4]]), true, "4 of wall");
  // The way out: from the floor up onto the top and down outside.
  const low = await apeMeasure(pen([["glass", 3]]));
  assert.ok(low.out.path.length > 2 && low.out.escape);
  assert.equal(Math.max(Math.abs(low.out.escape.x), Math.abs(low.out.escape.z)) > 4, true, "outside");
  assert.equal(low.out.via.y, 4, "over the top of the wall");
  // A Climbing Frame by the wall (EAZA 2024: structures 4 m or more from the walls): up it and over.
  const framed = pen([["glass", 5]]);
  boxOf(framed, "frame", [3, 3], [1, 3], [0, 0]);
  assert.equal((await apeMeasure(framed)).out.proof, false, "a frame against the wall");
  const back = pen([["glass", 5]]);
  boxOf(back, "frame", [0, 0], [1, 3], [0, 0]);
  assert.equal((await apeMeasure(back)).out.proof, true, "a frame in the middle");
  // A tree whose leaves reach the wall: up the trunk, out along the branches, onto the wall's top 2 up.
  const tree = (top, spread) => {
    const b = pen([["glass", top]]);
    boxOf(b, "leaves", [-spread, spread], [4, 5], [-spread, spread]);
    boxOf(b, "log", [0, 0], [1, 5], [0, 0]);
    return b;
  };
  const near = await apeMeasure(tree(7, 3));
  assert.equal(near.out.proof, false, "branches to the wall");
  assert.equal(near.out.trees, 1);
  assert.equal((await apeMeasure(tree(7, 2))).out.proof, true, "branches a block short of the wall");
  assert.equal((await apeMeasure(tree(9, 3))).out.proof, true, "the wall's top out of reach of the branches");
  // A moat: deep water it never crosses (it can't swim); shallow water it wades across, to a low wall beyond.
  const moat = (deep) => {
    const b = new Map();
    ringOf(b, "glass", 6, 1, 2);
    for (const r of [4, 5]) ringOf(b, "water", r, deep ? -1 : 1, 1);
    return b;
  };
  assert.equal((await apeMeasure(moat(true))).out.proof, true, "a deep moat");
  assert.equal((await apeMeasure(moat(false))).out.proof, false, "a shallow one, waded");
  // The categories: a fence is a rail only to the ape reader; the End Fence, stone walls and bars stay barriers.
  const cat = (id, o = {}) => classifyBlock(id, { isAir: false, isLiquid: false, open: false, leaves: true, climb: true, ...o });
  assert.deepEqual(["minecraft:oak_fence", "minecraft:nether_brick_fence", "minecraft:fence", "zoocraft:end_fence", "minecraft:cobblestone_wall", "minecraft:iron_bars", "minecraft:oak_fence_gate"].map((id) => cat(id, { ape: true })), ["rail", "rail", "rail", "barrier", "barrier", "barrier", "barrier"]);
  assert.equal(cat("minecraft:oak_fence"), "barrier", "the raccoon's reader is unchanged");
  // The raccoon's measure, shared with it now (the outline and the way out), still finds its ways.
  const rac = new Map();
  ringOf(rac, "glass", 4, 1, 3);
  const walk = newResult({ x: 2, y: 1, z: 2 });
  const w = floodTerrestrial(climbReader(rac), { x: 2, y: 1, z: 2 }, { halfWidth: 32, halfHeight: 16, maxDrop: 3, minHeight: 2, cellsPerYield: 1e9 }, walk);
  while (!w.next().done);
  const out = newClimbResult();
  const c = floodClimb(climbReader(rac), walk.cells, { rise: BALANCE.climb.rise, cellsPerYield: 50 }, out);
  while (!c.next().done);
  assert.equal(out.proof, true, "glass 3 high holds a raccoon");
});

test("Gorilla rules: the troop's day, roles, infants, the ring, the warnings and the clipboard's lines", async () => {
  const R = await import("../packs/BP/scripts/animals/gorillaRules.js");
  const G = BALANCE.gorilla;
  const sp = SPECIES["zoocraft:gorilla"];
  assert.deepEqual(R.GORILLA_TYPES, ["zoocraft:gorilla", "zoocraft:wild_gorilla"]);
  assert.deepEqual([0, 3000, 5000, 9000, 11500, 12500, 18000, 23500, 24500].map(R.dayPart), ["morning", "morning", "midday", "afternoon", "nesting", "nesting", "night", "morning", "morning"]);
  // The moods by weight: at night only sleep, before dusk only nests.
  assert.equal(R.pickMood("night", G, () => 0.5), "sleep");
  assert.equal(R.pickMood("nesting", G, () => 0.99), "nest");
  assert.equal(R.pickMood("morning", G, () => 0), "feed");
  assert.equal(R.pickMood("midday", G, () => 0), "rest");
  // Roles: the record's sex, a wild one's mark.
  assert.equal(R.roleOf({ id: "a", sex: "male" }, sp), "silverback");
  assert.equal(R.roleOf({ id: "b", sex: "female" }, sp), "female");
  assert.equal(R.roleOf({ id: "c", sex: "male", juvenile: true }, sp), "young");
  assert.deepEqual([R.wildRole(1), R.wildRole(0)], ["silverback", "female"]);
  // An infant rides its first G.rideDays park days.
  assert.equal(R.isInfant({ juvenile: true, bornDay: 10 }, 10 + G.rideDays - 1, G), true);
  assert.equal(R.isInfant({ juvenile: true, bornDay: 10 }, 10 + G.rideDays, G), false);
  assert.equal(R.isInfant({ bornDay: 10 }, 10, G), false, "grown");
  // The ring round the silverback: each G.restRing (or a little more) out.
  const ring = R.ringPlaces({ x: 0, z: 0 }, 4, G);
  assert.equal(ring.length, 4);
  for (const p of ring) assert.ok(Math.hypot(p.x, p.z) >= G.restRing - 1e-9 && Math.hypot(p.x, p.z) <= G.restRing + 0.8 + 1e-9);
  // Deep water, rivals, a big bachelor group.
  assert.equal(R.deepWaterSafe(sp, { deepWaterCells: 0 }), true);
  assert.equal(R.deepWaterSafe(sp, { deepWaterCells: 3 }), false);
  assert.equal(R.deepWaterSafe(SPECIES["zoocraft:otter"] ?? { noSwim: false }, { deepWaterCells: 3 }), true, "a swimmer");
  const m = (id, sex, juvenile = false) => ({ id, name: id, sex, juvenile });
  assert.match(R.troopWarnings({ deepWaterCells: 2 }, [m("a", "female")], [], G)[0].text, /can't swim and drown in deep water: 2 spots are 2 or more blocks deep/);
  assert.match(R.troopWarnings({ deepWaterCells: 0 }, [], [m("a", "male"), m("b", "male")], G)[0].text, /2 silverbacks with the females/);
  const bachelors = [1, 2, 3, 4, 5].map((i) => m(`m${i}`, "male"));
  assert.match(R.troopWarnings({ deepWaterCells: 0 }, bachelors, [], G)[0].text, /5 grown males together: a bachelor group gets on with 4 at most/);
  assert.deepEqual(R.troopWarnings({ deepWaterCells: 0 }, bachelors.slice(0, 4), [], G), []);
  assert.deepEqual(R.troopLines({ deepWaterCells: 0 }, [m("a", "male"), m("b", "female"), m("c", "female"), m("d", "male", true)]), ["§fTroop: §71 silverback, 2 females, 1 young", "§fDeep water: §7none (gorillas can't swim)"]);
  // Strong walls on the clipboard and in the issue.
  assert.match(R.apeLine({}, "Gorillas"), /not measured yet/);
  assert.match(R.apeLine({ apeClimb: { proof: true, trees: 2 } }, "Gorillas"), /§ayes§7, gorillas can't get out; 2 climbing trees/);
  assert.match(R.apeLine({ apeClimb: { proof: false, trees: 0, via: { x: 1, y: 5, z: 2, leaves: true } } }, "Gorillas"), /§cno§7, gorillas could get out near 1 5 2 through a tree's branches/);
  assert.match(R.apeIssue("Gorillas", { via: { x: 1, y: 5, z: 2 } }, G), /Gorillas could get out near 1 5 2\. They climb trees, Climbing Frames and fences, and pull themselves up onto anything up to 3\.5 blocks above where they stand.*4 or more blocks high/);
  assert.match(R.wildLine(G.bluff), /Come within 10 blocks and he warns you off.*Still within 6 and he charges, stopping short.*a shove for 3 hearts/);
});

test("Gorilla bluff: the display, a charge that stops short, a real one only at someone who keeps coming or hurt the troop", async () => {
  const { bluffStep } = await import("../packs/BP/scripts/animals/gorillaRules.js");
  const B = BALANCE.gorilla.bluff;
  const see = (dist, o = {}) => ({ dist, exposed: true, grudge: false, ...o });
  let s = bluffStep(undefined, see(15), 0, B);
  assert.equal(s.phase, "calm");
  s = bluffStep(s, see(9), 10, B);
  assert.equal(s.phase, "display", "within 10: the display");
  // Staying back (beyond the charge range) through the display: he stands his ground, then lets them be.
  let t = bluffStep(s, see(8), 10 + B.displayTicks, B);
  assert.equal(t.phase, "stand");
  const t0stand = () => bluffStep(s, see(8), 10 + B.displayTicks, B);
  t = bluffStep(t, see(8), 10 + B.displayTicks + B.standTicks, B);
  assert.equal(t.phase, "back");
  assert.equal(bluffStep(t, see(8), t.until, B).phase, "calm");
  // Within the charge range after the display: a bluff charge, stopping short.
  let c = bluffStep(s, see(5), 10 + B.displayTicks, B);
  assert.deepEqual([c.phase, c.real], ["charge", false]);
  c = bluffStep(c, see(B.stopShort), 100, B);
  assert.equal(c.phase, "stand", "stopped short");
  // Standing still where he stopped (inside the close range) isn't coming on; nor is stepping back.
  assert.equal(bluffStep(c, see(B.stopShort), 105, B).phase, "stand", "stood still through the bluff");
  assert.equal(bluffStep(c, see(2.9), 105, B).phase, "stand");
  // Coming on within the close range: the real charge, the shove when he reaches them, then he lets them be.
  let r = bluffStep(c, see(B.stopShort - 0.6), 110, B);
  assert.deepEqual([r.phase, r.real], ["charge", true]);
  r = bluffStep(r, see(1.5), 115, B);
  assert.deepEqual([r.phase, r.shove], ["back", true]);
  r = bluffStep(r, see(1.5), 120, B);
  assert.deepEqual([r.phase, r.shove], ["back", false], "the shove lands once");
  // Stood his ground after the display (from beyond the charge range): within the close range is coming on.
  assert.deepEqual([bluffStep(t0stand(), see(B.closeRange), 200, B).phase, bluffStep(t0stand(), see(B.closeRange), 200, B).real], ["charge", true]);
  // Walking up during the display: within the close range, the real charge. Already that close when he begins
  // (where his last bluff charge left them) and staying put: a bluff again, not a real one.
  assert.deepEqual([bluffStep(s, see(B.closeRange), 20, B).phase, bluffStep(s, see(B.closeRange), 20, B).real], ["charge", true]);
  const close = bluffStep(bluffStep(undefined, see(15), 0, B), see(2.8), 10, B);
  assert.equal(bluffStep(close, see(2.8), 20, B).phase, "display");
  assert.deepEqual([bluffStep(close, see(2.8), 10 + B.displayTicks, B).phase, bluffStep(close, see(2.8), 10 + B.displayTicks, B).real], ["charge", false]);
  // Hurting one of the troop: a real charge straight away. Not in Survival: no bluff at all.
  assert.deepEqual([bluffStep(undefined, see(9, { grudge: true }), 0, B).phase, bluffStep(undefined, see(9, { grudge: true }), 0, B).real], ["charge", true]);
  assert.equal(bluffStep(s, see(5, { exposed: false }), 20, B).phase, "calm");
  // Walking away during the display ends it.
  assert.equal(bluffStep(s, see(B.displayRange + B.leaveSlack + 1), 20, B).phase, "calm");
});

test("Gorilla climbing: up a trunk feet first both ways, and out of a pen without strong walls", async () => {
  const R = await import("../packs/BP/scripts/animals/gorillaRules.js");
  const C = await import("../packs/BP/scripts/animals/climbRules.js");
  const G = BALANCE.gorilla;
  const b = new Map();
  ringOf(b, "glass", 4, 1, 4);
  boxOf(b, "log", [0, 0], [1, 3], [0, 0]);
  const read = climbReader(b);
  const foot = { x: 1, y: 1, z: 0 };
  const t = C.trunkBeside(read, foot);
  const route = C.climbRoute(read, t.from, t.dir, G.maxUp);
  assert.equal(route.onTop, true);
  const up = R.apeUpLegs(t.from, t.dir, route, G);
  const down = R.apeDownLegs(t.from, t.dir, route, G);
  const face = C.yawTo(t.dir.x, t.dir.z);
  assert.deepEqual(up.map((l) => l.act), [R.ACT.climb, R.ACT.climb, R.ACT.climb, R.ACT.climb, R.ACT.walk]);
  assert.deepEqual(up[up.length - 1].to, { x: 0.5, y: 4, z: 0.5 }, "on top of the trunk");
  assert.ok(down.slice(0, -1).every((l) => l.act === R.ACT.down && l.yaw === face), "down feet first, facing the trunk");
  assert.deepEqual(down[down.length - 1], { to: { x: 1.5, y: 1, z: 0.5 }, ticks: G.gripTicks, act: R.ACT.none, yaw: face });
  // A young one hugs closer.
  assert.ok(R.apeUpLegs(t.from, t.dir, route, G, 0.32)[0].to.x < up[0].to.x);
  // Out of a stone pen 3 high, along the ape measure's way out: hauled up the wall, over, down facing it.
  const low = await apeMeasure(ringOf(new Map(), "solid", 4, 1, 3));
  const path = low.out.path;
  const legs = R.apeEscapeLegs(low.read, path[0], path, G);
  assert.ok(legs.length >= 3);
  for (const l of legs) assert.ok([R.ACT.walk, R.ACT.climb, R.ACT.down, R.ACT.none].includes(l.act), String(l.act));
  const haul = legs.find((l) => l.act === R.ACT.climb);
  assert.equal(haul.ticks, G.climbTicks * 3, "3 blocks up in one pull");
  assert.ok(legs.some((l) => l.act === R.ACT.down), "down the outside");
  // From the top of a Climbing Frame against a glass wall 5 high: the pull up onto the wall faces the wall.
  const framed = ringOf(new Map(), "glass", 4, 1, 5);
  boxOf(framed, "frame", [3, 3], [1, 3], [0, 0]);
  const fm = await apeMeasure(framed);
  const fLegs = R.apeEscapeLegs(fm.read, fm.out.path[0], fm.out.path, G);
  const onto = fLegs.filter((l) => l.act === R.ACT.climb).at(-1);
  assert.deepEqual([onto.yaw, onto.to.x > 3.5, onto.to.y], [C.yawTo(1, 0), true, 6], "facing the wall it pulls itself onto");
});

test("Gorilla care: rival silverbacks and deep water cap comfort; the troop breeds with one silverback", async () => {
  const W = await import("../packs/BP/scripts/animals/welfare.js");
  const Br = await import("../packs/BP/scripts/animals/breeding.js");
  const sp = SPECIES["zoocraft:gorilla"];
  const day = BALANCE.clock.dayLength;
  for (const [k, cap] of Object.entries({ troop: BALANCE.gorilla.rivalComfortCap, deep: BALANCE.gorilla.deepComfortCap })) {
    const a = { needs: { satiety: 90, comfort: 90, cleanliness: 90, enrichment: 90, social: 90 }, health: 100 };
    W.simulateAnimal(a, sp, { exhibitCleanliness: 100, spaceRatio: 1, groupSize: 3, feederUnits: 10, [k]: false }, day * 20, BALANCE);
    assert.equal(a.needs.comfort, cap, k);
  }
  assert.deepEqual(W.comfortCauses({ spaceRatio: 1, troop: false, deep: false }, BALANCE), ["troop", "deep"]);
  const advice = W.adviceFor("comfort", sp, ["troop", "deep"]);
  assert.match(advice, /one silverback with the females/);
  assert.match(advice, /no water 2 or more deep: they can't swim/);
  // Two grown males with a female: rivals, and no breeding; a bachelor pair is no trouble.
  const g = (id, sex, juvenile = false) => ({ id, name: id, sex, juvenile, coat: 0 });
  assert.equal(Br.rivalStallions([g("a", "male"), g("b", "male"), g("c", "female")], sp).length, 2);
  assert.equal(Br.rivalStallions([g("a", "male"), g("b", "male")], sp).length, 0);
  const ctx = { species: sp, on: true, animals: [g("a", "male"), g("b", "male"), g("c", "female")], day: 20, cooldownUntil: 0, state: "occupied", plural: "Gorillas" };
  assert.match(Br.breedingCheck(ctx, BALANCE.breeding).reason, /fight over the females: a troop has one silverback/);
  // The species: a dangerous ape in a troop, on Leafy and Fruit Rations, baited with a Fruit Ration.
  assert.equal(sp.dangerous && sp.troop && sp.ape && sp.noSwim && sp.climbTree && sp.sexLook, true);
  assert.equal(Boolean(sp.climbs || sp.harem || sp.sexByCoat), false);
  assert.deepEqual(HABITAT_PROFILES[sp.habitatProfile], { baseArea: 200, extraArea: 50, minHeight: 5 });
  assert.deepEqual([sp.dietTags, sp.baitItem, sp.carrierProfile, sp.coats, sp.dens], [["leafy", "fruit"], "zoocraft:fruit_ration", "large", ["Western lowland"], { spare: 0, cubsFollow: true }]);
  assert.deepEqual(sp.observe, ["spot", "chestbeat", "nightnest", "picking"]);
  assert.deepEqual([sp.breeding.litter, sp.breeding.young, sp.breeding.youngPlural], [1, "infant", "infants"]);
  const others = Object.values(SPECIES).filter((s) => s !== sp).flatMap((s) => s.names ?? []);
  assert.deepEqual(sp.names.filter((n) => others.includes(n)), [], "names of its own");
  assert.deepEqual(validateData(), []);
  // Crating: a wild one (or one that got out) only while it eats a thrown Fruit Ration; a zoo one from its den.
  const { crateBlock } = await import("../packs/BP/scripts/animals/predatorRules.js");
  assert.match(crateBlock(sp, { wild: true }), /throw a Fruit Ration down near the gorilla/);
  assert.equal(crateBlock(sp, { wild: true, eating: true }), undefined);
  assert.match(crateBlock(sp, { wild: false, loose: true }), /throw a Fruit Ration down/);
  assert.equal(crateBlock(sp, { wild: false, loose: true, eating: true }), undefined);
  assert.match(crateBlock(sp, { wild: false }), /Shut the gorilla in a Holding Den first/);
  assert.match(crateBlock(SPECIES["zoocraft:lion"], { wild: true }), /throw a Meat Ration down near the lion/, "a lion's is still the Meat Ration");
  // Climbing trees for an ape are the ape measure's (a Climbing Frame always counts).
  const { hasClimbTree } = await import("../packs/BP/scripts/animals/climbRules.js");
  assert.equal(hasClimbTree(sp, { apeClimb: { trees: 0 }, climb: { trees: 3 } }, []), false);
  assert.equal(hasClimbTree(sp, { apeClimb: { trees: 1 } }, []), true);
  assert.equal(hasClimbTree(sp, { apeClimb: { trees: 0 } }, [{ type: "frame" }]), true);
  assert.equal(hasClimbTree(SPECIES["zoocraft:raccoon"], { apeClimb: { trees: 0 }, climb: { trees: 3 } }, []), true, "a raccoon's are the climb measure's");
});

test("Gorilla Field Journal: the chest-beat display, a night nest, grooming", async () => {
  const { TASKS, tasksSeen, levelOf } = await import("../packs/BP/scripts/discovery/rules.js");
  const sp = SPECIES["zoocraft:gorilla"];
  assert.deepEqual(tasksSeen(sp, ["spot"], { chestBeat: true, nestBuilding: false, picking: true }), ["chestbeat", "picking"]);
  assert.deepEqual(tasksSeen(sp, ["spot", "chestbeat", "picking"], { nestBuilding: true }), ["nightnest"]);
  assert.equal(levelOf(sp, ["spot", "chestbeat", "nightnest", "picking"]), 3);
  for (const t of sp.observe) assert.ok(TASKS[t], t);
  const read = (p) => readFileSync(new URL(p, import.meta.url), "utf8");
  const disc = read("../packs/BP/scripts/discovery/discovery.js");
  assert.match(disc, /return \{ chestBeat: act === GORILLA_ACT\.display \|\| act === GORILLA_ACT\.warn, nestBuilding: act === GORILLA_ACT\.nest, picking: act === GORILLA_ACT\.groom \};/);
  assert.match(disc, /\.\.\.gorillaSight\(species, hit\)/);
  const journal = read("../packs/BP/scripts/ui/fieldJournal.js");
  assert.match(journal, /if \(sp\.troop\) lines\.splice\(4, 0, `§c\$\{gorillaWildLine\(BALANCE\.gorilla\.bluff\)\}`\);/);
  assert.match(journal, /§7Strong walls: they climb trees, Climbing Frames and fences/);
});

test("Gorilla files: the mob, the wild one, the spawn, the skins, the animations and the wiring", () => {
  const read = (p) => readFileSync(new URL(p, import.meta.url), "utf8");
  const json = (p) => JSON.parse(read(p));
  const ACTS = 18;
  for (const name of ["gorilla", "wild_gorilla"]) {
    const be = json(`../packs/BP/entities/${name}.json`)["minecraft:entity"];
    assert.deepEqual(be.description.properties["zoocraft:act"], { type: "int", range: [0, ACTS], default: 0, client_sync: true }, name);
    for (const ev of ["zoocraft:move", "zoocraft:still", "zoocraft:climb", "zoocraft:ride", "zoocraft:den_in", "zoocraft:den_out", "zoocraft:sex_0", "zoocraft:sex_1"]) assert.ok(be.events[ev], `${name} ${ev}`);
    for (const g of ["zoocraft:moving", "zoocraft:still", "zoocraft:climbing", "zoocraft:riding", "zoocraft:denned"]) assert.ok(be.component_groups[g], `${name} ${g}`);
    assert.ok(be.components["minecraft:type_family"].family.includes("gorilla"), `${name} family`);
    // Each body event swaps the other bodies out (0.1.70: whatever a group held comes back with the next one).
    for (const ev of ["zoocraft:move", "zoocraft:still", "zoocraft:climb", "zoocraft:ride"]) assert.equal(be.events[ev].add.component_groups.length, 1, ev);
    const rp = json(`../packs/RP/entity/${name}.entity.json`)["minecraft:client_entity"].description;
    assert.equal(rp.geometry.default, "geometry.zoocraft.gorilla");
    for (const t of Object.values(rp.textures)) assert.ok(readdirSync(new URL("../packs/RP/textures/entity/zoocraft/", import.meta.url)).includes(`${t.split("/").pop()}.png`), t);
  }
  const wild = json("../packs/BP/entities/wild_gorilla.json")["minecraft:entity"];
  for (const ev of ["zoocraft:hunt", "zoocraft:calm"]) assert.ok(wild.events[ev], ev);
  const zoo = json("../packs/BP/entities/gorilla.json")["minecraft:entity"];
  assert.ok(zoo.components["minecraft:type_family"].family.includes("zoocraft_animal"));
  assert.equal(zoo.events["zoocraft:hunt"], undefined, "a zoo gorilla has no hunting group: predators.js only triggers it on wild ones");
  const spawn = json("../packs/BP/spawn_rules/wild_gorilla.json")["minecraft:spawn_rules"];
  assert.match(JSON.stringify(spawn.conditions[0]["minecraft:biome_filter"]), /jungle/);
  assert.match(JSON.stringify(spawn.conditions[0]["minecraft:biome_filter"]), /bamboo/);
  // The client plays an animation for every act; the render controller swaps the skins and shows the crest.
  const ctrl = read("../packs/RP/animation_controllers/gorilla.animation_controllers.json");
  for (let a = 1; a <= ACTS; a++) assert.ok(ctrl.includes(`query.property('zoocraft:act') == ${a}`), `act ${a}`);
  const anims = json("../packs/RP/animations/gorilla.animation.json").animations;
  for (const a of ["walk", "run", "sit", "eat", "browse", "puzzle", "groom", "nest", "sleep", "rest", "display", "warn", "shove", "play", "climb", "down", "ride"]) assert.ok(anims[`animation.zoocraft.gorilla.${a}`], a);
  assert.equal(anims["animation.zoocraft.gorilla.display"].animation_length, 4);
  // Molang only (no keyframe lists): nothing the client precomputes as cubic (0.1.78).
  assert.doesNotMatch(JSON.stringify(anims), /"lerp_mode"|catmullrom/);
  const rc = read("../packs/RP/render_controllers/gorilla.render_controllers.json");
  assert.ok(rc.includes("query.mark_variant == 1"), "the silverback's look");
  const lang = read("../packs/RP/texts/en_US.lang");
  for (const l of ["entity.zoocraft:gorilla.name=Gorilla", "entity.zoocraft:wild_gorilla.name=Wild Gorilla"]) assert.ok(lang.includes(l), l);
  // The wiring: the loops, the ape measure, the caps, the bait, the clipboard.
  const main = read("../packs/BP/scripts/main.js");
  assert.match(main, /loop\("gorillas", 10, \d+, \(\) => tickGorillas\(system\.currentTick\)\)/);
  assert.match(main, /loop\("gorillamove", 1, \d+, tickGorillaMoves\)/);
  assert.match(main, /initGorillas\(\);/);
  const ex = read("../packs/BP/scripts/exhibits/exhibits.js");
  assert.match(ex, /floodApe\(blockReader\(dim\(ex\.dimension\), \{ leaves: true, climb: true, ape: true \}, memo\), out\.cells, \{ rise: BALANCE\.climb\.rise, reach: BALANCE\.gorilla\.reach, cellsPerYield: opts\.cellsPerYield \}, ape\);/);
  assert.match(ex, /&& !climbsOut && !apesOut( && !wallsOut( && !boarsOut( && !hopsOut( && !goatsOut( && !frogsOut)?)?)?)?)?;/);
  const animals = read("../packs/BP/scripts/animals/animals.js");
  assert.match(animals, /enrichmentPerDay, canopy, nestbox, shade, troop, deep(, perches(, nylium, rub(, walls, hide, males(, wallow(, soul(, bed(, pads(, crevices, mineral(, rock, burrows(, flowers, dim(, endPlants, warmPads, retreat(, sand(, seagrass(, lush, clay(, burrow(, sculk, shriek(, bloom(, warmth(, hoard(, trunk(, snow(, soulfloor, beam(, mobfloor(, hay(, run, groomed: [\w.()]+(, rockLedges(, desertSand, desertShade(, lilyPads(, waterPlants, tankFloor(, deepStretch, openWater(, beeFlowers, beeHives(, restSpots(, sandFloor, chill(, mycelium(, digBed(, batRoosts, batFlight(, coolBiome(, skyView(, sulfur)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)? \};/);
  assert.match(animals, /treesMeasure\(species, ex\)\?\.trees \?\? 0\)/);
  const pred = read("../packs/BP/scripts/animals/predators.js");
  assert.match(pred, /baits\.has\(it\.getComponent\("minecraft:item"\)\?\.itemStack\?\.typeId\)/);
  assert.match(pred, /const rest = new ItemStack\(s\.typeId, s\.amount - 1\);/);
  assert.doesNotMatch(pred, /e\.triggerEvent\("zoocraft:(hunt|calm)"\)|w\.triggerEvent\("zoocraft:calm"\)/, "only through huntEvent");
  const gor = read("../packs/BP/scripts/animals/gorilla.js");
  assert.match(gor, /entitiesNear\(player\.dimension, player\.location, KEEP_RANGE \+ G\.troopReach, GORILLA_TYPES\)/, "found by type");
  assert.match(read("../packs/BP/scripts/ui/clipboard.js"), /\.\.\.\(ape \? \[apeLine\(ex, pluralOf\(ape\)\)\] : \[\]\),/);
  assert.match(read("../packs/BP/scripts/transport/carriers.js"), /const loose = Boolean\(a\.outside && species\.ape && !den\);/);
});
// ---------- 0.1.81: the Treetop trio, the Owl ----------

test("Owl rules: the night bird's day, its hoots, a way through the aviary's air, the speed and the wingbeats", async () => {
  const O = await import("../packs/BP/scripts/animals/owlRules.js");
  const T = BALANCE.owl;
  // Day, dusk, night and dawn by the game's clock (0 sunrise, 12000 sunset, 18000 midnight).
  assert.deepEqual([1000, 6000, 11000, 12500, 15000, 18000, 22000, 23000, 23990].map((t) => O.phaseOf(t, T)), ["day", "day", "day", "dusk", "night", "night", "night", "dawn", "day"]);
  assert.equal(O.phaseOf(24000 + 12500, T), "dusk", "any day");
  // The hoot: two notes, the second a little higher; the female's higher than the male's.
  const [m1, m2] = O.hootPitch("male");
  const [f1] = O.hootPitch("female");
  assert.ok(m2 > m1 && f1 > m1);
  // An aviary 12 x 12, 4 high, with a wall across it, a gap at one end.
  const cells = new Set();
  for (let x = 1; x <= 12; x++) for (let z = 1; z <= 12; z++) for (let y = 1; y <= 4; y++) if (!(x === 6 && z <= 10)) cells.add(`${x},${y},${z}`);
  const open = (x, y, z) => cells.has(`${x},${y},${z}`);
  const way = O.airWay(open, { x: 2, y: 1, z: 2 }, { x: 10, y: 4, z: 2 });
  assert.ok(way && way.every((c) => open(c.x, c.y, c.z)), "through open air only");
  assert.ok(way.some((c) => c.x === 6 && c.z >= 11), "round the end of the wall");
  assert.equal(O.airWay(open, { x: 2, y: 1, z: 2 }, { x: 6, y: 1, z: 2 }), undefined, "into the wall: no way");
  // Never cutting a corner: two open blocks touching only at an edge have no way between them.
  const corner = new Set(["0,0,0", "1,0,1"]);
  assert.equal(O.airWay((x, y, z) => corner.has(`${x},${y},${z}`), { x: 0, y: 0, z: 0 }, { x: 1, y: 0, z: 1 }), undefined);
  // Straightened: few points, each stretch clear for its body.
  const body = { half: 0.22, height: 0.78 };
  const pts = O.smoothWay(open, way, { x: 2.5, y: 1, z: 2.5 }, { x: 10.5, y: 4, z: 2.5 }, body);
  assert.ok(pts.length >= 3 && pts.length < way.length, `${pts.length} points`);
  for (let i = 1; i < pts.length; i++) assert.ok(O.clearLine(open, pts[i - 1], pts[i], body), `stretch ${i}`);
  assert.deepEqual([pts[0], pts[pts.length - 1]], [{ x: 2.5, y: 1, z: 2.5 }, { x: 10.5, y: 4, z: 2.5 }]);
  // The speed: slow at take-off and landing, the cruise between; the flight takes about its length over the cruise.
  const f = O.flightOf(pts);
  const F = T.fly;
  assert.ok(Math.abs(O.speedAt(0, f.total, F) - F.slow) < 1e-9 && Math.abs(O.speedAt(f.total, f.total, F) - F.slow) < 1e-9);
  assert.equal(O.speedAt(f.total / 2, f.total, F), F.cruise);
  let s = 0;
  let ticks = 0;
  while (s < f.total && ticks < 1000) {
    s += O.speedAt(s, f.total, F);
    ticks++;
  }
  assert.ok(ticks > f.total / F.cruise && ticks < f.total / F.cruise + 40, `${ticks} ticks for ${f.total.toFixed(1)} blocks`);
  const mid = O.along(f, f.total / 2);
  assert.ok(open(Math.floor(mid.x), Math.floor(mid.y), Math.floor(mid.z)));
  // The wings: flapping to take off and to climb, landing at the end, a glide going down, and a rhythm between.
  assert.equal(O.wingsAt(0.2, 10, 0, 1, 0, F), O.ACT.fly);
  assert.equal(O.wingsAt(9.5, 10, 0, 1, 0, F), O.ACT.land);
  assert.equal(O.wingsAt(5, 10, 1, 2, 0, F), O.ACT.fly, "climbing");
  assert.equal(O.wingsAt(5, 10, -1, 2, 0, F), O.ACT.glide, "going down");
  const beats = new Set([0, 5, 10, 15, 20, 25].map((t) => O.wingsAt(5, 10, 0, 2, t, F)));
  assert.deepEqual([...beats].sort(), [O.ACT.fly, O.ACT.glide].sort(), "a few wingbeats, then a glide");
  // The wild: straight through open air, or up over a tree in the way.
  const treeIn = (x, y, z) => !(x === 5 && z === 0 && y >= 0 && y <= 6) && y >= 0;
  const route = O.wildRoute(treeIn, { x: 0.5, y: 1, z: 0.5 }, { x: 10.5, y: 1, z: 0.5 }, body);
  assert.equal(route.length, 4, "up, across and down");
  assert.ok(route[1].y > 6);
  assert.equal(O.wildRoute((x, y, z) => y >= 0, { x: 0.5, y: 1, z: 0.5 }, { x: 10.5, y: 1, z: 0.5 }, body).length, 2, "straight");
  // Under a canopy (leaves 3 blocks up over it, 7 blocks across) with a wall of trunks beside it: no way straight
  // or up over, but the search finds the way out from under the leaves and up, kept to its box, and straightened.
  const canopy = (x, y, z) => y >= 0 && !(y === 3 && Math.abs(x) <= 3 && Math.abs(z) <= 3) && !(x === 2 && y <= 2 && Math.abs(z) <= 3);
  const out = { x: 0.5, y: 0, z: 0.5 };
  const up = { x: 0.5, y: 6, z: 0.5 };
  assert.equal(O.wildRoute(canopy, out, up, body), undefined, "the leaves are in the way");
  const ws = O.seekWay(canopy, { x: 0, y: 0, z: 0 }, { x: 0, y: 6, z: 0 });
  assert.ok(ws && ws.every((c) => canopy(c.x, c.y, c.z)), "through open air only");
  assert.ok(ws.some((c) => Math.abs(c.x) > 3 || Math.abs(c.z) > 3), "out from under the leaves");
  assert.ok(ws.every((c) => c.y <= 16 && Math.abs(c.x) <= 6 && Math.abs(c.z) <= 6), "kept to the box round its ends");
  const sw = O.smoothWay(canopy, ws, out, up, body);
  for (let i = 1; i < sw.length; i++) assert.ok(O.clearLine(canopy, sw[i - 1], sw[i], body) || i === 1 || i === sw.length - 1, "straightened through open air");
  assert.equal(O.seekWay((x, y, z) => y >= 0 && !(Math.abs(x) <= 1 && Math.abs(z) <= 1 && y <= 1) || (x === 0 && z === 0 && y === 0), { x: 0, y: 0, z: 0 }, { x: 5, y: 0, z: 0 }), undefined, "boxed in: no way");
  // Treetops and the ground: leaves with open air above, a floor that isn't leaves.
  const col = { 5: "leaves", 4: "leaves", 3: "log", 0: "solid" };
  const read = (x, y, z) => col[y] ?? (y < 0 ? "solid" : "air");
  assert.deepEqual(O.treetopAt(read, 0, 0, 12, -4), { x: 0, y: 6, z: 0 });
  assert.equal(O.groundAt(read, 0, 0, 12, -4), undefined, "under leaves");
  assert.deepEqual(O.groundAt((x, y) => (y <= 0 ? "solid" : "air"), 3, 3, 8, -4), { x: 3, y: 1, z: 3 });
  // Bait: the Meat Ration held, or an empty carrier held with one on them.
  assert.equal(O.tempts("zoocraft:meat_ration", false, false, "zoocraft:meat_ration"), true);
  assert.equal(O.tempts("zoocraft:small_carrier", true, true, "zoocraft:meat_ration"), true);
  assert.equal(O.tempts("zoocraft:small_carrier", true, false, "zoocraft:meat_ration"), false);
  const by = O.besidePlayer({ x: 0, y: 64, z: 0 }, { x: 10, y: 70, z: 0 }, T.baitLand);
  assert.deepEqual(by, { x: T.baitLand, y: 64, z: 0 });
});

test("Owl aviary: Perches found by the air over them wherever they stand, at varied heights; what an aviary needs", async () => {
  const { serves } = await import("../packs/BP/scripts/equipment/rules.js");
  const { key } = await import("../packs/BP/scripts/exhibits/geometry.js");
  const { habitatProblem } = await import("../packs/BP/scripts/exhibits/room.js");
  const { ROOST_HEIGHT, AERIAL_HEIGHT } = await import("../packs/BP/scripts/data/profiles.js");
  const O = await import("../packs/BP/scripts/animals/owlRules.js");
  const prof = HABITAT_PROFILES.aviary;
  assert.deepEqual(prof, { baseArea: 16, extraArea: 8, minHeight: 4, aerial: true, minRoosts: 2 });
  assert.equal(requiredArea(prof, 2), 24, "AZA 2019: 6 x 3.9 m for a pair");
  assert.deepEqual([ROOST_HEIGHT, AERIAL_HEIGHT], [4, 14], "an empty aviary is measured at an owl's height; a Void Perch still asks the ray's");
  // The Perch block: "perch" to the flight measure, solid to everyone else, and guests see past it.
  const c = (id, extra = {}) => classifyBlock(id, { isAir: false, isLiquid: false, open: false, ...extra });
  assert.equal(c("zoocraft:perch", { perch: true }), "perch");
  assert.equal(c("zoocraft:perch"), "solid");
  assert.equal(blocksView("zoocraft:perch", { isAir: false, isLiquid: false }), false);
  // A roofed box 5 high: a Perch on the floor and one on top of a 2-block post. Both serve (the air over them is a
  // perch cell); a Void Perch needs air under it as well.
  const read = airBox({ roof: 6, perches: [[3, 1, 3], [8, 3, 8]] });
  const post = (x, y, z) => (x === 8 && z === 8 && (y === 1 || y === 2) ? "solid" : read(x, y, z));
  const r = runAir(post, { x: 6, y: 1, z: 6 }, { minHeight: 4 });
  assert.equal(r.enclosed, true);
  assert.equal(r.cells.get(key(3, 2, 3)), "perch");
  assert.equal(r.cells.get(key(8, 4, 8)), "perch");
  assert.equal(serves("roost", r.cells, { x: 3, y: 1, z: 3 }), true, "on the floor");
  assert.equal(serves("roost", r.cells, { x: 8, y: 3, z: 8 }), true, "on a post");
  assert.equal(serves("perch", r.cells, { x: 3, y: 1, z: 3 }), false, "a Void Perch on the floor doesn't");
  assert.equal(serves("roost", r.cells, { x: 6, y: 1, z: 6 }), false, "nothing there");
  // Their heights: the floor one 1 over the floor, the post's 3; 2 apart, so varied enough.
  assert.equal(O.heightAbove(r.cells, { x: 3, y: 2, z: 3 }), 1);
  assert.equal(O.heightAbove(r.cells, { x: 8, y: 4, z: 8 }), 3);
  assert.equal(O.heightAbove(r.cells, { x: 5, y: 1, z: 5 }), 0, "on the floor");
  const roosts = O.roostsOf([{ id: "a", type: "roost", pos: { x: 3, y: 1, z: 3 } }, { id: "b", type: "roost", pos: { x: 8, y: 3, z: 8 } }, { id: "n", type: "nest", pos: { x: 1, y: 1, z: 1 } }]);
  assert.deepEqual(roosts.map((q) => [q.id, q.cell.y]), [["a", 2], ["b", 4]]);
  assert.equal(O.perchSpread(roosts), 2);
  assert.equal(O.perchSpread(roosts.slice(0, 1)), 0);
  assert.equal(O.highestFree(roosts, new Set()).id, "b");
  assert.equal(O.highestFree(roosts, new Set(["b"])).id, "a", "the highest one taken: the next");
  assert.equal(O.highestFree(roosts, new Set(["a", "b"])), undefined);
  const owl = SPECIES["zoocraft:owl"];
  assert.equal(O.hasPerchSpread(owl, { roostSpread: 2 }, BALANCE.owl), true);
  assert.equal(O.hasPerchSpread(owl, { roostSpread: 1 }, BALANCE.owl), false);
  assert.equal(O.hasPerchSpread(owl, {}, BALANCE.owl), true, "not measured yet");
  assert.equal(O.hasPerchSpread(SPECIES["zoocraft:void_ray"], { roostSpread: 0 }, BALANCE.owl), true, "only for owls");
  // A floor block beside the feeder to land on, facing it.
  const fs = O.feederSpot(r.cells, { x: 6, y: 1, z: 6 }, { x: 10, y: 3, z: 6 });
  assert.deepEqual(fs.cell, { x: 7, y: 1, z: 6 });
  assert.equal(fs.yaw, 90, "facing west, to the feeder");
  // What an aviary needs: measured for flight, a roof, 4 blocks of air, 2 Perches.
  assert.match(habitatProblem({}, prof, "Owl"), /place 2 Perches inside the exhibit .* roof it over/);
  assert.match(habitatProblem({ aerial: { enclosed: false, escape: { x: 1, y: 9, z: 1 } } }, prof, "Owl"), /needs a roof and closed walls\. The air leads out near 1 9 1/);
  assert.match(habitatProblem({ aerial: { enclosed: true, usableArea: 0, roostCount: 2 } }, prof, "Owl"), /4 blocks of air .* raise the roof/);
  assert.match(habitatProblem({ aerial: { enclosed: true, usableArea: 30, roostCount: 1, perchCount: 3 } }, prof, "Owl"), /2 or more Perches to sit on \(1 now/, "Void Perches don't count");
  assert.equal(habitatProblem({ aerial: { enclosed: true, usableArea: 30, roostCount: 2 } }, prof, "Owl"), undefined);
  assert.match(habitatProblem({ aerial: { enclosed: true, usableArea: 400, perchCount: 1, roostCount: 4 } }, HABITAT_PROFILES.large_aerial, "Void Ray"), /2 or more Void Perches/, "Perches don't count for rays");
  // The clipboard's lines and the warnings.
  const fx = [{ type: "roost", pos: { x: 3, y: 1, z: 3 } }, { type: "roost", pos: { x: 8, y: 2, z: 8 } }];
  const lines = O.owlLines({}, [], fx, BALANCE.owl);
  assert.match(lines[0], /Perches: §a2§7 \(2 or more\), §e1 block between the highest and the lowest/);
  assert.match(lines[1], /none \(they lay their eggs only in a Nest Box\)/);
  const warn = O.owlWarnings({ breeding: { on: true } }, [], fx, BALANCE.owl);
  assert.equal(warn.length, 2);
  assert.match(warn[0].text, /all about one height: put one 2 or more blocks higher or lower .* above 50/);
  assert.match(warn[1].text, /lay their eggs only in a Nest Box/);
  assert.deepEqual(O.owlWarnings({ breeding: { on: true } }, [], [...fx, { type: "roost", pos: { x: 1, y: 4, z: 1 } }, { type: "nest", pos: { x: 2, y: 1, z: 2 } }], BALANCE.owl), []);
});

test("Owl care: Perches all one height cap comfort; eggs only in a Nest Box; a roofed flyer's exhibit is sheltered", async () => {
  const W = await import("../packs/BP/scripts/animals/welfare.js");
  const Br = await import("../packs/BP/scripts/animals/breeding.js");
  const sp = SPECIES["zoocraft:owl"];
  const day = BALANCE.clock.dayLength;
  const a = { needs: { satiety: 90, comfort: 90, cleanliness: 90, enrichment: 90, social: 90 }, health: 100 };
  W.simulateAnimal(a, sp, { exhibitCleanliness: 100, spaceRatio: 1, groupSize: 2, feederUnits: 10, perches: false }, day * 20, BALANCE);
  assert.equal(a.needs.comfort, BALANCE.owl.perchComfortCap);
  assert.deepEqual(W.comfortCauses({ spaceRatio: 1, perches: false }, BALANCE), ["perches"]);
  assert.match(W.adviceFor("comfort", sp, ["perches"]), /Perches at different heights/);
  // Breeding: a female and a male, everything ready but the Nest Box.
  const o = (id, sex) => ({ id, name: id, sex, juvenile: false, coat: 0 });
  const ctx = { species: sp, on: true, animals: [o("f", "female"), o("m", "male")], day: 20, cooldownUntil: 0, state: "occupied", plural: "Owls", usable: 40, required: (n) => 16 + 8 * (n - 1), foodDays: 5, coveredCells: 40, usableArea: 40, goodDays: 9, welfareOf: () => 90 };
  assert.match(Br.breedingCheck({ ...ctx, nestBoxes: 0 }, BALANCE.breeding).reason, /lay their eggs only in a Nest Box/);
  const ok = Br.breedingCheck({ ...ctx, nestBoxes: 1 }, BALANCE.breeding);
  assert.equal(ok.ok, true, ok.reason);
  assert.ok(ok.litter >= 2 && ok.litter <= 3);
  const sitting = Br.breedingCheck({ ...ctx, animals: [{ ...o("f", "female"), expecting: { daysLeft: 2 } }, o("m", "male")], nestBoxes: 1 }, BALANCE.breeding);
  assert.match(sitting.reason, /f is sitting on her eggs in the Nest Box: they hatch in 2 park days/);
  // The species: a flyer of its own on Perches, a Small Carrier, Meat Rations, a pair at most.
  assert.equal(sp.flies && sp.roosts && sp.sexLook, true);
  assert.equal(Boolean(sp.dangerous || sp.nestBox || sp.nocturnal), false, "not dangerous; Nest Boxes for eggs, not one each; no dark house");
  assert.deepEqual([sp.habitatProfile, sp.movementProfile, sp.carrierProfile, sp.dietTags, sp.baitItem, sp.rationUnitsPerParkDay], ["aviary", "aerial", "small", ["meat"], "zoocraft:meat_ration", 1]);
  assert.deepEqual(sp.social, { minGroup: 1, recommendedMax: 5, prefersCompany: true }, "a pair and their owlets");
  // A breeding pair's young fit the group: every species that breeds has room for a pair and a litter (0.1.81: red
  // pandas at 2 could never breed).
  for (const s of Object.values(SPECIES)) if (s.breeding && !s.solitary) assert.ok(2 + s.breeding.litter <= s.social.recommendedMax, s.id);
  assert.deepEqual(sp.observe, ["spot", "hoot", "pounce", "pellet"]);
  assert.deepEqual([sp.breeding.litter, sp.breeding.litterMax, sp.breeding.juvenileScale, sp.breeding.young, sp.breeding.nestBox], [2, 3, 0.6, "owlet", true]);
  const others = Object.values(SPECIES).filter((s) => s !== sp).flatMap((s) => s.names ?? []);
  assert.deepEqual(sp.names.filter((n) => others.includes(n)), [], "names of its own");
  assert.deepEqual(validateData(), []);
  // A roofed flyer's exhibit counts all its floor as sheltered (before 0.1.81 a Void Ray's counted none, and
  // its breeding stopped at "a sheltered corner").
  const read = (p) => readFileSync(new URL(p, import.meta.url), "utf8");
  const ex = read("../packs/BP/scripts/exhibits/exhibits.js");
  assert.match(ex, /\? \(profileOf\(ex\)\.aerial && r\.enclosed \? r\.usableArea : r\.coveredCells\) : undefined;/);
  assert.match(ex, /minHeight: inside === "void" \? AERIAL_HEIGHT : ROOST_HEIGHT/);
  assert.match(ex, /f\.type === "perch" \|\| f\.type === "roost" \? Boolean\(air\) && airBox\(f\.pos\) && serves\(f\.type, air\.cells, f\.pos\)/);
  assert.match(ex, /ex\.roostSpread = air \? perchSpread\(roosts\) : undefined;/);
  const nursery = read("../packs/BP/scripts/animals/nursery.js");
  assert.match(nursery, /nestBoxes: fixturesOf\(ex\)\.filter\(\(f\) => f\.type === "nest"\)\.length/);
  assert.match(nursery, /const spot = (spawn \?\? )?nest\?\.pos \?\? box \?\? /, "owlets hatch in the Nest Box");
});

test("Owl Field Journal: a hoot, a swoop onto food, a pellet", async () => {
  const { TASKS, tasksSeen, levelOf } = await import("../packs/BP/scripts/discovery/rules.js");
  const sp = SPECIES["zoocraft:owl"];
  assert.deepEqual(tasksSeen(sp, ["spot"], { hooting: true, pouncing: false, pelleting: true }), ["hoot", "pellet"]);
  assert.deepEqual(tasksSeen(sp, ["spot", "hoot", "pellet"], { pouncing: true }), ["pounce"]);
  assert.deepEqual(tasksSeen(sp, ["spot"], { flying: true, looping: true }), [], "a Void Ray's flight tasks aren't an owl's");
  assert.equal(levelOf(sp, ["spot", "hoot", "pounce", "pellet"]), 3);
  for (const t of sp.observe) assert.ok(TASKS[t], t);
  const read = (p) => readFileSync(new URL(p, import.meta.url), "utf8");
  const disc = read("../packs/BP/scripts/discovery/discovery.js");
  assert.match(disc, /return \{ hooting: act === OWL_ACT\.hoot, pouncing: act === OWL_ACT\.eat, pelleting: act === OWL_ACT\.pellet \};/);
  assert.match(disc, /\.\.\.owlSight\(species, hit\)/);
  assert.match(disc, /if \(!species\.flies \|\| species\.roosts( \|\| species\.soulLight( \|\| species\.chorusFlowers( \|\| species\.warmth( \|\| species\.beeGarden( \|\| species\.dances( \|\| species\.batRoost)?)?)?)?)?)?\) return \{\};/, "no Void Ray properties read off an owl");
  const journal = read("../packs/BP/scripts/ui/fieldJournal.js");
  assert.match(journal, /if \(sp\.roosts\) lines\.splice\(4, 0, `§7\$\{owlWildLine\(BALANCE\.owl\)\}`\);/);
  assert.match(journal, /§7Aviary: a roof and closed walls/);
});

test("Owl files: the mob, the wild one, the spawn, the Perch, the skins, the animations and the wiring", () => {
  const read = (p) => readFileSync(new URL(p, import.meta.url), "utf8");
  const json = (p) => JSON.parse(read(p));
  const ACTS = 12;
  for (const name of ["owl", "wild_owl"]) {
    const be = json(`../packs/BP/entities/${name}.json`)["minecraft:entity"];
    assert.deepEqual(be.description.properties["zoocraft:act"], { type: "int", range: [0, ACTS], default: 0, client_sync: true }, name);
    for (const ev of ["zoocraft:watch", "zoocraft:fly", "zoocraft:sex_0", "zoocraft:sex_1"]) assert.ok(be.events[ev], `${name} ${ev}`);
    // Flown by the script: no gravity, no walking, no can_fly (0.1.67), no pushing it off its perch.
    assert.equal(be.components["minecraft:physics"].has_gravity, false);
    assert.equal(be.components["minecraft:movement"].value, 0);
    assert.equal(be.components["minecraft:can_fly"], undefined);
    assert.equal(be.components["minecraft:pushable_by_entity"], undefined, name);
    assert.ok(be.components["minecraft:pushable_by_block"], name);
    assert.ok(be.components["minecraft:type_family"].family.includes("owl"), `${name} family`);
    // The look groups hold only the look goal: swapping them never strips the base (0.1.70).
    assert.deepEqual(Object.keys(be.component_groups["zoocraft:watching"]), ["minecraft:behavior.look_at_player"]);
    assert.deepEqual(be.component_groups["zoocraft:flying"], {});
    for (const ev of ["zoocraft:watch", "zoocraft:fly"]) assert.equal(be.events[ev].add.component_groups.length, 1, ev);
    const rp = json(`../packs/RP/entity/${name}.entity.json`)["minecraft:client_entity"].description;
    assert.equal(rp.geometry.default, "geometry.zoocraft.owl");
    assert.equal(rp.scripts.scale, "q.is_baby ? 0.6 : (q.mark_variant == 1 ? 0.88 : 1)");
    for (const t of Object.values(rp.textures)) assert.ok(readdirSync(new URL("../packs/RP/textures/entity/zoocraft/", import.meta.url)).includes(`${t.split("/").pop()}.png`), t);
  }
  const zoo = json("../packs/BP/entities/owl.json")["minecraft:entity"];
  assert.ok(zoo.components["minecraft:type_family"].family.includes("zoocraft_animal"));
  assert.ok(zoo.events["zoocraft:juvenile"] && zoo.events["zoocraft:home_8"]);
  const spawn = json("../packs/BP/spawn_rules/wild_owl.json")["minecraft:spawn_rules"];
  assert.match(JSON.stringify(spawn.conditions[0]["minecraft:biome_filter"]), /taiga.*roofed.*extreme_hills/);
  // The client plays an animation for every act; the render controller shuts its eyes roosting, puffs the throat
  // hooting and shows the food eating.
  const ctrl = read("../packs/RP/animation_controllers/owl.animation_controllers.json");
  for (let a = 1; a <= ACTS; a++) assert.ok(ctrl.includes(`query.property('zoocraft:act') == ${a}`), `act ${a}`);
  const anims = json("../packs/RP/animations/owl.animation.json").animations;
  for (const a of ["idle", "fly", "glide", "land", "watch", "roost", "hoot", "eat", "pellet", "preen", "display", "nestbox", "beg", "look_at_target"]) assert.ok(anims[`animation.zoocraft.owl.${a}`], a);
  assert.match(JSON.stringify(anims["animation.zoocraft.owl.look_at_target"]), /query\.target_y_rotation/);
  assert.doesNotMatch(JSON.stringify(anims), /"lerp_mode"|catmullrom/, "nothing the client precomputes as cubic (0.1.78)");
  const rc = read("../packs/RP/render_controllers/owl.render_controllers.json");
  assert.ok(rc.includes("query.property('zoocraft:act') == 5") && rc.includes("query.property('zoocraft:act') == 6") && rc.includes("query.property('zoocraft:act') == 7"));
  // The Perch: a T-perch, a fixture, its bar the only thing that collides, two from logs and sticks.
  const block = json("../packs/BP/blocks/perch.json")["minecraft:block"];
  assert.equal(block.description.identifier, "zoocraft:perch");
  assert.ok("zoocraft:fixture" in block.components);
  assert.deepEqual(block.components["minecraft:collision_box"], { origin: [-7, 13, -1.5], size: [14, 3, 3] });
  assert.equal(block.components["minecraft:geometry"], "geometry.zoocraft.perch");
  const recipe = json("../packs/BP/recipes/zoocraft_perch.json")["minecraft:recipe_shaped"];
  assert.deepEqual(recipe.result, { item: "zoocraft:perch", count: 2 });
  assert.deepEqual(recipe.tags, ["zoocraft_workshop"]);
  assert.equal(json("../packs/BP/loot_tables/blocks/zoocraft_perch.json").pools[0].entries[0].name, "zoocraft:perch");
  assert.deepEqual(json("../packs/RP/blocks.json")["zoocraft:perch"], { sound: "wood" });
  const lang = read("../packs/RP/texts/en_US.lang");
  for (const l of ["entity.zoocraft:owl.name=Owl", "entity.zoocraft:wild_owl.name=Wild Owl", "tile.zoocraft:perch.name=Perch"]) assert.ok(lang.includes(l), l);
  // The wiring: the loops, found by type, the Perch fixture, the comfort cap in the ctx.
  const main = read("../packs/BP/scripts/main.js");
  assert.match(main, /loop\("owls", 10, \d+, \(\) => tickOwls\(system\.currentTick\)\)/);
  assert.match(main, /loop\("owlmove", 1, \d+, tickOwlMoves\)/);
  const owlJs = read("../packs/BP/scripts/animals/owl.js");
  assert.match(owlJs, /entitiesNear\(player\.dimension, player\.location, RANGE, OWL_TYPES\)/, "found by type");
  assert.match(owlJs, /flyStep\(e, d, \{ x: 0, y: m\.yaw \}, system\.currentTick, tell\)/, "pushed as the Void Ray is");
  const fixtures = read("../packs/BP/scripts/equipment/fixtures.js");
  assert.match(fixtures, /\[BLOCKS\.roost\]: "roost"(, \[BLOCKS\.landingPad\]: "pad")? \};/);
  assert.match(read("../packs/BP/scripts/data/items.js"), /roost: "zoocraft:perch",/);
  const animals = read("../packs/BP/scripts/animals/animals.js");
  assert.match(animals, /enrichmentPerDay, canopy, nestbox, shade, troop, deep, perches(, nylium, rub(, walls, hide, males(, wallow(, soul(, bed(, pads(, crevices, mineral(, rock, burrows(, flowers, dim(, endPlants, warmPads, retreat(, sand(, seagrass(, lush, clay(, burrow(, sculk, shriek(, bloom(, warmth(, hoard(, trunk(, snow(, soulfloor, beam(, mobfloor(, hay(, run, groomed: [\w.()]+(, rockLedges(, desertSand, desertShade(, lilyPads(, waterPlants, tankFloor(, deepStretch, openWater(, beeFlowers, beeHives(, restSpots(, sandFloor, chill(, mycelium(, digBed(, batRoosts, batFlight(, coolBiome(, skyView(, sulfur)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)? \};/);
  assert.match(read("../packs/BP/scripts/ui/clipboard.js"), /\.\.\.\(percher \? owlLines\(ex, /);
});
// ---------- 0.1.84: the Nether trio, the Crimson Grazer ----------

test("Grazer rules: the day's moods, the herd and its lead, the ring of horns, the rush, rubbing", async () => {
  const G = await import("../packs/BP/scripts/animals/grazerRules.js");
  const T = BALANCE.grazer;
  // Grazing in the morning and the afternoon, resting round noon, asleep through the night (0 sunrise, 6000 noon).
  assert.deepEqual([23500, 1000, 4900, 5500, 6900, 8000, 12000, 13000, 18000, 22900].map((t) => G.moodAt(t, T)), ["graze", "graze", "graze", "rest", "rest", "graze", "graze", "sleep", "sleep", "sleep"]);
  assert.equal(G.moodAt(24000 + 6000, T), "rest", "any day");
  // What it goes for: no feeder, no stem: cropping or a wander; a calf never rubs.
  const seen = new Set();
  for (let i = 0; i < 40; i++) seen.add(G.pickInterest({ feeder: false, stem: true, calf: true }, () => i / 40));
  assert.deepEqual([...seen].sort(), ["graze", "wander"]);
  const all = new Set();
  for (let i = 0; i < 40; i++) all.add(G.pickInterest({ feeder: true, stem: true, calf: false }, () => i / 40));
  assert.deepEqual([...all].sort(), ["feeder", "graze", "rub", "wander"]);
  assert.equal(G.restAct("sleep", () => 0.5), G.ACT.rest, "mostly asleep by night");
  assert.equal(G.restAct("rest", () => 0.5), G.ACT.chew, "mostly chewing round noon");
  // The lead: the oldest grown bull; with none, the oldest grown cow; a calf only on its own.
  const m = (id, male, adult, age) => ({ id, male, adult, age });
  assert.equal(G.leadOf([m("cow", false, true, 9), m("bull", true, true, 2), m("old bull", true, true, 5), m("calf", true, false, 99)]), "old bull");
  assert.equal(G.leadOf([m("a", false, true, 1), m("b", false, true, 3), m("calf", true, false, 9)]), "b");
  assert.equal(G.leadOf([m("calf", true, false, 1)]), "calf");
  assert.equal(G.leadOf([]), undefined);
  // Wild herds: linked within range, the biggest first.
  const herds = G.herdsOf([{ id: "a", x: 0, z: 0 }, { id: "b", x: 10, z: 0 }, { id: "c", x: 20, z: 0 }, { id: "d", x: 60, z: 0 }], 16);
  assert.deepEqual(herds.map((h) => h.sort()), [["a", "b", "c"], ["d"]]);
  // The ring: a bull, three cows and a calf, a threat to the east. The grown ones evenly round the middle, facing
  // out (the yaw looks away from the middle), the bull on the side toward the threat; the calf in the middle.
  const members = [{ id: "bull", x: 1, z: 1, adult: true, male: true }, { id: "c1", x: -1, z: 1, adult: true, male: false }, { id: "c2", x: -1, z: -1, adult: true, male: false }, { id: "c3", x: 1, z: -1, adult: true, male: false }, { id: "calf", x: 0, z: 0, adult: false, male: false }];
  const places = G.ringPlaces(members, { x: 20, z: 0 }, T);
  assert.equal(places.size, 5);
  const bull = places.get("bull");
  assert.ok(bull.x > 1.9 && Math.abs(bull.z) < 1e-9, "the bull faces the threat, in front");
  assert.equal(bull.yaw, G.yawTo(1, 0), "facing out, toward the threat");
  for (const id of ["c1", "c2", "c3"]) {
    const p = places.get(id);
    assert.ok(Math.abs(Math.hypot(p.x, p.z) - Math.max(T.ringMin, (4 * T.ringSpacing) / (2 * Math.PI))) < 1e-9, `${id} on the ring`);
    assert.equal(p.yaw, G.yawTo(p.x, p.z), `${id} facing out`);
  }
  assert.ok(Math.hypot(places.get("calf").x, places.get("calf").z) < 1e-9, "the calf in the middle");
  // Someone among them: the middle draws back so the front place stays ringGap short of them.
  const close = G.ringPlaces(members, { x: 0.5, z: 0 }, T);
  const front = Math.min(...[...close.values()].map((p) => Math.hypot(p.x - 0.5, p.z)));
  assert.ok(Math.abs(front - T.ringGap) < 1e-9, `front ${front}`);
  assert.ok(close.get("bull").x < 0.5 - T.ringGap + 1e-9, "the bull still between them and the herd");
  const onTop = G.ringPlaces(members, { x: 0, z: 0 }, T);
  assert.ok([...onTop.values()].every((p) => Math.hypot(p.x, p.z) >= T.ringGap - 1e-9 && Number.isFinite(p.yaw)));
  // Two bulls take the two places nearest the threat.
  const two = G.ringPlaces([...members.slice(0, 3), { id: "bull2", x: 1, z: -1, adult: true, male: true }], { x: 20, z: 0 }, T);
  const order = [...two.entries()].filter(([, p]) => p.x !== 0 || p.z !== 0).sort((p, q) => q[1].x - p[1].x).map(([id]) => id);
  assert.deepEqual(order.slice(0, 1), ["bull"]);
  assert.ok(order.indexOf("bull2") <= 2, "the second bull beside the first");
  // The rush: the bull nearest within range (a bull before a cow as near); a calf never.
  assert.equal(G.rusherOf(members, { x: 3, z: 1 }, T.rushRange), "bull");
  assert.equal(G.rusherOf(members, { x: 30, z: 0 }, T.rushRange), undefined, "out of range");
  assert.equal(G.rusherOf([{ id: "calf", x: 0, z: 0, adult: false }], { x: 1, z: 0 }, 3), undefined);
  const r = G.rushTo({ x: 0, z: 0 }, { x: 5, z: 0 }, T.rushShort);
  assert.ok(Math.abs(r.x - (5 - T.rushShort)) < 1e-9 && r.z === 0 && r.yaw === G.yawTo(1, 0));
  assert.equal(G.rushTo({ x: 0, z: 0 }, { x: 1, z: 0 }, T.rushShort).length, 0, "already that close: no rush");
  const steps = G.stepsAlong({ x: 0, z: 0 }, { x: 1, z: 0 }, 0.3);
  assert.equal(steps.length, 4);
  assert.deepEqual(steps[3], { x: 1, z: 0 });
  // Rubbing: side on, the stem at its left. In Minecraft facing +z (yaw 0) the left is +x.
  assert.equal(G.rubYaw({ x: 1, z: 0 }), 0);
  assert.equal(G.rubYaw({ x: -1, z: 0 }), 180);
  assert.equal(G.rubYaw({ x: 0, z: 1 }), G.yawTo(-1, 0));
  // What it crops and what it rubs on.
  for (const id of ["minecraft:crimson_nylium", "minecraft:crimson_roots", "minecraft:warped_fungus", "minecraft:nether_sprouts", "minecraft:grass_block"]) assert.ok(G.grazeable(id), id);
  for (const id of ["minecraft:netherrack", "minecraft:soul_sand", undefined]) assert.equal(G.grazeable(id), false, String(id));
  for (const id of ["minecraft:crimson_stem", "minecraft:stripped_crimson_hyphae"]) assert.ok(G.isRubStem(id), id);
  assert.equal(G.isRubStem("minecraft:warped_stem"), false, "a crimson stem");
  assert.equal(G.isRubStem("minecraft:oak_log"), false);
});

test("Grazer exhibit: crimson nylium and the stems beside the floor counted by the walking measure", () => {
  // Categories of their own only for readers that ask; a climb reader still sees a crimson stem as a log.
  const c = (id, extra = {}) => classifyBlock(id, { isAir: false, isLiquid: false, open: false, ...extra });
  assert.equal(c("minecraft:crimson_nylium", { nylium: true }), "nylium");
  assert.equal(c("minecraft:crimson_nylium"), "solid");
  assert.equal(c("minecraft:warped_nylium", { nylium: true }), "solid", "crimson only");
  assert.equal(c("minecraft:crimson_stem", { stem: true }), "stem");
  assert.equal(c("minecraft:stripped_crimson_hyphae", { stem: true }), "stem");
  assert.equal(c("minecraft:crimson_stem", { climb: true }), "log");
  assert.equal(c("minecraft:crimson_stem"), "solid");
  // A 9 x 9 pen: nylium under the west half; a crimson stem standing on the floor at (2, 0, 2), 3 high, and one
  // outside the fence that no floor touches.
  const grid = (x, y, z) => {
    if (x === 2 && z === 2 && y >= 0 && y <= 2) return "stem";
    if (x === 9 && z === 0 && y >= 0 && y <= 2) return "stem";
    if (x < -5 || x > 5 || z < -5 || z > 5) return y < 0 ? "solid" : "air";
    if (x === -5 || x === 5 || z === -5 || z === 5) return y === 0 || y === 1 ? "barrier" : y < 0 ? "solid" : "air";
    if (y === -1) return x <= 0 ? "nylium" : "solid";
    return y < -1 ? "solid" : "air";
  };
  const measure = (opts) => {
    const r = newResult({ x: -2, y: 0, z: 0 });
    const it = floodTerrestrial(grid, r.seed, { halfWidth: 32, halfHeight: 16, maxDrop: 3, minHeight: 4, cellsPerYield: 1e9, ...opts }, r);
    while (!it.next().done);
    return r;
  };
  const r = measure({ countNylium: true, countStem: true });
  assert.equal(r.enclosed, true, "nylium is floor and a stem is solid");
  assert.equal(r.usableArea, 80, "the stem stands on one floor block");
  assert.equal(r.nyliumCells, 45, "the west half: 5 rows of 9");
  assert.equal(r.stemCount, 1, "the one beside the floor, counted once");
  const plain = measure({});
  assert.equal(plain.nyliumCells + plain.stemCount, 0, "only counted when asked");
  // Cover: a stem or nylium overhead is a roof like any solid block.
  const roofed = (x, y, z) => (y === 4 ? "nylium" : grid(x, y, z));
  const rr = newResult({ x: -2, y: 0, z: 0 });
  const it = floodTerrestrial(roofed, rr.seed, { halfWidth: 32, halfHeight: 16, maxDrop: 3, minHeight: 4, cellsPerYield: 1e9, coverHeight: 3 }, rr);
  while (!it.next().done);
  assert.equal(rr.coveredCells, rr.usableArea);
});

test("Grazer care: crimson ground and a rubbing stem cap comfort; the warnings, the clipboard, the species", async () => {
  const W = await import("../packs/BP/scripts/animals/welfare.js");
  const G = await import("../packs/BP/scripts/animals/grazerRules.js");
  const C = await import("../packs/BP/scripts/quests/conservationRules.js");
  const sp = SPECIES["zoocraft:crimson_grazer"];
  const T = BALANCE.grazer;
  const day = BALANCE.clock.dayLength;
  const a = () => ({ needs: { satiety: 90, comfort: 90, cleanliness: 90, enrichment: 90, social: 90 }, health: 100 });
  const ground = a();
  W.simulateAnimal(ground, sp, { exhibitCleanliness: 100, spaceRatio: 1, groupSize: 4, feederUnits: 20, heat: true, nylium: false }, day * 20, BALANCE);
  assert.equal(ground.needs.comfort, T.nyliumComfortCap);
  const rub = a();
  W.simulateAnimal(rub, sp, { exhibitCleanliness: 100, spaceRatio: 1, groupSize: 4, feederUnits: 20, heat: true, rub: false }, day * 20, BALANCE);
  assert.equal(rub.needs.comfort, T.rubComfortCap);
  assert.deepEqual(W.comfortCauses({ spaceRatio: 1, nylium: false, rub: false }, BALANCE), ["nylium", "rub"]);
  assert.match(W.adviceFor("comfort", sp, ["nylium", "rub"]), /crimson nylium in the floor.*a crimson stem to rub against/);
  // Alone or in twos a grazer is uneasy (the social need): a herd is 3 or more.
  assert.equal(W.socialTarget(sp.social, 2), 40);
  assert.equal(W.socialTarget(sp.social, 3), 90);
  // What the exhibit has: not measured yet passes; too little nylium, no stem fail.
  assert.equal(G.hasNylium(sp, {}, T), true);
  assert.equal(G.hasNylium(sp, { nyliumCells: 15 }, T), false);
  assert.equal(G.hasNylium(sp, { nyliumCells: 16 }, T), true);
  assert.equal(G.hasNylium(SPECIES["zoocraft:zebra"], { nyliumCells: 0 }, T), true, "not a zebra's");
  assert.equal(G.hasRubStem(sp, { stemCount: 0 }), false);
  assert.equal(G.hasRubStem(sp, { stemCount: 2 }), true);
  const warn = G.grazerWarnings({ nyliumCells: 4, stemCount: 0 }, "Crimson Grazers", T);
  assert.equal(warn.length, 2);
  assert.match(warn[0].text, /at least 16 crimson nylium blocks in the exhibit floor \(4 now\)/);
  assert.match(warn[1].text, /crimson stem/);
  assert.deepEqual(G.grazerWarnings({ nyliumCells: 20, stemCount: 1 }, "Crimson Grazers", T), []);
  const lines = G.grazerLines({ nyliumCells: 20, stemCount: 1 }, [{ juvenile: false }, { juvenile: true }], T);
  assert.deepEqual(lines, ["§fCrimson ground: §720 of 16 crimson nylium blocks", "§fRubbing stems: §71", "§fHerd: §72 (1 grown)"]);
  // Let out on crimson nylium.
  assert.equal(C.groundText(sp), "on crimson nylium");
  assert.equal(C.groundOk(sp, { id: "minecraft:crimson_nylium", isAir: false, isLiquid: false }), true);
  assert.equal(C.groundOk(sp, { id: "minecraft:netherrack", isAir: false, isLiquid: false }), false);
  // The species: a Nether herd, a Thermal Carrier, Fungal Rations, its sexes on the mob.
  assert.deepEqual([sp.habitatProfile, sp.movementProfile, sp.carrierProfile, sp.dietTags, sp.baitItem, sp.rationUnitsPerParkDay, sp.origin, sp.homeDimension], ["herd", "terrestrial", "thermal", ["fungus"], "zoocraft:fungal_ration", 3, "custom_nether", "minecraft:nether"]);
  assert.equal(sp.heat && sp.nylium && sp.rubStem && sp.sexLook, true);
  assert.deepEqual(sp.cover, { minFraction: 0.1, why: "herd shelter" });
  assert.equal(Boolean(sp.dangerous), false, "a hazard to approach, not a predator: no dens");
  assert.deepEqual(sp.social, { minGroup: 3, recommendedMax: 8, prefersCompany: true });
  assert.deepEqual(sp.observe, ["spot", "ring", "rub", "cud"]);
  assert.deepEqual([sp.breeding.litter, sp.breeding.gestationDays, sp.breeding.matureDays, sp.breeding.juvenileScale, sp.breeding.young], [1, 4, 8, 0.4, "calf"]);
  const others = Object.values(SPECIES).filter((s) => s !== sp).flatMap((s) => s.names ?? []);
  assert.deepEqual(sp.names.filter((n) => others.includes(n)), [], "names of its own");
  const herd = HABITAT_PROFILES.herd;
  assert.deepEqual([herd.baseArea, herd.extraArea, herd.minHeight], [180, 40, 4]);
  assert.equal(requiredArea(herd, 4), 300);
  // The Fungal Ration feeds the fungus diet; the shop sells it.
  const I = await import("../packs/BP/scripts/data/items.js");
  assert.deepEqual(I.RATIONS["zoocraft:fungal_ration"], { diet: "fungus", units: 1, label: "Fungal Ration" });
  assert.equal(I.foodLook("zoocraft:fungal_ration"), I.FOOD_LOOK.fungus);
  assert.ok(BALANCE.shop["zoocraft:fungal_ration"].price > 0);
  assert.deepEqual(validateData(), []);
});

