    assert.deepEqual(be.description.properties["zoocraft:act"], { type: "int", range: [0, ACTS], default: 0, client_sync: true }, name);
    for (const ev of ["zoocraft:move", "zoocraft:still", "zoocraft:seek_feeder", "zoocraft:seek_rub", "zoocraft:seek_none", "zoocraft:follow", "zoocraft:lead", "zoocraft:sex_0", "zoocraft:sex_1"]) assert.ok(be.events[ev], `${name} ${ev}`);
    const c = be.components;
