    // The herd follows the tagged lead (a filter that holds whichever way the goal reads its subjects).
    const follow = be.component_groups["zoocraft:following"]["minecraft:behavior.follow_mob"];
    assert.match(JSON.stringify(follow.filters), new RegExp(G.LEAD_TAG));
