// ---------- 0.1.85: the Nether trio, the Warped Gecko ----------

// A gecko terrarium for the gecko tests: a 5 x 5 floor (x and z 0 to 4) on stone at y 0, glass walls 4 high round
// it (solid to a gecko), a stone pillar 2 high at (2, 1..2, 2), a crack in the east wall at (5, 2, 2), and solid
// rock all round outside; a roof at y 5 unless `open`.
function terrarium({ open = false } = {}) {
  return (x, y, z) => {
    const inside = x >= 0 && x <= 4 && z >= 0 && z <= 4;
    if (x === 5 && y === 2 && z === 2) return "air"; // the crack
    if (inside && y >= 1 && (y <= 4 || open)) return x === 2 && z === 2 && y <= 2 ? "solid" : "air";
    if (open && y >= 5 && x >= -1 && x <= 5 && z >= -1 && z <= 5) return x === -1 || x === 5 || z === -1 || z === 5 ? (y <= 4 ? "solid" : "air") : "air";
    return "solid";
  };
}

test("Gecko rules: where it can hold, how it moves, routes that never pass through a block, its poses", async () => {
  const G = await import("../packs/BP/scripts/animals/geckoRules.js");
  const read = terrarium();
  // Spots: an open block and the face it holds; never in a block, never holding air or a slab.
  assert.equal(G.validSpot(read, { x: 0, y: 1, z: 0, f: "f" }), true);
  assert.equal(G.validSpot(read, { x: 0, y: 3, z: 0, f: "w" }), true, "the west glass");
  assert.equal(G.validSpot(read, { x: 1, y: 3, z: 1, f: "e" }), false, "air beside it, not a wall");
  assert.equal(G.validSpot(read, { x: 2, y: 1, z: 2, f: "f" }), false, "inside the pillar");
  assert.equal(G.validSpot(read, { x: 2, y: 3, z: 2, f: "f" }), true, "on top of the pillar");
  const slab = (x, y, z) => (y === 0 ? "partial" : read(x, y, z));
  assert.equal(G.validSpot(slab, { x: 0, y: 1, z: 0, f: "f" }), false, "not on a slab");
  // Every move from the pillar's foot, the wall's corner and the top of the pillar.
  const kinds = (s) => G.movesFrom(read, s).map((m) => m.kind).sort();
  assert.deepEqual(kinds({ x: 1, y: 1, z: 2, f: "f" }), ["onto", "walk", "walk", "walk"], "on the floor by the pillar: onto it, or walk on");
  assert.deepEqual(kinds({ x: 1, y: 2, z: 2, f: "e" }), ["down", "round", "round", "top"], "on the pillar's side: over the top, down, or round a corner (it's one block wide)");
  assert.deepEqual(kinds({ x: 0, y: 2, z: 2, f: "w" }), ["along", "along", "down", "up"], "on the glass: up, down or along");
  assert.ok(G.movesFrom(read, { x: 1, y: 1, z: 2, f: "e" }).some((m) => m.kind === "round" && m.to.f === "s" && m.to.x === 2 && m.to.z === 1), "round the pillar's outside corner");
  assert.ok(G.movesFrom(read, { x: 2, y: 3, z: 2, f: "f" }).some((m) => m.kind === "edge"), "off the edge of the pillar's top, down its side");
  assert.deepEqual(kinds({ x: 0, y: 4, z: 0, f: "w" }).sort(), ["along", "down", "turn"], "the inside corner under the roof: never under the roof");
  // The search reaches every wall of the terrarium, the pillar's top and the crack.
  const box = { min: { x: -1, y: 0, z: -1 }, max: { x: 5, y: 5, z: 5 } };
  const seen = G.explore(read, { x: 0, y: 1, z: 0, f: "f" }, box, 2000);
  assert.ok(seen.has("2,3,2,f") && seen.has("5,2,2,f") && seen.has("4,4,4,e") && seen.has("2,2,1,s"), "the pillar's top, the crack, a high corner, the pillar's side");
  assert.ok(G.explore(read, { x: 0, y: 1, z: 0, f: "f" }, box, 10).size <= 10, "a search stops at its limit");
  // Every route, every leg sampled: the gecko's middle (on the floor, its feet) is always in an open block.
  const open = (x, y, z) => G.geckoOpen(read(Math.floor(x), Math.floor(y), Math.floor(z)));
  let legs = 0;
  for (const k of seen.keys()) {
    const route = G.routeTo(seen, k);
    let at = G.spotPos(route[0].s);
    const all = G.legsAlong(route, G.WALL_GAP, 0.06, G.ACT.walk);
    // Each move's last leg names the route's spot it ends on, in order, the very last the route's end (where it can stop short).
    assert.deepEqual(all.filter((l) => l.spot).map((l) => l.spot), route.slice(1).map((r) => r.s), k);
    if (all.length) assert.equal(all[all.length - 1].spot, route[route.length - 1].s, k);
    for (const leg of all) {
      legs++;
      assert.ok(leg.ticks >= 2 && Number.isFinite(leg.yaw), k);
      for (let i = 0; i <= 10; i++) {
        const p = { x: at.x + ((leg.to.x - at.x) * i) / 10, y: at.y + ((leg.to.y - at.y) * i) / 10, z: at.z + ((leg.to.z - at.z) * i) / 10 };
        const lift = leg.pose === G.POSE.floor ? 0.01 : G.WALL_GAP;
        assert.ok(open(p.x, p.y + lift, p.z), `${k}: a ${leg.pose} leg passes ${JSON.stringify(p)}`);
      }
      at = leg.to;
    }
  }
  assert.ok(legs > 300, `${legs} legs`);
  // Where it sits: on the floor in the middle; on a wall its middle WALL_GAP from it, halfway up.
  assert.deepEqual(G.spotPos({ x: 1, y: 1, z: 1, f: "f" }), { x: 1.5, y: 1, z: 1.5 });
  const w = G.spotPos({ x: 0, y: 3, z: 0, f: "w" });
  assert.ok(Math.abs(w.x - G.WALL_GAP) < 1e-9 && Math.abs(w.y - (3.5 - G.WALL_GAP)) < 1e-9 && w.z === 0.5);
  // Poses: head up facing the wall, head down facing away, across with the wall on its left or right (a mob facing
  // +z, yaw 0, has its left at +x).
  assert.deepEqual(G.poseFor("w", "up"), { pose: G.POSE.up, yaw: G.yawTo(-1, 0) });
  assert.deepEqual(G.poseFor("w", "down"), { pose: G.POSE.down, yaw: G.yawTo(1, 0) });
  assert.deepEqual(G.poseFor("e", "s"), { pose: G.POSE.sideL, yaw: 0 }, "facing +z, the east wall on its left");
  assert.deepEqual(G.poseFor("w", "s"), { pose: G.POSE.sideR, yaw: 0 });
  assert.deepEqual(G.poseFor("f", "e"), { pose: G.POSE.floor, yaw: -90 });
  assert.equal(G.yawTo(0, 1), 0);
  assert.equal(G.yawTo(-1, 0), 90);
  // The crack: three sides it holds and one way out; its hide pose faces out.
  assert.equal(G.crackAt(read, 5, 2, 2), "w");
  assert.equal(G.crackAt(read, 4, 2, 2), undefined, "an open block in the room isn't a crack");
  assert.deepEqual(G.hidePose({ x: 5, y: 2, z: 2, f: "f" }, "w"), { pose: G.POSE.floor, yaw: 90 });
  // Its day: dusk, night, dawn, day; turned round a half-day in a nocturnal house.
  const T = BALANCE.gecko;
  assert.deepEqual([0, 6000, 11000, 12500, 15000, 21000, 23000, 23990].map((t) => G.phaseOf(t, T)), ["day", "day", "day", "dusk", "night", "night", "dawn", "day"]);
  assert.deepEqual([6000, 18000, 24000 + 6000].map((t) => G.phaseOf(t, T, true)), ["night", "day", "night"]);
});

test("Gecko rules: hides, the night's wander, the hunt, rivals and moths", async () => {
  const G = await import("../packs/BP/scripts/animals/geckoRules.js");
  const read = terrarium();
  const T = BALANCE.gecko;
  const box = { min: { x: -1, y: 0, z: -1 }, max: { x: 5, y: 5, z: 5 } };
  const seen = G.explore(read, { x: 0, y: 1, z: 0, f: "f" }, box, 2000);
  const crack = (x, y, z) => G.crackAt(read, x, y, z);
  // Where it hides: the nearest crack; with none, a Burrow Shelter's floor; with neither, the highest wall it reached.
  const hide = G.pickHide(seen, crack, new Set());
  assert.deepEqual([hide.key.startsWith("5,2,2,"), hide.how, hide.out], [true, "crack", "w"], "in the crack (on its floor or a side)");
  assert.deepEqual(G.pickHide(seen, () => undefined, new Set(["3,1,3"])), { key: "3,1,3,f", how: "shelter", out: undefined });
  const high = G.pickHide(seen, () => undefined, new Set());
  assert.equal(high.how, "wall");
  assert.equal(seen.get(high.key).s.y, 4);
  // The night: a grown male keeps low; a female goes anywhere; a wall three times in four.
  for (let i = 0; i < 20; i++) {
    const k = G.pickWander(seen, 1, true, true, T, () => i / 20);
    assert.ok(k && seen.get(k).s.y - 1 <= T.maleLow, `male ${k}`);
    const d = seen.get(k).d;
    assert.ok(d >= T.wanderMin && d <= T.wanderMax);
  }
  assert.ok([...Array(20).keys()].some((i) => seen.get(G.pickWander(seen, 1, false, true, T, () => i / 20)).s.y === 4), "a female goes high");
  assert.equal(G.heightOk(3, true, false, T), true, "a young male climbs high");
  assert.equal(G.pickWander(new Map([["0,1,0,f", { s: { x: 0, y: 1, z: 0, f: "f" }, d: 0 }]]), 1, true, true, T), undefined, "nowhere to go");
  // The hunt: a spot beside the moth on the same wall, facing it; else one within 1.5 blocks.
  const moth = { x: 0, y: 3, z: 2, f: "w" };
  const k = G.pickStalk(seen, moth);
  const s = seen.get(k).s;
  assert.equal(s.f, "w");
  assert.equal(Math.abs(s.y - moth.y) + Math.abs(s.z - moth.z), 1);
  const face = G.facingSpot(s, moth, undefined);
  assert.equal(face.pose, s.y < moth.y ? G.POSE.up : s.y > moth.y ? G.POSE.down : s.z < moth.z ? G.POSE.sideR : G.POSE.sideL);
  assert.deepEqual(G.facingSpot({ x: 1, y: 1, z: 1, f: "f" }, { x: 1, y: 3, z: 3, f: "w" }, undefined), G.poseFor("f", "s"), "on the floor it turns toward it");
  // Rivals: grown males within range, nearest first, each in one pair.
  assert.deepEqual(G.rivalPairs([{ id: "a", x: 0, y: 0, z: 0 }, { id: "b", x: 1, y: 0, z: 0 }, { id: "c", x: 1.5, y: 0, z: 0 }, { id: "d", x: 9, y: 0, z: 0 }], T.rivalRange), [{ a: "b", b: "c", d: 0.5 }]);
  // Moths: on the walls near the feeder (never in it), inside the exhibit; sitting nearly against the wall.
  const spots = G.mothSpots(read, { x: 4, y: 1, z: 4 }, T.mothReach);
  assert.ok(spots.length > 10 && spots.every((m) => G.validSpot(read, m) && m.f !== "f"));
  assert.ok(spots.every((m) => !(m.x === 4 && m.y === 1 && m.z === 4)));
  assert.equal(G.mothSpots(read, { x: 4, y: 1, z: 4 }, T.mothReach, (x) => x < 3).every((m) => m.x < 3), true);
  const p = G.mothPos({ x: 0, y: 3, z: 2, f: "w" });
  assert.ok(Math.abs(p.x - 0.08) < 1e-9 && Math.abs(p.y - 3.55) < 1e-9 && p.z === 2.5);
});

test("Gecko exhibit: the gecko reader, the air that mustn't lead out, wall faces and cracks counted", async () => {
  const G = await import("../packs/BP/scripts/animals/geckoRules.js");
  const c = (id, extra = {}) => classifyBlock(id, { isAir: false, isLiquid: false, open: false, ...extra });
  // What a gecko can't cling to or stand in: blocks that aren't a whole cube; zoo equipment but the cubes.
  for (const id of ["minecraft:oak_slab", "minecraft:stone_block_slab2", "minecraft:wooden_slab", "minecraft:oak_stairs", "minecraft:spruce_trapdoor", "minecraft:chest", "minecraft:ender_chest", "minecraft:red_bed", "minecraft:lantern", "minecraft:soul_lantern", "minecraft:white_candle", "minecraft:flower_pot", "minecraft:anvil", "minecraft:creeper_head", "minecraft:ladder", "minecraft:chain", "minecraft:amethyst_cluster", "zoocraft:insect_feeder", "zoocraft:hay_rack", "zoocraft:climbing_frame", "zoocraft:perch"]) assert.equal(c(id, { gecko: true, leaves: true }), "partial", id);
  for (const id of ["minecraft:stone", "minecraft:glass", "minecraft:tinted_glass", "minecraft:warped_stem", "minecraft:warped_wart_block", "minecraft:double_stone_block_slab", "minecraft:oak_double_slab", "minecraft:dirt_path", "zoocraft:basic_feeder", "zoocraft:zoo_workshop", "zoocraft:thermal_regulator"]) assert.equal(c(id, { gecko: true, leaves: true }), "solid", id);
  assert.equal(c("minecraft:oak_leaves", { gecko: true, leaves: true }), "leaves");
  assert.equal(c("minecraft:oak_fence", { gecko: true }), "barrier");
  assert.equal(c("minecraft:glass_pane", { gecko: true }), "barrier");
  assert.equal(c("zoocraft:burrow_shelter", { gecko: true }), "air", "a hedgehog's burrow: open, a gecko's hide on the floor");
  assert.equal(c("minecraft:torch", { gecko: true }), "air");
  assert.equal(c("minecraft:oak_slab"), "solid", "only for a gecko reader");
  assert.equal(c("zoocraft:insect_feeder"), "solid");
  assert.equal(c("zoocraft:insect_feeder", { croc: true }), "fixture");
  assert.equal(blocksView("zoocraft:insect_feeder", { isAir: false, isLiquid: false }), false, "guests see past it");
  // The measure (exhibits.js): the air from the floor, which must not lead out, then the walls over it.
  const measure = (read) => {
    const room = newResult({ x: 0, y: 1, z: 0 });
    const it = floodAerial(read, room.seed, { halfWidth: 32, halfHeight: 16, minHeight: 4, cellsPerYield: 1e9 }, room);
    while (!it.next().done);
    const walls = G.newWallsResult();
    const m = G.measureWalls(read, room.cells, { cellsPerYield: 7, keep: 32 }, walls);
    while (!m.next().done);
    return { room, walls };
  };
  const roofed = measure(terrarium());
  assert.equal(roofed.room.enclosed, true);
  assert.equal(roofed.room.cells.size, 25 * 4 - 2 + 1, "the room's air, the pillar left out, the crack in");
  // 20 faces of glass a layer for 4 layers, the pillar's 4 a layer for 2, the crack's 3 (and the one it takes away).
  assert.equal(roofed.walls.faces, 80 + 8 + 3 - 1);
  assert.equal(roofed.walls.cracks, 1);
  assert.deepEqual(roofed.walls.crackSpots, [[5, 2, 2, "w"]]);
  const open = measure(terrarium({ open: true }));
  assert.equal(open.room.enclosed, false, "open to the sky: they'd climb out");
  assert.ok(open.room.escape && open.room.escape.y > 4);
  // The exhibit wiring.
  const read = (p) => readFileSync(new URL(p, import.meta.url), "utf8");
  const ex = read("../packs/BP/scripts/exhibits/exhibits.js");
  assert.match(ex, /anyWants\(ex, "clings"\) \|\| \(!species && insectFeederInside\(ex, out\)\)/, "for geckos, or an empty exhibit with an Insect Feeder in it");
  assert.match(ex, /yield\* floodAerial\(read, start, \{ \.\.\.airOpts, minHeight: HABITAT_PROFILES\.terrarium\.minHeight, countEnd: false \}, room\);/);
  assert.match(ex, /yield\* measureWalls\(blockReader\(dim\(ex\.dimension\), \{ leaves: true, gecko: true \}, memo\), room\.cells, \{ cellsPerYield: airOpts\.cellsPerYield, keep: BALANCE\.gecko\.crackKeep \}, walls\);/);
  assert.match(ex, /&& !climbsOut && !apesOut && !wallsOut( && !boarsOut( && !hopsOut( && !goatsOut( && !frogsOut)?)?)?)?;/, "geckos whose air leads out: unsafe");
  assert.match(ex, /if \(species\.clings\) \{\n    if \(!ex\.walls\) return/, "a gecko moves in only once the walls are measured");
  assert.match(ex, /return ex\.walls\.enclosed \? undefined : roofIssue\(pluralOf\(species\), ex\.walls\);/);
  assert.match(ex, /resolve\(applyValidation\(exId, start, out, air, climb, croc, ape, walls(, boar(, soul(, hops(, crevices(, rock(, chorus(, tortoise(, okapi(, molebear(, skulker(, unicorn(, dragon(, griffin(, stag(, snow(, sloth(, mobPen, mobFloor(, bamboo(, goat(, pond(, tank(, pool(, bees(, parrots(, cats)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?\)\);/);
  assert.match(ex, /\(wants\("nocturnal"\) \|\| wants\("nightLife"\) \|\| wants\("lowLight"\)\) && !out\.error\) yield\* measureHouse/, "a nocturnal house for geckos too");
  assert.match(read("../packs/BP/scripts/platform/mc.js"), /climb, ape, nylium, stem, gecko(, thermalMud, boar(, substrate(, thin(, rock(, sandBed(, seagrass(, hay(, mycelium(, dig(, sulfur)?)?)?)?)?)?)?)?)?)? \};/);
  // The roof and the walls on the clipboard, and the issue.
  assert.match(G.roofIssue("Warped Geckos", { escape: { x: 1, y: 20, z: 3 } }), /^Warped Geckos climb glass and walls: the air leads out of the exhibit near 1 20 3, so they could climb out\. Roof it over/);
  assert.match(G.wallsLine({}, 1, "Warped Geckos", BALANCE.gecko), /not measured yet: put an Insect Feeder inside/);
  assert.equal(G.wallsLine({ walls: { enclosed: true, faces: 40, cracks: 2 } }, 2, "Warped Geckos", BALANCE.gecko), "§fClimbing walls: §a40§7 wall faces to cling to, 2 cracks to hide in; roof §aclosed§7");
  assert.match(G.wallsLine({ walls: { enclosed: false, faces: 20, cracks: 1, escape: { x: 0, y: 9, z: 0 } } }, 2, "Warped Geckos", BALANCE.gecko), /§e20§7 \(32 for 2\).*1 crack to hide in; roof §copen§7 \(warped geckos climb glass and walls: the air leads out near 0 9 0, so roof it over\)/);
});

test("Gecko care: walls, hides and one male cap comfort; the warnings, the clipboard, feeders, the species", async () => {
  const W = await import("../packs/BP/scripts/animals/welfare.js");
  const G = await import("../packs/BP/scripts/animals/geckoRules.js");
  const C = await import("../packs/BP/scripts/quests/conservationRules.js");
  const R = await import("../packs/BP/scripts/equipment/rules.js");
  const sp = SPECIES["zoocraft:warped_gecko"];
  const T = BALANCE.gecko;
  const day = BALANCE.clock.dayLength;
  const a = () => ({ needs: { satiety: 90, comfort: 90, cleanliness: 90, enrichment: 90, social: 90 }, health: 100 });
  for (const [k, cap] of [["walls", T.wallsComfortCap], ["hide", T.hideComfortCap], ["males", T.rivalComfortCap]]) {
    const g = a();
    W.simulateAnimal(g, sp, { exhibitCleanliness: 100, spaceRatio: 1, groupSize: 2, feederUnits: 20, heat: true, [k]: false }, day * 20, BALANCE);
    assert.equal(g.needs.comfort, cap, k);
  }
  assert.deepEqual(W.comfortCauses({ spaceRatio: 1, walls: false, hide: false, males: false }, BALANCE), ["walls", "hide", "males"]);
  assert.match(W.adviceFor("comfort", sp, ["walls", "hide", "males"]), /more wall to climb.*a hide each for the day.*one grown male/);
  // Alone is fine (giant geckos live alone or in pairs).
  assert.equal(W.socialTarget(sp.social, 1), W.socialTarget(sp.social, 2));
  // What the exhibit has: not measured yet passes.
  assert.equal(G.hasWalls(sp, {}, 2, T), true);
  assert.equal(G.hasWalls(sp, { walls: { faces: 31 } }, 2, T), false);
  assert.equal(G.hasWalls(sp, { walls: { faces: 32 } }, 2, T), true);
  assert.equal(G.hasWalls(SPECIES["zoocraft:hedgehog"], { walls: { faces: 0 } }, 2, T), true, "not a hedgehog's");
  assert.equal(G.hasHides(sp, { walls: { cracks: 1 } }, 1, 2), true, "a crack and a Burrow Shelter for two");
  assert.equal(G.hasHides(sp, { walls: { cracks: 0 } }, 1, 2), false);
  assert.equal(G.hasHides(sp, {}, 0, 2), true, "not measured yet");
  const m = (sex, juvenile = false) => ({ sex, juvenile });
  assert.equal(G.oneMale(sp, [m("male"), m("male", true), m("female")]), true, "a young male is no rival yet");
  assert.equal(G.oneMale(sp, [m("male"), m("male")]), false);
  const warn = G.geckoWarnings({ walls: { faces: 10, cracks: 0 } }, [m("male"), m("male")], 0, "Warped Geckos", T);
  assert.equal(warn.length, 3);
  assert.match(warn[0].text, /16 wall faces for each \(10 now for 2\)/);
  assert.match(warn[1].text, /a crack for each .* or a Burrow Shelter on the floor \(0 now for 2\)/);
  assert.match(warn[2].text, /2 grown male warped geckos share the exhibit/);
  assert.deepEqual(G.geckoWarnings({}, [m("female")], 0, "Warped Geckos", T), [], "nothing to say before the measure");
  assert.deepEqual(G.geckoLines({ walls: { enclosed: true, faces: 40, cracks: 1 } }, [m("male"), m("female")], 1, "Warped Geckos", T).slice(1), ["§fHides: §71 crack, 1 Burrow Shelter for 2", "§fGrown males: §71"]);
  // Feeders: geckos eat only from an Insect Feeder; any insect eater eats from one too.
  assert.equal(R.reachesFeeder(sp, { insect: true }), true);
  assert.equal(R.reachesFeeder(sp, {}), false, "not from a Basic Feeder");
  assert.equal(R.reachesFeeder(sp, { rack: true }), false);
  for (const id of ["zoocraft:hedgehog", "zoocraft:raccoon", "zoocraft:flamingo"]) assert.equal(R.reachesFeeder(SPECIES[id], { insect: true }), true, id);
  for (const id of ["zoocraft:deer", "zoocraft:zebra", "zoocraft:lion"]) assert.equal(R.reachesFeeder(SPECIES[id], { insect: true }), false, id);
  assert.equal(R.reachesFeeder(SPECIES["zoocraft:hedgehog"], {}), true);
  assert.equal(R.reachesFeeder(SPECIES["zoocraft:zebra"], { rack: true }), true);
  const read = (p) => readFileSync(new URL(p, import.meta.url), "utf8");
  const feeder = read("../packs/BP/scripts/equipment/feeder.js");
  assert.match(feeder, /if \(block\.typeId === BLOCKS\.insectFeeder\) rec\.insect = true;/);
  assert.match(feeder, /rec\.insect \? "Insect Feeder"/);
  assert.match(feeder, /if \(rec\.insect && RATIONS\[item\]\?\.diet !== "insect"\) return/);
  assert.match(feeder, /block\?\.typeId === BLOCKS\.thermalFeeder \|\| block\?\.typeId === BLOCKS\.insectFeeder/, "its look shows only how full it is");
  const animals = read("../packs/BP/scripts/animals/animals.js");
  assert.match(animals, /else if \(!reach\.length && species\.insectFeeder\) out\.push\(\{ severity: 3, text: `\$\{pluralOf\(species\)\} hunt their food: put an Insect Feeder inside/);
  assert.match(animals, /if \(species\.clings\) out\.push\(\.\.\.geckoWarnings\(/);
  assert.match(read("../packs/BP/scripts/ui/clipboard.js"), /\.\.\.\(clinger \? geckoLines\(ex, /);
  // A gecko tucked into its hide is off show at a Viewing Point (one asleep up a wall is still on show).
  const night = read("../packs/BP/scripts/animals/night.js");
  assert.match(night, /if \(GECKO_TYPES\.includes\(e\.typeId\)\) return e\.getProperty\("zoocraft:act"\) === GECKO_ACT\.hide;/);
  // Let out on warped nylium.
  assert.equal(C.groundText(sp), "on warped nylium");
  assert.equal(C.groundOk(sp, { id: "minecraft:warped_nylium", isAir: false, isLiquid: false }), true);
  assert.equal(C.groundOk(sp, { id: "minecraft:crimson_nylium", isAir: false, isLiquid: false }), false);
  assert.equal(C.groundText(SPECIES["zoocraft:crimson_grazer"]), "on crimson nylium");
  // The species: a Nether climber, a Thermal Carrier, Insect Rations, its sexes on the mob.
  assert.deepEqual([sp.habitatProfile, sp.movementProfile, sp.carrierProfile, sp.dietTags, sp.baitItem, sp.rationUnitsPerParkDay, sp.origin, sp.homeDimension], ["terrarium", "terrestrial", "thermal", ["insect"], "zoocraft:insect_ration", 1, "custom_nether", "minecraft:nether"]);
  assert.equal(sp.heat && sp.clings && sp.insectFeeder && sp.nightLife && sp.oneMale && sp.sexLook, true);
  assert.equal(Boolean(sp.climbs || sp.ape || sp.nocturnal || sp.dangerous || sp.flies), false, "its own wall measure and day, not the raccoon's, the gorilla's or the hedgehog's");
  assert.deepEqual(sp.observe, ["spot", "cling", "hunt", "call"]);
  assert.deepEqual([sp.breeding.litter, sp.breeding.juvenileScale, sp.breeding.young, sp.breeding.youngPlural], [2, 0.35, "hatchling", "hatchlings"]);
  const others = Object.values(SPECIES).filter((s) => s !== sp).flatMap((s) => s.names ?? []);
  assert.deepEqual(sp.names.filter((n) => others.includes(n)), [], "names of its own");
  assert.equal(sp.names.length, 16);
  const ter = HABITAT_PROFILES.terrarium;
  assert.deepEqual([ter.baseArea, ter.extraArea, ter.minHeight, Boolean(ter.aerial)], [9, 4, 4, false]);
  assert.equal(requiredArea(ter, 3), 17);
  const I = await import("../packs/BP/scripts/data/items.js");
  assert.equal(I.BLOCKS.insectFeeder, "zoocraft:insect_feeder");
  assert.deepEqual(validateData(), []);
});

test("Gecko nocturnal house line: they glow, and the Nether has no daylight", async () => {
  const N = await import("../packs/BP/scripts/animals/nightRules.js");
  const house = { cells: 48, daylit: 0, bright: 0, lit: 0, brightest: 0 };
  const dark = N.nocturnalLine({ house }, "Hedgehogs", BALANCE);
  assert.match(dark, /fully enclosed and dark: no daylight, brightest spot 0 of 7 allowed.*48 blocks are pitch dark, where guests can't see them/);
  const glow = N.nocturnalLine({ house, dimension: "minecraft:nether" }, "Warped Geckos", BALANCE, true);
  assert.match(glow, /yes §7\(dark, and no daylight reaches the Nether, brightest spot 0 of 7 allowed; 0 of 48 blocks in lamplight\): warped geckos are up by day for the guests and sleep at night §7\(they glow, so guests see them in the dark too\)$/);
  assert.doesNotMatch(glow, /pitch dark|fully enclosed/);
  assert.match(N.nocturnalLine({ house: { ...house, lit: 48 } }, "Warped Geckos", BALANCE, true), /sleep at night$/, "lit everywhere: nothing to add");
  assert.equal(SPECIES["zoocraft:warped_gecko"].glows, true);
  assert.match(readFileSync(new URL("../packs/BP/scripts/ui/clipboard.js", import.meta.url), "utf8"), /nocturnalLine\(ex, pluralOf\(nocturnal\), BALANCE, Boolean\(nocturnal\.glows\)\)/);
});
test("Gecko Field Journal: clinging, the hunt, the call", async () => {
  const { TASKS, tasksSeen, levelOf } = await import("../packs/BP/scripts/discovery/rules.js");
  const sp = SPECIES["zoocraft:warped_gecko"];
  assert.deepEqual(tasksSeen(sp, ["spot"], { clinging: true, hunting: false, calling: true }), ["cling", "call"]);
  assert.deepEqual(tasksSeen(sp, ["spot", "cling", "call"], { hunting: true }), ["hunt"]);
  assert.deepEqual(tasksSeen(sp, ["spot"], { ringing: true, climbing: true }), [], "a grazer's and a raccoon's tasks aren't a gecko's");
  assert.equal(levelOf(sp, ["spot", "cling", "hunt", "call"]), 3);
  for (const t of sp.observe) assert.ok(TASKS[t], t);
  const read = (p) => readFileSync(new URL(p, import.meta.url), "utf8");
  const disc = read("../packs/BP/scripts/discovery/discovery.js");
  assert.match(disc, /return \{ clinging: pose !== undefined && pose !== GECKO_POSE\.floor, hunting: act === GECKO_ACT\.stalk \|\| act === GECKO_ACT\.snap, calling: act === GECKO_ACT\.call \};/);
  assert.match(disc, /\/\*\* @returns \{\{ clinging\?: boolean, hunting\?: boolean, calling\?: boolean \}\} \*\/\nfunction geckoSight/, "one return type (tsc)");
  assert.match(disc, /\.\.\.geckoSight\(species, hit\)/);
  const journal = read("../packs/BP/scripts/ui/fieldJournal.js");
  assert.match(journal, /if \(sp\.clings\) \{/);
  assert.match(journal, /§7Walls to climb: they cling to the side of any whole block, glass too/);
});

test("Gecko files: the mob, the wild one, the spawn, the skins, the poses, the Insect Feeder and the wiring", async () => {
  const read = (p) => readFileSync(new URL(p, import.meta.url), "utf8");
  const json = (p) => JSON.parse(read(p));
  const G = await import("../packs/BP/scripts/animals/geckoRules.js");
  const ACTS = Math.max(...Object.values(G.ACT));
  const POSES = Math.max(...Object.values(G.POSE));
  assert.deepEqual([ACTS, POSES], [11, 4]);
  for (const name of ["warped_gecko", "wild_warped_gecko"]) {
    const be = json(`../packs/BP/entities/${name}.json`)["minecraft:entity"];
    assert.equal(be.description.identifier, `zoocraft:${name}`);
    assert.deepEqual(be.description.properties["zoocraft:act"], { type: "int", range: [0, ACTS], default: 0, client_sync: true }, name);
    assert.deepEqual(be.description.properties["zoocraft:pose"], { type: "int", range: [0, POSES], default: 0, client_sync: true }, name);
    for (const ev of ["zoocraft:move", "zoocraft:still", "zoocraft:climb", "zoocraft:sex_0", "zoocraft:sex_1"]) assert.ok(be.events[ev], `${name} ${ev}`);
    const c = be.components;
    assert.ok(c["minecraft:fire_immune"] && c["minecraft:navigation.walk"] && c["minecraft:physics"] && c["minecraft:movement"], name);
    assert.ok(c["minecraft:type_family"].family.includes("warped_gecko"), `${name} family`);
    assert.deepEqual(c["minecraft:behavior.tempt"].items, BALANCE.gecko.bait);
    assert.equal(JSON.stringify(be).includes('"minecraft:pushable"'), false, "1.26.10: never minecraft:pushable");
    // Each body group holds the walking speed and physics the base has (0.1.70: removing a group removes them);
    // climbing, no gravity (the script glides it and it clings where it stops).
    for (const g of ["zoocraft:moving", "zoocraft:still", "zoocraft:climbing"]) assert.ok(be.component_groups[g]["minecraft:movement"] && be.component_groups[g]["minecraft:physics"], `${name} ${g}`);
    assert.equal(be.component_groups["zoocraft:climbing"]["minecraft:physics"].has_gravity, false);
    assert.equal(be.component_groups["zoocraft:still"]["minecraft:movement"].value, 0);
    for (const [ev, keep] of [["zoocraft:move", "zoocraft:moving"], ["zoocraft:still", "zoocraft:still"], ["zoocraft:climb", "zoocraft:climbing"]]) {
      assert.deepEqual(be.events[ev].add.component_groups, [keep]);
      assert.deepEqual(be.events[ev].remove.component_groups.sort(), ["zoocraft:climbing", "zoocraft:moving", "zoocraft:still"].filter((g) => g !== keep));
    }
    // Its middle sits WALL_GAP from a wall: the box's half-width fits inside that.
    assert.ok(c["minecraft:collision_box"].width / 2 < G.WALL_GAP);
    assert.equal(be.component_groups["zoocraft:sex_1"]["minecraft:mark_variant"].value, 1);
    const rp = json(`../packs/RP/entity/${name}.entity.json`)["minecraft:client_entity"].description;
    assert.equal(rp.geometry.default, "geometry.zoocraft.warped_gecko");
    assert.equal(rp.materials.default, "entity_emissive_alpha", "it glows");
    for (const t of Object.values(rp.textures)) assert.ok(readdirSync(new URL("../packs/RP/textures/entity/zoocraft/", import.meta.url)).includes(`${t.split("/").pop()}.png`), t);
  }
  const zoo = json("../packs/BP/entities/warped_gecko.json")["minecraft:entity"];
  assert.ok(zoo.components["minecraft:type_family"].family.includes("zoocraft_animal"));
  assert.ok(zoo.components["minecraft:persistent"]);
  assert.ok(zoo.events["zoocraft:juvenile"] && zoo.events["zoocraft:home_8"] && zoo.events["zoocraft:home_32"]);
  const juv = zoo.component_groups["zoocraft:juvenile"]["minecraft:collision_box"].width;
  assert.ok(juv / 2 < G.WALL_GAP * SPECIES["zoocraft:warped_gecko"].breeding.juvenileScale, "a hatchling sits nearer the wall: its box fits too");
  const wild = json("../packs/BP/entities/wild_warped_gecko.json")["minecraft:entity"];
  assert.ok(wild.components["minecraft:despawn"]);
  assert.deepEqual(wild.events["minecraft:entity_spawned"].add.component_groups.sort(), ["zoocraft:moving", "zoocraft:sex_1"], "the first a male");
  const spawn = json("../packs/BP/spawn_rules/wild_warped_gecko.json")["minecraft:spawn_rules"];
  assert.match(JSON.stringify(spawn.conditions[0]["minecraft:biome_filter"]), /warped_forest/);
  assert.deepEqual(spawn.conditions[0]["minecraft:spawns_on_block_filter"], ["minecraft:warped_nylium"]);
  assert.match(JSON.stringify(spawn.conditions[0]), /zoocraft:sex_0/, "a second one female");
  // The client: a pose for each wall pose, an animation for every act; nothing cubic (0.1.78).
  const ctrl = read("../packs/RP/animation_controllers/warped_gecko.animation_controllers.json");
  for (let a = 1; a <= ACTS; a++) assert.ok(ctrl.includes(`query.property('zoocraft:act') == ${a}`), `act ${a}`);
  for (let p = 1; p <= POSES; p++) assert.ok(ctrl.includes(`query.property('zoocraft:pose') == ${p}`), `pose ${p}`);
  const anims = json("../packs/RP/animations/warped_gecko.animation.json").animations;
  for (const a of ["walk", "run", "idle", "still", "stalk", "snap", "call", "lick", "bob", "threat", "hide", "sleep", "pose_up", "pose_down", "pose_sideL", "pose_sideR"]) assert.ok(anims[`animation.zoocraft.warped_gecko.${a}`], a);
  assert.doesNotMatch(JSON.stringify(anims), /"lerp_mode"|catmullrom/, "nothing the client precomputes as cubic (0.1.78)");
  const geo = json("../packs/RP/models/entity/warped_gecko.geo.json")["minecraft:geometry"][0];
  const bones = new Set(geo.bones.map((b) => b.name));
  for (const a of Object.values(anims)) for (const b of Object.keys(a.bones ?? {})) assert.ok(bones.has(b), `animates a bone the model has: ${b}`);
  const rc = read("../packs/RP/render_controllers/warped_gecko.render_controllers.json");
  assert.match(rc, /query\.mark_variant == 1/, "a male's look");
  assert.match(rc, /\{"tongue": "query\.property\('zoocraft:act'\) == 7"\}/, "the tongue out only licking");
  assert.equal(json("../packs/RP/particles/moth.json").particle_effect.description.identifier, "zoocraft:moth");
  // The Insect Feeder: string, a glass pane and planks at the Zoo Workshop; full, half or empty to look at.
  const block = json("../packs/BP/blocks/insect_feeder.json")["minecraft:block"];
  assert.equal(block.description.identifier, "zoocraft:insect_feeder");
  assert.deepEqual(block.description.states["zoocraft:fill"], [0, 1, 2]);
  assert.ok(block.components["zoocraft:feeder"], "the feeder component");
  assert.deepEqual(Object.keys(block.components["minecraft:geometry"].bone_visibility).sort(), ["grubs_high", "grubs_low"]);
  const recipe = json("../packs/BP/recipes/zoocraft_insect_feeder.json")["minecraft:recipe_shaped"];
  assert.deepEqual(recipe.result, { item: "zoocraft:insect_feeder", count: 1 });
  assert.ok(recipe.tags.includes("zoocraft_workshop"));
  assert.deepEqual(Object.values(recipe.key).map((k) => k.item ?? k.tag).sort(), ["minecraft:glass_pane", "minecraft:planks", "minecraft:string"]);
  const tt = json("../packs/RP/textures/terrain_texture.json").texture_data;
  for (const t of ["wood", "mesh", "grubs"]) assert.ok(tt[`zoocraft_insect_feeder_${t}`], t);
  const lang = read("../packs/RP/texts/en_US.lang");
  for (const l of ["entity.zoocraft:warped_gecko.name=Warped Gecko", "entity.zoocraft:wild_warped_gecko.name=Wild Warped Gecko", "tile.zoocraft:insect_feeder.name=Insect Feeder"]) assert.ok(lang.includes(l), l);
  // The wiring: the loops, found by type, its reader.
  const main = read("../packs/BP/scripts/main.js");
  assert.match(main, /loop\("geckos", 10, \d+, \(\) => tickGeckos\(system\.currentTick\)\)/);
  assert.match(main, /loop\("geckomove", 1, \d+, tickGeckoMoves\)/);
  const js = read("../packs/BP/scripts/animals/gecko.js");
  assert.match(js, /entitiesNear\(player\.dimension, player\.location, RANGE, GECKO_TYPES\)/, "found by type");
  // No two in one spot: a hide each, and never wandering, fleeing, stalking or coming down where another is.
  assert.match(js, /const pick = pickHide\(without\(seen, busy\), /);
  assert.match(js, /if \(pick\) s\.hideAt = blockOf\(seen\.get\(pick\.key\)\.s\);/);
  assert.match(js, /pickWander\(without\(seen, othersAt\(e\)\), /);
  assert.match(js, /pickStalk\(without\(seen, othersAt\(e\)\), m\.spot, s\.gap\)/);
  assert.equal((js.match(/without\(seen, othersAt\(e\)\)/g) ?? []).length, 4, "wander, flee, stalk, come down");
  // Climbed out, it keeps out until it's caught: no route back over the wall.
  assert.match(js, /s\.out = true;\n  s\.anchor = \{ x: v\.x, y: v\.y, z: v\.z \};/);
  assert.match(js, /const read = fencedReader\(reader\(e\), fenceOf\(s, ex, a\)\);/);
  // Tempted down: to its own floor first, not a crack's or a ledge's.
  assert.match(js, /if \(n\.s\.y === floorY\) return keep\(go\(e, s, routeTo\(seen, k\), T\.walk, ACT\.walk, toFloor\)\);/);
  // On its way somewhere: a player beside it or tempting it stops it at the end of the move (not coming down or out).
  assert.match(js, /if \(tempted\(e, players\) \|\| \(now >= s\.threatCool && threatNear\(e, players, T\)\)\) cutShort\(e\.id\);\n    return;/);
  assert.match(js, /keep\(go\(e, s, routeTo\(seen, out\), /);
  assert.match(js, /if \(rec\.cut\) s\.next = 0;/);
  // Onto its spot by a short walk, never a jump; forgotten mid-glide, onto the nearest spot of its route.
  assert.match(js, /s\.next = system\.currentTick \+ 40;\n  settle\(e, s\);/);
  assert.match(js, /\}\n  settle\(e, s\);\n  return s;/);
  assert.match(js, /for \(const r of m\.route\) \{/);
  // Off its feet onto a floor spot nobody else holds (it takes the free one beside).
  assert.match(js, /const spot = freeFloor\(e, read, here\);/);
  assert.match(js, /const spot = at\?\.f === "f" \? freeFloor\(e, read, at\) : at;/);
  // A feeder's moths over the exhibit: inside its air when it's closed, over its floor when not.
  assert.match(js, /const box = ex\.walls\?\.enclosed \? ex\.walls\.box : b && /);
  assert.match(js, /blockReader\(e\.dimension, \{ leaves: true, gecko: true \}\)/);
  assert.doesNotMatch(js, /minecraft:pushable/);
});

// ---------- 0.1.86: the game's rotation order and skin layout ----------
// The game turns a bone or box by [a, b, c] as Rz(-c) Ry(b) Rx(-a), x first (Blockbench's Bedrock codec), and lays
// a box's skin out the way Blockbench's cube.js does: the first side strip on the -x side, the front's and top's
// first column at -x, the top's first row at the back. gen/gameconv.py turned the poses drawn the other way
// (croc, lion, tiger, zebra, flamingo, hedgehog, raccoon, the rays) and gen/gameskin.py moved their skins' texels.
const r86 = (d) => (d * Math.PI) / 180;
function gameTurn([a, b, c], [x, y, z]) {
  const ca = Math.cos(r86(-a)), sa = Math.sin(r86(-a));
  [y, z] = [y * ca - z * sa, y * sa + z * ca];
  const cb = Math.cos(r86(b)), sb = Math.sin(r86(b));
  [x, z] = [x * cb + z * sb, -x * sb + z * cb];
  const cc = Math.cos(r86(-c)), sc = Math.sin(r86(-c));
  return [x * cc - y * sc, x * sc + y * cc, z];
}
const json86 = (p) => JSON.parse(readFileSync(new URL(p, import.meta.url), "utf8"));
const molang86 = (e) => Function("math", `return (${String(e).replace(/math\./g, "math.").replace(/query\.life_time|query\.anim_time/g, "0")});`)(
  { sin: (d) => Math.sin(r86(d)), cos: (d) => Math.cos(r86(d)), abs: Math.abs, max: Math.max, min: Math.min });

test("Game rotation: the croc's legs hang from the body's edges and splay out flat when it lies (0.1.111)", () => {
  const g = json86("../packs/RP/models/entity/crocodile.geo.json")["minecraft:geometry"][0];
  const bone = (n) => g.bones.find((b) => b.name === n);
  const body = bone("body").cubes[0];
  for (const n of ["legFL", "legFR", "legHL", "legHR"]) {
    const c = bone(n).cubes[0], p = bone(n).pivot;
    assert.ok(Math.abs(p[0]) >= body.origin[0] + body.size[0] - 0.5, `${n} pivots at the body's side`);
    assert.equal(c.origin[1], 0, `${n} stands on the ground`);
    assert.ok(p[1] >= c.origin[1] + c.size[1] - 0.01, `${n} hangs from its top`);
  }
  // Lying, each leg turns out to its own side (the left legs' z negative, as written for the game) till the foot lies flat.
  const lie = json86("../packs/RP/animations/crocodile.animation.json").animations["animation.zoocraft.crocodile.lie"].bones;
  for (const [n, s] of [["legFL", 1], ["legFR", -1], ["legHL", 1], ["legHR", -1]]) {
    const foot = gameTurn(lie[n].rotation.map(molang86), [0, -9, 0]);
    assert.ok(foot[0] * s > 7 && foot[1] > -4, `${n} lies out to its side (${foot})`);
  }
});

