// A small PNG reader (8-bit RGBA, not interlaced: how every ZooCraft skin is saved).
async function png86(p) {
  const { inflateSync } = await import("node:zlib");
  const b = readFileSync(new URL(p, import.meta.url));
  let o = 8, w = 0, h = 0; const idat = [];
  while (o < b.length) {
    const n = b.readUInt32BE(o), t = b.toString("latin1", o + 4, o + 8), d = b.subarray(o + 8, o + 8 + n);
    if (t === "IHDR") { w = d.readUInt32BE(0); h = d.readUInt32BE(4); assert.equal(d[8], 8); assert.equal(d[9], 6); assert.equal(d[12], 0); }
    if (t === "IDAT") idat.push(d);
    o += 12 + n;
  }
  const raw = inflateSync(Buffer.concat(idat)), px = Buffer.alloc(w * h * 4), st = w * 4;
  for (let y = 0; y < h; y++) {
    const f = raw[y * (st + 1)], row = raw.subarray(y * (st + 1) + 1, (y + 1) * (st + 1));
    for (let i = 0; i < st; i++) {
      const a = i >= 4 ? px[y * st + i - 4] : 0, up = y ? px[(y - 1) * st + i] : 0, ul = y && i >= 4 ? px[(y - 1) * st + i - 4] : 0;
      const pa = Math.abs(up - ul), pb = Math.abs(a - ul), pc = Math.abs(a + up - 2 * ul);
      const pr = pa <= pb && pa <= pc ? a : pb <= pc ? up : ul;
      px[y * st + i] = (row[i] + [0, a, up, (a + up) >> 1, pr][f]) & 255;
    }
  }
  return { w, h, at: (x, y) => px.subarray((y * w + x) * 4, (y * w + x) * 4 + 4) };
}

test("Game skin layout: every box's top meets its four sides the way the game folds it", async () => {
  // Along each of a top's four edges, the colour step between the top's edge texels and the side faces' top rows,
  // as the game lays them out (the top's first column at -x, its last row against the front face), against the
  // same with the top's rows the other way round (how the old skins were laid out).
  // 0.1.113: the lion's coat is flat now (the red panda's way), so its tops barely change front to back and the measure
  // can't tell the two layouts apart on it; the tiger is painted by the same code and keeps that rig covered, and the
  // raccoon (its ringed tail and masked head) takes the lion's place.
  for (const [geo, skin, k] of [["flamingo", "flamingo", 0.75], ["zebra", "zebra", 0.75], ["raccoon", "raccoon", 0.7], ["tiger", "tiger_amur_0", 0.7], ["crocodile", "crocodile_young_0", 0.85]]) {
    const g = json86(`../packs/RP/models/entity/${geo}.geo.json`)["minecraft:geometry"][0];
    const im = await png86(`../packs/RP/textures/entity/zoocraft/${skin}.png`), res = im.w / g.description.texture_width;
    const step = (p, q) => (p[3] < 128 || q[3] < 128 ? 0 : Math.abs(p[0] - q[0]) + Math.abs(p[1] - q[1]) + Math.abs(p[2] - q[2]));
    let asLaid = 0, turned = 0;
    for (const b of g.bones) for (const c of b.cubes ?? []) {
      if (!Array.isArray(c.uv)) continue;
      const [w, h, d] = c.size.map((q) => Math.round(q * res)), [u, v] = c.uv.map((q) => Math.round(q * res));
      if (!w || !h || !d) continue;
      const top = (i, r, t) => im.at(u + d + i, v + (t ? d - 1 - r : r));  // the top's texel (column i, row r)
      for (const t of [0, 1]) {
        let sum = 0;
        for (let i = 0; i < w; i++) {
          sum += step(top(i, d - 1, t), im.at(u + d + i, v + d));               // front edge: the front face's top row
          sum += step(top(i, 0, t), im.at(u + 2 * d + w + (w - 1 - i), v + d)); // back edge: the back face's, mirrored
        }
        for (let r = 0; r < d; r++) {
          sum += step(top(0, r, t), im.at(u + r, v + d));                       // -x edge: the first strip
          sum += step(top(w - 1, r, t), im.at(u + d + w + (d - 1 - r), v + d)); // +x edge: the second strip
        }
        if (t) turned += sum; else asLaid += sum;
      }
    }
    assert.ok(asLaid < k * turned, `${skin}: steps round the tops ${asLaid}, with the tops turned ${turned}`);
  }
});

test("Game skin layout: the otter's nose and the gecko's toe pads sit at the front of their tops", async () => {
  const ot = await png86("../packs/RP/textures/entity/zoocraft/otter.png");
  // snout 3 x 2 x 2 at (36, 9): its top is columns 38..40, rows 9..10, row 10 against the front face
  assert.ok(ot.at(39, 10)[0] < 60 && ot.at(40, 10)[0] < 60, "nose on the top's front row");
  assert.ok(ot.at(39, 9)[0] > 100, "pale behind it");
  for (const s of ["", "_slit", "_female", "_female_slit", "_hatchling", "_hatchling_slit"]) {
    const gk = await png86(`../packs/RP/textures/entity/zoocraft/warped_gecko${s}.png`);
    for (const [u, v] of [[42, 8], [50, 8], [0, 12], [8, 12]]) {  // feet 2 x 1 x 2: top at (u+2, v), 2 rows
      for (const x of [u + 2, u + 3]) {
        assert.ok(gk.at(x, v + 1)[1] > 200, `warped_gecko${s}: pad at the top's front (${x}, ${v + 1})`);
        assert.ok(gk.at(x, v)[1] < 200, `warped_gecko${s}: hide behind it (${x}, ${v})`);
      }
    }
  }
});
// ---------- 0.1.87: the Nether trio, the Cinder Boar ----------

test("Boar rules: what it roots, wallows and rubs in, the day, the sounder's lead, the piglets' mothers", async () => {
  const B = await import("../packs/BP/scripts/animals/boarRules.js");
  const T = BALANCE.boar;
  // Ground to root in: Warm Ash in a zoo; soul soil, soul sand, gravel and netherrack too in the wild.
  assert.equal(B.rootable("zoocraft:warm_ash", false), true);
  for (const id of ["minecraft:soul_soil", "minecraft:gravel", "minecraft:netherrack"]) {
    assert.equal(B.rootable(id, false), false, `zoo ${id}`);
    assert.equal(B.rootable(id, true), true, `wild ${id}`);
  }
  assert.equal(B.rootable("minecraft:dirt", true), false);
  assert.equal(B.rootable(undefined, true), false);
  // Mud: Thermal Mud in a zoo; mud, soul sand and soul soil too in the wild.
  assert.equal(B.wallowable("zoocraft:thermal_mud", false), true);
  assert.equal(B.wallowable("minecraft:mud", false), false);
  for (const id of ["minecraft:mud", "minecraft:soul_sand", "minecraft:soul_soil"]) assert.equal(B.wallowable(id, true), true, id);
  // What it rubs the mud off on: rock, bricks, a wall or a fence; never zoo equipment, glass, leaves or air.
  for (const [id, kind] of [["minecraft:basalt", "solid"], ["minecraft:stone_bricks", "solid"], ["minecraft:nether_brick_fence", "barrier"], ["minecraft:crimson_stem", "solid"]]) assert.equal(B.rubbable(id, kind), true, id);
  for (const [id, kind] of [["zoocraft:basic_feeder", "solid"], ["minecraft:glass", "solid"], ["minecraft:oak_leaves", "solid"], ["minecraft:glass_pane", "barrier"], ["minecraft:barrier", "solid"], ["minecraft:air", "air"]]) assert.equal(B.rubbable(id, kind), false, id);
  // The day: foraging through the morning and from the afternoon into the night, wallowing at midday, asleep late.
  assert.deepEqual([0, 2999, 3000, 6000, 8999, 9000, 17999, 18000, 22999, 23000, 24000 + 1000, -1000].map((t) => B.moodAt(t, T)), ["forage", "forage", "wallow", "wallow", "wallow", "forage", "forage", "sleep", "sleep", "forage", "forage", "forage"]);
  // What it goes looking for while foraging: mostly rooting; the feeder with food in it; a muddy one, a rock to rub on.
  assert.equal(B.pickInterest({ ground: true }, () => 0), "root");
  assert.equal(B.pickInterest({ ground: true }, () => 0.99), "wander");
  assert.equal(B.pickInterest({ ground: false }, () => 0), "wander", "no ash to root in");
  assert.equal(B.pickInterest({ ground: true, feeder: true }, () => 0.7), "feeder");
  assert.equal(B.pickInterest({ ground: true, muddy: true }, () => 0.9), "rub");
  // In the heat: the mud once, then the rub, then a lie-down.
  assert.equal(B.wallowStep({ wallowed: false, muddy: false, mud: true }), "mud");
  assert.equal(B.wallowStep({ wallowed: true, muddy: true, mud: true }), "rub");
  assert.equal(B.wallowStep({ wallowed: true, muddy: false, mud: true }), "rest");
  assert.equal(B.wallowStep({ wallowed: false, muddy: false, mud: false }), "rest", "no mud: lie down");
  // The lead: the oldest grown sow; with no sow, the oldest boar.
  const herd = [{ id: "p", adult: false, male: false, age: -1 }, { id: "b", adult: true, male: true, age: 9 }, { id: "s1", adult: true, male: false, age: 2 }, { id: "s2", adult: true, male: false, age: 7 }];
  assert.equal(B.leadOf(herd), "s2");
  assert.equal(B.leadOf(herd.filter((m) => m.male || !m.adult)), "b");
  assert.equal(B.leadOf([]), undefined);
  // A piglet's mother: its recorded one if she's here, else the nearest sow.
  const fam = [{ id: "s1", x: 0, z: 0, adult: true, male: false }, { id: "s2", x: 10, z: 0, adult: true, male: false }, { id: "p1", x: 9, z: 0, adult: false, motherId: "s1" }, { id: "p2", x: 9, z: 0, adult: false }, { id: "p3", x: 1, z: 0, adult: false, motherId: "gone" }];
  assert.deepEqual([...B.mothersOf(fam)], [["p1", "s1"], ["p2", "s2"], ["p3", "s1"]]);
  assert.equal(B.mothersOf(fam.filter((m) => !m.adult)).size, 0, "no sow about");
  // The acts the client knows (the entity's zoocraft:act runs 0 to 8).
  assert.deepEqual(B.ACT, { none: 0, root: 1, wallow: 2, rub: 3, rest: 4, sleep: 5, alert: 6, charge: 7, trot: 8 });
  assert.deepEqual(B.BOAR_TYPES, ["zoocraft:cinder_boar", "zoocraft:wild_cinder_boar"]);
});

test("Boar defence: the alert, the bluff and the real charge; where the sow and her piglets stand; walking off", async () => {
  const B = await import("../packs/BP/scripts/animals/boarRules.js");
  const T = BALANCE.boar;
  const R = T.alertRange;
  assert.equal(B.defenceStep({ dPiglet: 9, dSow: 9 }, R, T), "none");
  assert.equal(B.defenceStep({ dPiglet: 7, dSow: 9 }, R, T), "alert");
  assert.equal(B.defenceStep({ dPiglet: 7.5, dSow: 9 }, T.alertRangeZoo, T), "none", "a zoo sounder lets you closer");
  assert.equal(B.defenceStep({ dPiglet: 3.5, dSow: 5 }, R, T), "bluff");
  assert.equal(B.defenceStep({ dPiglet: 6, dSow: 3.9 }, R, T), "bluff", "too near her");
  assert.equal(B.defenceStep({ dPiglet: 1.9, dSow: 3 }, R, T), "real");
  assert.equal(B.defenceStep({ dPiglet: 20, dSow: 20, hurt: true }, R, T), "real", "they hurt one");
  // Between them: the sow guardGap from her piglets toward the threat, facing it; the piglets bunched behind.
  const piglets = [{ id: "a", x: 0, z: 0 }, { id: "b", x: 1, z: 0 }];
  const g = B.guardPlaces(piglets, { x: 0.5, z: 10 }, T);
  assert.deepEqual([g.sow.x, g.sow.z, g.sow.yaw], [0.5, T.guardGap, 0]);
  for (const id of ["a", "b"]) {
    const p = g.piglets.get(id);
    assert.ok(Math.abs(p.z + T.huddle) < 1e-9 && p.yaw === 0, id);
  }
  assert.ok(Math.abs(g.piglets.get("a").x - g.piglets.get("b").x) >= 0.5 - 1e-9, "side by side");
  assert.equal(B.guardPlaces(piglets, { x: 0.5, z: 2 }, T).sow.z, 1, "never past the threat");
  assert.deepEqual(B.backTo(piglets, { x: 0.5, z: 10 }, T), g.sow);
  // Walking off: straight away from them.
  assert.deepEqual(B.walkOffTo({ x: 0, z: 0 }, { x: 3, z: 0 }, T.walkOff), { x: -T.walkOff, z: 0, yaw: 90 });
  assert.deepEqual([B.chargeDamage(true, T), B.chargeDamage(false, T)], [T.boarDamage, T.sowDamage]);
  // The charge's end (grazerRules.js rushTo): a real one within reach, a bluff short of it.
  const real = B.rushTo({ x: 0, z: 0 }, { x: 6, z: 0 }, T.realShort);
  assert.ok(6 - real.x <= T.reach && 6 - B.rushTo({ x: 0, z: 0 }, { x: 6, z: 0 }, T.bluffShort).x > T.reach);
  assert.ok(B.stepsAlong({ x: 0, z: 0 }, { x: 4, z: 0 }, T.chargePace).length > B.stepsAlong({ x: 0, z: 0 }, { x: 4, z: 0 }, 1).length);
});

// The boar measure as exhibits.js runs it (geometry.js floodBoar): the walking measure with a plain reader, then the
// boar's flood with a boar reader, both from block ids (data/blocks.js classifyBlock). A block id ending "|open" is open.
async function boarMeasure(blocks, seed = { x: 0, y: 1, z: 0 }) {
  const { floodBoar, newBoarResult } = await import("../packs/BP/scripts/exhibits/geometry.js");
  const reader = (flags) => (x, y, z) => {
    const v = blocks.get(`${x},${y},${z}`) ?? (y <= 0 ? "minecraft:stone" : "minecraft:air");
    if (v === "unloaded") return "unloaded";
    const [id, open] = v.split("|");
    return classifyBlock(id, { isAir: id === "minecraft:air", isLiquid: false, open: open === "open", ...flags });
  };
  const walk = newResult(seed);
  const w = floodTerrestrial(reader({}), seed, { halfWidth: 32, halfHeight: 16, maxDrop: 3, minHeight: 3, cellsPerYield: 1e9 }, walk);
  while (!w.next().done);
  const out = newBoarResult();
  const f = floodBoar(reader({ boar: true }), walk.cells, { maxDrop: 3, rise: BALANCE.climb.rise, cellsPerYield: 7 }, out);
  while (!f.next().done);
  return { walk, out };
}

test("Boar strong walls: wooden fences, gates and doors lead out; stone, brick, nether brick, bars and iron hold", async () => {
  const c = (id, extra = {}) => classifyBlock(id, { isAir: false, isLiquid: false, open: false, ...extra });
  // The boar reader: wood it breaks is "weak"; everyone else still sees a barrier.
  for (const id of ["minecraft:oak_fence", "minecraft:fence", "minecraft:spruce_fence", "minecraft:crimson_fence", "minecraft:bamboo_fence", "minecraft:pale_oak_fence", "minecraft:fence_gate", "minecraft:dark_oak_fence_gate", "minecraft:warped_fence_gate", "minecraft:wooden_door", "minecraft:spruce_door", "minecraft:mangrove_door", "minecraft:cherry_door"]) {
    assert.equal(c(id, { boar: true }), "weak", id);
    assert.equal(c(id), "barrier", `${id} without a boar reader`);
  }
  for (const id of ["minecraft:nether_brick_fence", "minecraft:cobblestone_wall", "minecraft:blackstone_wall", "minecraft:iron_bars", "minecraft:iron_door", "minecraft:copper_door", "zoocraft:keeper_gate", "zoocraft:end_fence"]) assert.equal(c(id, { boar: true }), "barrier", id);
  assert.equal(c("minecraft:oak_trapdoor", { boar: true }), "solid", "a trapdoor isn't a door");
  assert.equal(c("minecraft:fence_gate", { boar: true, open: true }), "gate_open", "an open gate is a gap to anyone");
  // Thermal Mud: its own only for a reader that asks; a whole block to a gecko.
  assert.equal(c("zoocraft:thermal_mud", { thermalMud: true }), "thermal_mud");
  assert.equal(c("zoocraft:thermal_mud"), "solid");
  assert.equal(c("zoocraft:thermal_mud", { gecko: true }), "solid");
  // Pens 9 x 9 inside (x and z -4 to 4 is the ring), walls 1 or 2 high.
  const pen = (id, h = 1) => ringOf(new Map(), id, 4, 1, h);
  for (const [id, h] of [["minecraft:stone_bricks", 2], ["minecraft:nether_brick_fence", 1], ["minecraft:cobblestone_wall", 1], ["minecraft:iron_bars", 1]]) {
    const m = await boarMeasure(pen(id, h));
    assert.equal(m.walk.enclosed, true, id);
    assert.deepEqual([m.out.proof, m.out.via, m.out.weak], [true, undefined, 0], id);
  }
  // Oak fences: shut to walkers, open to a boar. The way out from the floor, a block at a time, through the fence.
  for (const h of [1, 2]) {
    const m = await boarMeasure(pen("minecraft:oak_fence", h));
    assert.equal(m.walk.enclosed, true);
    const { proof, path, escape, via, weak } = m.out;
    assert.equal(proof, false, `${h} high`);
    assert.equal(m.walk.cells.get(`${path[0].x},${path[0].y},${path[0].z}`), "land", "it sets off from the floor");
    assert.deepEqual(path[path.length - 1], escape);
    assert.ok(Math.max(Math.abs(escape.x), Math.abs(escape.z)) > 4, "and ends outside the fence");
    for (let i = 1; i < path.length; i++) assert.ok(Math.abs(path[i].x - path[i - 1].x) + Math.abs(path[i].z - path[i - 1].z) <= 1);
    assert.equal(Math.max(Math.abs(via.x), Math.abs(via.z)), 4, "the fence it breaks");
    assert.equal(via.y, 1);
    assert.ok(path.some((p) => p.x === via.x && p.z === via.z));
    assert.ok(weak >= 28, `${weak} fence blocks beside the floor`);
  }
  // A wooden door in a stone wall leads out; an iron one doesn't.
  const door = (id) => pen("minecraft:stone_bricks", 2).set("4,1,0", id).set("4,2,0", id);
  const wood = await boarMeasure(door("minecraft:wooden_door"));
  assert.deepEqual([wood.out.proof, wood.out.via], [false, { x: 4, y: 1, z: 0 }]);
  assert.deepEqual(wood.out.escape, { x: 5, y: 1, z: 0 });
  assert.equal(wood.out.weak, 2);
  assert.equal((await boarMeasure(door("minecraft:iron_door"))).out.proof, true);
  assert.equal((await boarMeasure(door("minecraft:spruce_fence_gate"))).out.proof, false);
  // Wood beside the floor with strong walls behind it holds them (the clipboard counts it).
  const lined = ringOf(ringOf(new Map(), "minecraft:stone_bricks", 4, 1, 2), "minecraft:oak_fence", 3, 1, 1);
  const inner = await boarMeasure(lined);
  assert.equal(inner.out.proof, true);
  assert.ok(inner.out.weak >= 20, `${inner.out.weak}`);
  // Past the fence, ground not loaded yet holds it, as the climb measures.
  const edge = ringOf(pen("minecraft:oak_fence"), "unloaded", 5, 1, 2);
  assert.equal((await boarMeasure(edge)).out.proof, true);
  // Thermal Mud in the floor: counted by the walking measure, and stood on like any block.
  const mud = boxOf(pen("minecraft:stone_bricks", 2), "zoocraft:thermal_mud", [-3, -1], [0, 0], [-3, -2]);
  const r = newResult({ x: 0, y: 1, z: 0 });
  const read = (x, y, z) => {
    const id = mud.get(`${x},${y},${z}`) ?? (y <= 0 ? "minecraft:stone" : "minecraft:air");
    return classifyBlock(id, { isAir: id === "minecraft:air", isLiquid: false, open: false, thermalMud: true });
  };
  const it = floodTerrestrial(read, r.seed, { halfWidth: 32, halfHeight: 16, maxDrop: 3, minHeight: 3, cellsPerYield: 1e9, countThermalMud: true }, r);
  while (!it.next().done);
  assert.deepEqual([r.enclosed, r.thermalMudCells, r.landCells], [true, 6, 49]);
  const r2 = newResult({ x: 0, y: 1, z: 0 });
  const it2 = floodTerrestrial(read, r2.seed, { halfWidth: 32, halfHeight: 16, maxDrop: 3, minHeight: 3, cellsPerYield: 1e9 }, r2);
  while (!it2.next().done);
  assert.equal(r2.thermalMudCells, 0, "only when asked");
  // The exhibit wiring.
  const src = (p) => readFileSync(new URL(p, import.meta.url), "utf8");
  const ex = src("../packs/BP/scripts/exhibits/exhibits.js");
  assert.match(ex, /if \(!out\.error && \(!species \|\| anyWants\(ex, "boarProof"\)\)\) \{\n {14}boar = newBoarResult\(\);\n {14}yield\* floodBoar\(blockReader\(dim\(ex\.dimension\), \{ boar: true \}, memo\), out\.cells, \{ maxDrop: opts\.maxDrop, rise: BALANCE\.climb\.rise, cellsPerYield: opts\.cellsPerYield \}, boar\);/);
  assert.match(ex, /resolve\(applyValidation\(exId, start, out, air, climb, croc, ape, walls, boar(, soul(, hops(, crevices(, rock(, chorus(, tortoise(, okapi(, molebear(, skulker(, unicorn(, dragon(, griffin(, stag(, snow(, sloth(, mobPen, mobFloor(, bamboo(, goat(, pond(, tank(, pool(, bees(, parrots(, cats)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?\)\);/);
  assert.match(ex, /stem: wants\("rubStem"\), thermalMud: wants\("wallow"\)(, substrate: wants\("substrate"\)( \|\| wants\("mineralBed"\)( \|\| wants\("burrows"\)( \|\| wants\("substrateNest"\))?)?)?)?(, sandBed: wants\("sandBed"\)( \|\| wants\("desert"\)( \|\| wants\("sandFloor"\))?)?(, seagrass: wants\("seagrass"\)(, hay: wants\("hay"\)(, mycelium: wants\("mycelium"\)(, dig: wants\("digBed"\)(, sulfur: wants\("sulfurFloor"\))?)?)?)?)?)? \}, memo\);/);
  assert.match(ex, /countThermalMud: wants\("wallow"\),/);
  assert.match(ex, /ex\.thermalMudCells = anyWants\(ex, "wallow"\) \? r\.thermalMudCells : undefined;/);
  assert.match(ex, /ex\.boarWalls = boar \? \{ proof: boar\.proof, via: boar\.via, path: boar\.path && boar\.path\.length <= 64 \? boar\.path\.map\(\(p\) => \[p\.x, p\.y, p\.z\]\) : undefined, weak: boar\.weak \} : undefined;/);
  assert.match(ex, /if \(boarsOut && !climbsOut && !apesOut && !wallsOut && !openGates\.length && !r\.escape\) issues\.push\(boarIssue\(pluralOf\(boars\[0\]\), boar\)\);/);
  assert.match(ex, /&& !climbsOut && !apesOut && !wallsOut && !boarsOut( && !hopsOut( && !goatsOut( && !frogsOut)?)?)?;/, "boars that could break out: unsafe");
  // The pen as built: a broken fence floods the walking measure out, so the outside watch keeps the box that stayed in.
  assert.match(ex, /penBox: undefined,/);
  assert.match(ex, /ex\.bbox = r\.bbox;\n  \/\/ [^\n]*\n  if \(r\.enclosed \|\| !ex\.penBox\) ex\.penBox = r\.enclosed \? r\.bbox : undefined;/);
  assert.match(src("../packs/BP/scripts/animals/animals.js"), /const b = ex\.penBox \?\? ex\.bbox;/);
  assert.match(ex, /if \(species\.boarProof\) \{\n    if \(!ex\.boarWalls\) return .*\n    return ex\.boarWalls\.proof \? undefined : boarIssue\(pluralOf\(species\), ex\.boarWalls\);/, "a boar moves in only behind strong walls");
  assert.match(src("../packs/BP/scripts/platform/mc.js"), /climb, ape, nylium, stem, gecko, thermalMud, boar(, substrate(, thin(, rock(, sandBed(, seagrass(, hay(, mycelium(, dig(, sulfur)?)?)?)?)?)?)?)?)? \};/);
});

test("Boar care: Thermal Mud caps comfort; the warnings, the clipboard, the issue, the species, its home ground", async () => {
  const W = await import("../packs/BP/scripts/animals/welfare.js");
  const B = await import("../packs/BP/scripts/animals/boarRules.js");
  const C = await import("../packs/BP/scripts/quests/conservationRules.js");
  const R = await import("../packs/BP/scripts/equipment/rules.js");
  const sp = SPECIES["zoocraft:cinder_boar"];
  const T = BALANCE.boar;
  const day = BALANCE.clock.dayLength;
  const g = { needs: { satiety: 90, comfort: 90, cleanliness: 90, enrichment: 90, social: 90 }, health: 100 };
  W.simulateAnimal(g, sp, { exhibitCleanliness: 100, spaceRatio: 1, groupSize: 3, feederUnits: 20, heat: true, wallow: false }, day * 20, BALANCE);
  assert.equal(g.needs.comfort, T.wallowComfortCap);
  assert.deepEqual(W.comfortCauses({ spaceRatio: 1, wallow: false, ash: false }, BALANCE), ["ash", "wallow"]);
  assert.match(W.adviceFor("comfort", sp, ["ash", "wallow"]), /Warm Ash in the floor to root in \(8 blocks\) and Thermal Mud to wallow in \(4 blocks in the floor\): without it the heat is too much for them/);
  const digger = Object.values(SPECIES).find((s) => s.ash && !s.wallow);
  assert.match(W.adviceFor("comfort", digger, ["ash"]), /a Warm Ash bed to dig in/, `${digger.id}'s advice as before`);
  // Thermal Mud: not measured yet passes.
  assert.equal(B.hasThermalMud(sp, {}), true);
  assert.equal(B.hasThermalMud(sp, { thermalMudCells: 3 }), false);
  assert.equal(B.hasThermalMud(sp, { thermalMudCells: 4 }), true);
  assert.equal(B.hasThermalMud(SPECIES["zoocraft:crimson_grazer"], { thermalMudCells: 0 }), true, "not a grazer's");
  const a = (name, sex, juvenile = false) => ({ name, sex, juvenile });
  const warn = B.boarWarnings({ thermalMudCells: 2 }, [a("Snuffle", "male"), a("Rooter", "male"), a("Tufa", "male", true)], "Cinder Boars", sp);
  assert.equal(warn.length, 2);
  assert.match(warn[0].text, /^Cinder Boars need Thermal Mud to wallow in: at least 4 blocks in the exhibit floor \(2 now\)\. .*Craft it from mud, soul soil and a snowball\.$/);
  assert.match(warn[1].text, /^Snuffle and Rooter are grown boars: boars live apart/, "a young boar is no rival yet");
  assert.deepEqual(B.boarWarnings({}, [a("Snuffle", "male"), a("Huff", "female")], "Cinder Boars", sp), [], "nothing before the measure");
  assert.deepEqual(B.boarLines({ thermalMudCells: 5, boarWalls: { proof: true, weak: 3 } }, [a("Huff", "female"), a("Tufa", "male", true)], sp), ["§fThermal Mud: §75 of 4 blocks", "§fStrong walls: §ayes§7, 3 wooden blocks beside the floor, with strong walls behind", "§fSounder: §72 (1 piglet)"]);
  assert.deepEqual(B.boarLines({ thermalMudCells: 1, boarWalls: { proof: false, via: { x: 4, y: 1, z: 0 } } }, [], sp), ["§fThermal Mud: §71 of 4 blocks §c(too hot without it)", "§fStrong walls: §cno§7, they'd break through the wood at 4 1 0", "§fSounder: §70"]);
  assert.match(B.boarLines({}, [], sp)[0], /not measured yet/);
  assert.equal(B.boarLines({}, [], sp)[1], "§fStrong walls: §7not measured yet");
  assert.equal(B.boarIssue("Cinder Boars", { via: { x: 4, y: 1, z: 0 } }), "Cinder Boars break through wooden fences, gates and doors: the wooden fence, gate or door at 4 1 0 leads out. Build the walls of stone, brick or nether brick (walls or fences), iron bars or glass, with a Keeper Gate to go in by.");
  // From a Basic Feeder: Ember or Fungal Rations.
  assert.equal(R.reachesFeeder(sp, {}), true);
  assert.equal(R.reachesFeeder(sp, { thermal: true }), false);
  const { RATIONS } = await import("../packs/BP/scripts/data/items.js");
  assert.deepEqual(["zoocraft:ember_ration", "zoocraft:fungal_ration"].map((r) => sp.dietTags.includes(RATIONS[r].diet)), [true, true]);
  // Let out on basalt, blackstone, netherrack or soul soil; the others' home ground as before.
  assert.equal(C.groundText(sp), "on basalt, blackstone, netherrack or soul soil");
  for (const id of ["minecraft:basalt", "minecraft:blackstone", "minecraft:netherrack", "minecraft:soul_soil"]) assert.equal(C.groundOk(sp, { id, isAir: false, isLiquid: false }), true, id);
  assert.equal(C.groundOk(sp, { id: "minecraft:crimson_nylium", isAir: false, isLiquid: false }), false);
  assert.equal(C.groundOk(SPECIES["zoocraft:crimson_grazer"], { id: "minecraft:crimson_nylium", isAir: false, isLiquid: false }), true);
  assert.equal(C.groundOk(SPECIES["zoocraft:warped_gecko"], { id: "minecraft:basalt", isAir: false, isLiquid: false }), false);
  // The species: a Nether walker in a sounder, a Thermal Carrier, its sexes on the mob.
  assert.deepEqual([sp.habitatProfile, sp.movementProfile, sp.carrierProfile, sp.dietTags, sp.baitItem, sp.rationUnitsPerParkDay, sp.origin, sp.homeDimension, sp.wildSource], ["sounder", "terrestrial", "thermal", ["ember", "fungus"], "zoocraft:ember_ration", 2, "custom_nether", "minecraft:nether", "zoocraft:wild_cinder_boar"]);
  assert.equal(sp.heat && sp.boarProof && sp.oneMale && sp.sexLook && sp.social.prefersCompany, true);
  assert.deepEqual([sp.ash.minCells, sp.wallow.minCells], [8, 4]);
  assert.equal(Boolean(sp.climbs || sp.ape || sp.clings || sp.nocturnal || sp.dangerous || sp.flies), false, "its own measure, not the raccoon's, the gorilla's or the gecko's");
  assert.deepEqual(sp.observe, ["spot", "root", "wallow", "scrub"]);
  assert.deepEqual([sp.breeding.litter, sp.breeding.litterMax, sp.breeding.juvenileScale, sp.breeding.young, sp.breeding.youngPlural], [3, 5, 0.35, "piglet", "piglets"]);
  const others = Object.values(SPECIES).filter((s) => s !== sp).flatMap((s) => s.names ?? []);
  assert.deepEqual(sp.names.filter((n) => others.includes(n)), [], "names of its own");
  assert.equal(new Set(sp.names).size, 16);
  const sounder = HABITAT_PROFILES.sounder;
  assert.deepEqual([sounder.baseArea, sounder.extraArea, sounder.minHeight, Boolean(sounder.aerial)], [120, 24, 3, false]);
  assert.equal(requiredArea(sounder, 3), 168);
  const I = await import("../packs/BP/scripts/data/items.js");
  assert.equal(I.BLOCKS.thermalMud, "zoocraft:thermal_mud");
  assert.deepEqual(validateData(), []);
  // The wiring: the cap, the warnings, the clipboard.
  const src = (p) => readFileSync(new URL(p, import.meta.url), "utf8");
  const animals = src("../packs/BP/scripts/animals/animals.js");
  assert.match(animals, /const wallow = hasThermalMud\(species, ex\);/);
  assert.match(animals, /walls, hide, males, wallow(, soul(, bed(, pads(, crevices, mineral(, rock, burrows(, flowers, dim(, endPlants, warmPads, retreat(, sand(, seagrass(, lush, clay(, burrow(, sculk, shriek(, bloom(, warmth(, hoard(, trunk(, snow(, soulfloor, beam(, mobfloor(, hay(, run, groomed: [\w.()]+(, rockLedges(, desertSand, desertShade(, lilyPads(, waterPlants, tankFloor(, deepStretch, openWater(, beeFlowers, beeHives(, restSpots(, sandFloor, chill(, mycelium(, digBed(, batRoosts, batFlight(, coolBiome(, skyView(, sulfur)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)? \}, BALANCE\);/);
  assert.match(animals, /if \(species\.wallow\) out\.push\(\.\.\.boarWarnings\(ex, residents, pluralOf\(species\), species\)\);/);
  assert.match(src("../packs/BP/scripts/ui/clipboard.js"), /\.\.\.\(sounder \? boarLines\(ex, animalsIn\(ex\)\.filter\(\(a\) => a\.speciesId === sounder\.id\), sounder\) : \[\]\),/);
});

test("Boar Field Journal: rooting, wallowing, rubbing the mud off", async () => {
  const { TASKS, tasksSeen, levelOf } = await import("../packs/BP/scripts/discovery/rules.js");
  const sp = SPECIES["zoocraft:cinder_boar"];
  assert.deepEqual(tasksSeen(sp, ["spot"], { rooting: true, wallowing: false, scrubbing: true }), ["root", "scrub"]);
  assert.deepEqual(tasksSeen(sp, ["spot", "root", "scrub"], { wallowing: true }), ["wallow"]);
  assert.deepEqual(tasksSeen(sp, ["spot"], { clinging: true, ringing: true }), [], "a gecko's and a grazer's tasks aren't a boar's");
  assert.equal(levelOf(sp, ["spot", "root", "wallow", "scrub"]), 3);
  for (const t of sp.observe) assert.ok(TASKS[t], t);
  const src = (p) => readFileSync(new URL(p, import.meta.url), "utf8");
  const disc = src("../packs/BP/scripts/discovery/discovery.js");
  assert.match(disc, /return \{ rooting: act === BOAR_ACT\.root, wallowing: act === BOAR_ACT\.wallow, scrubbing: act === BOAR_ACT\.rub \};/);
  assert.match(disc, /\/\*\* @returns \{\{ rooting\?: boolean, wallowing\?: boolean, scrubbing\?: boolean \}\} \*\/\nfunction boarSight/, "one return type (tsc)");
  assert.match(disc, /\.\.\.boarSight\(species, hit\)/);
  const journal = src("../packs/BP/scripts/ui/fieldJournal.js");
  assert.match(journal, /if \(sp\.wallow\) \{/);
  assert.match(journal, /§7Strong walls: they break through wooden fences, gates and doors/);
});

test("Boar files: the mob, the wild one, the spawn, the skins, the acts, Thermal Mud and the wiring", async () => {
  const src = (p) => readFileSync(new URL(p, import.meta.url), "utf8");
  const json = (p) => JSON.parse(src(p));
  const B = await import("../packs/BP/scripts/animals/boarRules.js");
  const ACTS = Math.max(...Object.values(B.ACT));
  const SEEK = ["zoocraft:seek_feeder", "zoocraft:seek_root", "zoocraft:seek_mud"];
  for (const name of ["cinder_boar", "wild_cinder_boar"]) {
    const wild = name.startsWith("wild");
    const be = json(`../packs/BP/entities/${name}.json`)["minecraft:entity"];
    assert.equal(be.description.identifier, `zoocraft:${name}`);
    assert.deepEqual(be.description.properties["zoocraft:act"], { type: "int", range: [0, ACTS], default: 0, client_sync: true }, name);
    assert.deepEqual(be.description.properties["zoocraft:muddy"], { type: "bool", default: false, client_sync: true }, name);
    for (const ev of ["zoocraft:move", "zoocraft:still", "zoocraft:follow", "zoocraft:lead", "zoocraft:seek_none", "zoocraft:sex_0", "zoocraft:sex_1", ...SEEK]) assert.ok(be.events[ev], `${name} ${ev}`);
    const c = be.components;
    assert.ok(c["minecraft:fire_immune"] && c["minecraft:navigation.walk"] && c["minecraft:physics"] && c["minecraft:movement"], name);
    assert.ok(c["minecraft:type_family"].family.includes("cinder_boar"), `${name} family`);
    assert.deepEqual(c["minecraft:behavior.tempt"].items, BALANCE.boar.bait);
    assert.equal(JSON.stringify(be).includes('"minecraft:pushable"'), false, "1.26.10: never minecraft:pushable");
    // Each body group holds the walking speed and physics the base has (0.1.70: removing a group removes them).
    for (const g of ["zoocraft:moving", "zoocraft:still"]) assert.ok(be.component_groups[g]["minecraft:movement"] && be.component_groups[g]["minecraft:physics"], `${name} ${g}`);
    assert.equal(be.component_groups["zoocraft:still"]["minecraft:movement"].value, 0);
    // Its random stroll only in the walking body: standing still drops it, so it doesn't walk back to where it was going.
    assert.equal(be.components["minecraft:behavior.random_stroll"], undefined, name);
    assert.ok(be.component_groups["zoocraft:moving"]["minecraft:behavior.random_stroll"], name);
    for (const [ev, keep, drop] of [["zoocraft:move", "zoocraft:moving", "zoocraft:still"], ["zoocraft:still", "zoocraft:still", "zoocraft:moving"]]) assert.deepEqual([be.events[ev].add.component_groups, be.events[ev].remove.component_groups], [[keep], [drop]]);
    // What the engine walks it to: one seek group at a time; the blocks the script then roots or wallows in. A rock or a
    // wall to rub on the script finds (rubSpot): basalt or stone bricks are as often the floor a goal would take.
    for (const g of SEEK) {
      assert.deepEqual(be.events[g].add.component_groups, [g]);
      assert.deepEqual(be.events[g].remove.component_groups.sort(), SEEK.filter((o) => o !== g).sort());
    }
    assert.deepEqual(be.events["zoocraft:seek_none"].remove.component_groups.sort(), [...SEEK].sort());
    const targets = (g) => be.component_groups[g]["minecraft:behavior.move_to_block"].target_blocks;
    for (const id of targets("zoocraft:seek_root")) assert.ok(B.rootable(id, wild), `${name} roots in ${id}`);
    for (const id of targets("zoocraft:seek_mud")) assert.ok(B.wallowable(id, wild), `${name} wallows in ${id}`);
    assert.equal(be.component_groups["zoocraft:seek_rub"], undefined);
    assert.deepEqual(targets("zoocraft:seek_feeder"), ["zoocraft:basic_feeder"]);
    // The others follow the lead (the tag the script puts on it); piglets their mother.
    assert.match(JSON.stringify(be.component_groups["zoocraft:following"]["minecraft:behavior.follow_mob"]), new RegExp(B.LEAD_TAG));
    assert.ok(be.component_groups["zoocraft:juvenile"]["minecraft:behavior.follow_parent"] && be.component_groups["zoocraft:juvenile"]["minecraft:is_baby"]);
    assert.equal(be.component_groups["zoocraft:sex_1"]["minecraft:mark_variant"].value, 1);
    const rp = json(`../packs/RP/entity/${name}.entity.json`)["minecraft:client_entity"].description;
    assert.equal(rp.geometry.default, "geometry.zoocraft.cinder_boar");
    for (const t of Object.values(rp.textures)) assert.ok(readdirSync(new URL("../packs/RP/textures/entity/zoocraft/", import.meta.url)).includes(`${t.split("/").pop()}.png`), t);
  }
  const zoo = json("../packs/BP/entities/cinder_boar.json")["minecraft:entity"];
  assert.ok(zoo.components["minecraft:type_family"].family.includes("zoocraft_animal"));
  assert.ok(zoo.components["minecraft:persistent"]);
  assert.ok(zoo.events["zoocraft:juvenile"] && zoo.events["zoocraft:home_8"] && zoo.events["zoocraft:home_32"]);
  const wildBe = json("../packs/BP/entities/wild_cinder_boar.json")["minecraft:entity"];
  assert.ok(wildBe.components["minecraft:despawn"]);
  const spawn = json("../packs/BP/spawn_rules/wild_cinder_boar.json")["minecraft:spawn_rules"];
  assert.match(JSON.stringify(spawn.conditions[0]["minecraft:biome_filter"]), /basalt_deltas.*nether_wastes/);
  assert.ok(spawn.conditions[0]["minecraft:spawns_on_block_filter"].includes("minecraft:soul_soil"));
  assert.equal(spawn.conditions[0]["minecraft:herd"].event, "zoocraft:piglet", "a sounder with piglets");
  assert.equal(spawn.conditions[1]["minecraft:herd"].event, "zoocraft:sex_1", "an old boar alone");
  // The client: an animation for every act; muddy, asleep and piglet skins; tusks on a boar; nothing cubic (0.1.78).
  const ctrl = src("../packs/RP/animation_controllers/cinder_boar.animation_controllers.json");
  for (let a = 1; a <= ACTS; a++) assert.ok(ctrl.includes(`query.property('zoocraft:act') == ${a}`), `act ${a}`);
  const anims = json("../packs/RP/animations/cinder_boar.animation.json").animations;
  for (const a of ["walk", "trot", "idle", "root", "wallow", "rub", "rest", "sleep", "alert", "charge", "look_at_target"]) assert.ok(anims[`animation.zoocraft.cinder_boar.${a}`], a);
  assert.doesNotMatch(JSON.stringify(anims), /"lerp_mode"|catmullrom/, "nothing the client precomputes as cubic (0.1.78)");
  const geo = json("../packs/RP/models/entity/cinder_boar.geo.json")["minecraft:geometry"][0];
  const bones = new Set(geo.bones.map((b) => b.name));
  assert.ok(bones.has("tusks"));
  for (const a of Object.values(anims)) for (const b of Object.keys(a.bones ?? {})) assert.ok(bones.has(b), `animates a bone the model has: ${b}`);
  const rc = src("../packs/RP/render_controllers/cinder_boar.render_controllers.json");
  assert.match(rc, /query\.property\('zoocraft:muddy'\) \? 2 : 0/);
  assert.match(rc, /\(query\.property\('zoocraft:act'\) == 5\) \? 1 : 0/, "eyes shut asleep");
  assert.match(rc, /\{"tusks": "!query\.is_baby && query\.mark_variant == 1"\}/);
  // Thermal Mud: 4 mud, a soul soil and a snowball make 4, at a crafting table or the Zoo Workshop.
  const block = json("../packs/BP/blocks/thermal_mud.json")["minecraft:block"];
  assert.equal(block.description.identifier, "zoocraft:thermal_mud");
  const recipe = json("../packs/BP/recipes/zoocraft_thermal_mud.json")["minecraft:recipe_shapeless"];
  assert.deepEqual(recipe.result, { item: "zoocraft:thermal_mud", count: 4 });
  assert.deepEqual(recipe.ingredients.map((i) => i.item).sort(), ["minecraft:mud", "minecraft:mud", "minecraft:mud", "minecraft:mud", "minecraft:snowball", "minecraft:soul_soil"]);
  assert.ok(recipe.tags.includes("zoocraft_workshop"));
  assert.ok(json("../packs/RP/textures/terrain_texture.json").texture_data.zoocraft_thermal_mud);
  assert.ok(readdirSync(new URL("../packs/RP/textures/blocks/zoocraft/", import.meta.url)).includes("thermal_mud.png"));
  const lang = src("../packs/RP/texts/en_US.lang");
  for (const l of ["entity.zoocraft:cinder_boar.name=Cinder Boar", "entity.zoocraft:wild_cinder_boar.name=Wild Cinder Boar", "tile.zoocraft:thermal_mud.name=Thermal Mud"]) assert.ok(lang.includes(l), l);
  // The wiring: the loops, found by type; the wood it breaks is only ever what a boar reader calls weak, and only
  // with mobGriefing on.
  const main = src("../packs/BP/scripts/main.js");
  assert.match(main, /loop\("boars", 10, \d+, \(\) => tickBoars\(system\.currentTick\)\)/);
  assert.match(main, /loop\("boarmove", 1, \d+, tickBoarMoves\)/);
  assert.match(main, /initBoars\(\);/);
  const js = src("../packs/BP/scripts/animals/boar.js");
  assert.match(js, /entitiesNear\(player\.dimension, player\.location, RANGE, BOAR_TYPES\)/, "found by type");
  assert.match(js, /griefing = world\.gameRules\.mobGriefing;/);
  assert.match(js, /const read = blockReader\(e\.dimension, \{ boar: true \}\);\n  const broken = \[\];\n  for \(const p of path\.slice\(at, at \+ 2\)\) \{\n    for \(const y of \[p\.y, p\.y \+ 1\]\) \{\n      if \(read\(p\.x, y, p\.z\) !== "weak"\) continue;/);
  assert.equal((js.match(/setblock /g) ?? []).length, 1);
  assert.match(js, /for \(const b of broken\) blockChanged\(e\.dimension\.id, b\);/, "the exhibit is measured again");
  assert.match(js, /\{ entityTypes: \["zoocraft:wild_cinder_boar"\] \}/);
  // Busy defending, the sow and her piglets; the rest of the sounder carries on.
  assert.match(js, /if \(threat && mothers\.size\) busy = defend\(/);
  assert.match(js, /if \(busy\.has\(m\.id\)\) continue;/);
  assert.doesNotMatch(js, /minecraft:pushable|runInterval|seek_rub|seek\(e, s, "rub"\)/);
  assert.match(js, /const to = rubSpot\(m, here, T\);/);
  assert.match(js, /if \(goRub\(m, cellOf\(e\.location\), now, T\)\) return;/);
  // Now and then a grown one goes to try the wood (probe), and the butting news comes at most every buttTellEvery.
  assert.match(js, /ex\?\.boarWalls\?\.proof === false && ex\.boarWalls\.path\?\.length && Math\.random\(\) < T\.probeChance\) s\.interest = "probe";/);
  assert.match(js, /if \(s\.interest === "probe" && !strayed && ex && probe\(m, ex, here, T\)\) return;/);
  assert.match(js, />= T\.buttTellEvery\) \{/);
  // Trotting off, it turns up to 90 degrees either side when straight away is blocked (a pillar behind it), takes the
  // way that gets it farthest when boxed in, and stays put when none does.
  assert.match(js, /for \(const turn of \[0, 30, -30, 60, -60, 90, -90\]\)/);
  assert.match(js, /charge\(m, p, !peaceful\(\), \(\) => walkOff\(m, at, T\), T\);/);
  assert.match(js, /const to = awayFrom\(m, at, T\);\n      if \(!to\) return false;/);
  assert.equal(BALANCE.boar.shyAgain, 40);
  // Trots and charges go round something in the way (a basalt pillar) by one corner; a sow someone came round her
  // piglets past goes back between them.
  assert.match(js, /const way = to\.length >= 0\.5 \? routeTo\(m, from, to, T\.chargePace\)/);
  assert.match(js, /\? routeTo\(m, from, to, T\.trotPace\)\.pts : \[\];/);
  assert.match(js, /for \(const off of \[1, -1, 1\.5, -1\.5, 2, -2, 3, -3\]\)/);
  assert.match(js, /if \(sow\.s\.phase === "guard" && dSow > dPiglet && now >= h\.guard\.placeAt\) \{/);
  // Guarding, her brood stays the piglets she stood up for (a wild piglet's mother is the nearest sow).
  assert.match(js, /const brood = kept\.length \? kept : piglets\.filter\(\(q\) => mothers\.get\(q\.id\) === sow\.id\);/);
  // At the edge of the mud or the ash (a move_to_block goal ends goal_radius from the block's middle): a step onto
  // the mud, the snout into the ash.
  assert.match(js, /const mud = mudCell\(e, here, wild\);/);
  assert.match(js, /const at = rootCell\(e, here, wild\);/);
  // Through the wood it trots on outRun blocks, clear of the exhibit.
  assert.match(js, /const on = \{ x: gap\.x \+ dir\.x \* T\.outRun, z: gap\.z \+ dir\.z \* T\.outRun \};/);
  assert.ok(BALANCE.boar.outRun > 0);
  // A wild grown boar lives alone and carries no lead tag, so no sounder near it follows it.
  assert.match(js, /if \(!isBaby\(b\.e\) && markOf\(b\.e\) === 1\) groups\.set\(`wild:\$\{b\.e\.id\}`, \[b\]\);/);
  assert.match(js, /role\(m, members\.length === 1 \? "alone" : m\.id === leadId \? "lead" : "follow"\)/);
  assert.match(js, /e\.triggerEvent\(want === "follow" \? "zoocraft:follow" : "zoocraft:lead"\);/);
  // No one near: back on its feet with its own walking.
  assert.match(js, /function forget\(id\) \{\n  const s = state\.get\(id\);[\s\S]*?body\(e, s, "move"\);\n    seek\(e, s, "none"\);\n    setAct\(e, ACT\.none\);/);
});

