// ---------- 0.1.88: the Nether pair, the Soul Moth ----------

test("Moth rules: the day, the soul lights and host plants, the acts", async () => {
  const M = await import("../packs/BP/scripts/animals/mothRules.js");
  const T = BALANCE.moth;
  // The world clock (0 sunrise, 12000 sunset): out at dusk, the night at the lights, back to a wall at dawn, at rest by
  // day; a moth house turns it a half-day round.
  assert.deepEqual([0, 6000, 11999, 12000, 13499, 13500, 18000, 22499, 22500, 23999, 24000, -500].map((t) => M.phaseOf(t, T)), ["day", "day", "day", "dusk", "dusk", "night", "night", "night", "dawn", "dawn", "day", "dawn"]);
  assert.deepEqual([0, 1500, 6000, 18000].map((t) => M.phaseOf(t, T, true)), ["dusk", "night", "night", "day"]);
  // Soul light: a soul lantern hanging (it circles under it) or standing, a lit soul campfire, soul fire, a soul torch
  // standing or on a wall (the block states as @minecraft/vanilla-data 1.26.52 names them).
  assert.equal(M.lightKind("minecraft:soul_lantern", { hanging: true }), "above");
  assert.equal(M.lightKind("minecraft:soul_lantern", { hanging: false }), "below");
  assert.equal(M.lightKind("minecraft:soul_campfire", { extinguished: false, "minecraft:cardinal_direction": "north" }), "below");
  assert.equal(M.lightKind("minecraft:soul_campfire", { extinguished: true }), undefined, "put out: no light");
  assert.equal(M.lightKind("minecraft:soul_fire", { age: 0 }), "below");
  for (const f of ["top", "unknown", undefined]) assert.equal(M.lightKind("minecraft:soul_torch", { torch_facing_direction: f }), "below", String(f));
  for (const f of ["west", "east", "north", "south"]) assert.equal(M.lightKind("minecraft:soul_torch", { torch_facing_direction: f }), "wall", f);
  for (const id of ["minecraft:torch", "minecraft:lantern", "minecraft:campfire", "minecraft:fire", "zoocraft:nocturnal_lamp_red", "minecraft:glowstone"]) {
    assert.equal(M.lightKind(id, {}), undefined, id);
    assert.equal(M.isSoulLight(id), false, id);
  }
  assert.deepEqual(["minecraft:soul_torch", "minecraft:soul_lantern", "minecraft:soul_campfire", "minecraft:soul_fire"].map(M.isSoulLight), [true, true, true, true]);
  // The caterpillars' food: the Nether's small plants.
  for (const id of ["minecraft:crimson_roots", "minecraft:warped_roots", "minecraft:nether_sprouts", "minecraft:crimson_fungus", "minecraft:warped_fungus"]) assert.equal(M.isHostPlant(id), true, id);
  for (const id of ["minecraft:twisting_vines", "minecraft:nether_wart", "minecraft:short_grass", "minecraft:crimson_nylium"]) assert.equal(M.isHostPlant(id), false, id);
  // A soul light needed (an exhibit not measured yet passes); host plants enough for the caterpillars.
  const sp = SPECIES["zoocraft:soul_moth"];
  assert.equal(M.hasSoulLight(sp, {}), true);
  assert.equal(M.hasSoulLight(sp, { soul: { lights: [], plants: 0, plantSpots: [] } }), false);
  assert.equal(M.hasSoulLight(sp, { soul: { lights: [{ x: 0, y: 0, z: 0, kind: "above" }], plants: 0, plantSpots: [] } }), true);
  assert.equal(M.hasSoulLight(SPECIES["zoocraft:cinder_boar"], { soul: { lights: [] } }), true, "not a boar's");
  assert.equal(M.hasHostPlants(sp, { soul: { lights: [], plants: 3 } }), false);
  assert.equal(M.hasHostPlants(sp, { soul: { lights: [], plants: 4 } }), true);
  assert.equal(M.hasHostPlants(sp, {}), false);
  assert.equal(M.hasHostPlants(SPECIES["zoocraft:cinder_boar"], {}), true);
  // The acts the client knows (the entity's zoocraft:act runs 0 to 13), found by type.
  assert.deepEqual(M.ACT, { none: 0, fly: 1, rest: 2, flash: 3, orbit_l: 4, orbit_r: 5, stall: 6, invert: 7, sip: 8, emerge: 9, crawl: 10, munch: 11, burrow: 12, pupa: 13 });
  assert.deepEqual(M.MOTH_TYPES, ["zoocraft:soul_moth", "zoocraft:wild_soul_moth"]);
  assert.equal(M.WILD_MOTH, "zoocraft:wild_soul_moth");
});

// A moth house of block ids: a soul soil floor (y 0), stone brick walls 4 out from 0,0 up to y 5, a roof at y 6 (air
// 5 high over a 7 by 7 floor). `put` adds blocks ("id" or { id, states }).
function mothHouse(put = {}, { roof = 6, wall = "minecraft:stone_bricks" } = {}) {
  const blocks = new Map();
  for (let x = -4; x <= 4; x++) for (let z = -4; z <= 4; z++) {
    blocks.set(`${x},0,${z}`, { id: "minecraft:soul_soil" });
    if (roof !== undefined) blocks.set(`${x},${roof},${z}`, { id: "minecraft:stone_bricks" });
    if (Math.max(Math.abs(x), Math.abs(z)) === 4) for (let y = 1; y < (roof ?? 6); y++) blocks.set(`${x},${y},${z}`, { id: wall });
  }
  for (const [k, v] of Object.entries(put)) blocks.set(k, typeof v === "string" ? { id: v } : v);
  const typeAt = (x, y, z) => blocks.get(`${x},${y},${z}`) ?? (y < 0 ? { id: "minecraft:netherrack" } : { id: "minecraft:air" });
  const read = (x, y, z) => {
    const id = typeAt(x, y, z).id;
    return classifyBlock(id, { isAir: id === "minecraft:air", isLiquid: false, open: false, leaves: true, perch: true });
  };
  return { blocks, typeAt, read };
}
async function mothMeasure(house, seed = { x: -1, y: 1, z: -1 }) {
  const M = await import("../packs/BP/scripts/animals/mothRules.js");
  const prof = HABITAT_PROFILES.moth_house;
  const out = newResult(seed);
  const f = floodAerial(house.read, out.seed, { ...EXHIBIT_LIMITS, halfWidth: 16, minHeight: prof.minHeight, cellsPerYield: 1e9 }, out);
  while (!f.next().done);
  const soul = M.newMothResult();
  const m = M.measureMoth(house.typeAt, out.cells, { cellsPerYield: 7, keep: BALANCE.moth.plantKeep }, soul);
  while (!m.next().done);
  return { out, soul, open: (x, y, z) => out.cells.has(`${x},${y},${z}`) };
}

test("Moth house: the flight measure, its soul lights (hanging, standing, on a wall) and host plants", async () => {
  const M = await import("../packs/BP/scripts/animals/mothRules.js");
  const house = mothHouse({
    "0,5,0": { id: "minecraft:soul_lantern", states: { hanging: true } },
    "-2,1,-2": { id: "minecraft:soul_campfire", states: { extinguished: false } },
    "2,1,-2": { id: "minecraft:soul_campfire", states: { extinguished: true } },
    "3,2,0": { id: "minecraft:soul_torch", states: { torch_facing_direction: "west" } },
    "1,1,1": "minecraft:crimson_roots",
    "2,1,1": "minecraft:warped_roots",
    "1,1,2": "minecraft:nether_sprouts",
    "-1,1,2": "minecraft:warped_fungus",
    "-2,1,2": "minecraft:dandelion",
  });
  const { out, soul, open } = await mothMeasure(house);
  assert.equal(out.enclosed, true);
  assert.equal(out.usableArea, 49, "49 blocks of floor (the top of a campfire with air over it is floor too)");
  // Each light once, the one put out not at all.
  const lights = [...soul.lights].sort((a, b) => a.x - b.x);
  assert.deepEqual(lights, [{ x: -2, y: 1, z: -2, kind: "below" }, { x: 0, y: 5, z: 0, kind: "above" }, { x: 3, y: 2, z: 0, kind: "wall" }]);
  assert.equal(soul.plants, 4, "a dandelion isn't a host plant");
  assert.deepEqual(soul.plantSpots.map((p) => p.join(",")).sort(), ["-1,1,2", "1,1,1", "1,1,2", "2,1,1"]);
  // Only the first `keep` places are kept.
  const few = M.newMothResult();
  const g = M.measureMoth(house.typeAt, out.cells, { cellsPerYield: 1e9, keep: 2 }, few);
  while (!g.next().done);
  assert.deepEqual([few.plants, few.plantSpots.length], [4, 2]);
  // A plant up on a ledge, not over the floor of the air: none in the air at all, so nothing to count.
  const none = await mothMeasure(mothHouse());
  assert.deepEqual([none.soul.lights.length, none.soul.plants], [0, 0]);
  // The circle round each light, the widest that fits.
  const T = BALANCE.moth;
  const under = M.orbitFor(open, lights[1], T);
  assert.deepEqual([under.c.x, under.c.z, under.r, under.stall, under.invert], [0.5, 0.5, T.orbitRadius[1], true, false]);
  assert.ok(Math.abs(under.c.y - (5 - T.under)) < 1e-9, "below the hanging lantern");
  const over = M.orbitFor(open, lights[0], T);
  assert.ok(Math.abs(over.c.y - (1 + T.over)) < 1e-9, "above the campfire");
  assert.equal(over.r, 1.2, "the wall 2.5 blocks off: a narrower circle");
  assert.deepEqual([over.stall, over.invert], [false, true]);
  const torch = M.orbitFor(open, lights[2], T);
  assert.ok(Math.abs(torch.c.x - (3.5 - T.out)) < 1e-9 && torch.c.z === 0.5, "out from the wall");
  for (const o of [under, over, torch]) for (let i = 0; i < 24; i++) assert.ok(M.fits(open, M.orbitAt(o, (i / 24) * Math.PI * 2)), "every point of the circle is open");
  // No room: a light in a gap too tight for any circle.
  const tight = mothHouse({ "0,3,0": { id: "minecraft:soul_lantern", states: { hanging: false } } }, { roof: 6 });
  for (let x = -3; x <= 3; x++) for (let z = -3; z <= 3; z++) if (Math.max(Math.abs(x), Math.abs(z)) >= 1) for (let y = 1; y <= 5; y++) tight.blocks.set(`${x},${y},${z}`, { id: "minecraft:stone_bricks" });
  tight.blocks.set("0,1,0", { id: "minecraft:air" });
  tight.blocks.set("0,2,0", { id: "minecraft:air" });
  assert.equal(M.orbitFor((x, y, z) => tight.typeAt(x, y, z).id === "minecraft:air", { x: 0, y: 3, z: 0, kind: "below" }, T), undefined);
  // The way round: the light on its right going the angle's way, so orbit_r; it faces along the circle.
  assert.deepEqual([M.orbitAct(1), M.orbitAct(-1)], [M.ACT.orbit_r, M.ACT.orbit_l]);
  const yawAt = (a, dir) => {
    const p = M.orbitAt(under, a);
    const q = M.orbitAt(under, a + dir * 0.01);
    return Math.atan2(-(q.x - p.x), q.z - p.z) * (180 / Math.PI);
  };
  for (const [a, dir] of [[0, 1], [1, -1], [2.5, 1], [4, -1]]) assert.ok(Math.abs(((M.orbitYaw(a, dir) - yawAt(a, dir) + 540) % 360) - 180) < 1, `${a} ${dir}`);
  // Going the angle's way the light is on its right. Facing yaw h it looks along (-sin h, cos h), and its right is
  // (-cos h, -sin h) (facing +z, +x is the mob's left).
  for (const [a, dir] of [[0, 1], [2, 1], [0, -1], [3, -1]]) {
    const p = M.orbitAt(under, a);
    const h = M.orbitYaw(a, dir) * (Math.PI / 180);
    const right = { x: -Math.cos(h), z: -Math.sin(h) };
    const side = right.x * (under.c.x - p.x) + right.z * (under.c.z - p.z);
    assert.ok(dir > 0 ? side > 0 : side < 0, `${a} ${dir}: the light on its ${dir > 0 ? "right (orbit_r)" : "left (orbit_l)"}`);
  }
  // Sharing a light: the same way round as the others, spread round the circle.
  assert.equal(M.orbitDir([-1, -1], () => 0), -1);
  assert.equal(M.orbitDir([], () => 0.9), -1);
  assert.equal(M.orbitDir([], () => 0.1), 1);
  const o = { c: { x: 0, y: 0, z: 0 }, r: 1 };
  assert.equal(M.joinAngle(o, { x: 5, y: 0, z: 0 }, []), 0);
  assert.ok(Math.abs(M.joinAngle(o, { x: 5, y: 0, z: 0 }, [0.1]) - (0.1 + Math.PI)) < 1e-9, "across from the one there");
  assert.equal(M.joinAngle(o, { x: 5, y: 0, z: 0 }, [Math.PI]), 0, "the near point is free");
  // Its place on the circle: full speed with room ahead, slowing as it closes on the next one, stopped at half the gap;
  // one behind it, or one the other way round from it, slows it not.
  assert.equal(M.orbitPace(0, 1, 1, [], 0.08, 0.8), 0.08);
  assert.equal(M.orbitPace(0, 1, 1, [2], 0.08, 0.8), 0.08);
  assert.ok(Math.abs(M.orbitPace(0, 1, 1, [0.6], 0.08, 0.8) - 0.04) < 1e-9, "closing on it");
  assert.equal(M.orbitPace(0, 1, 1, [0.3], 0.08, 0.8), 0, "stopped behind it");
  assert.equal(M.orbitPace(0, 1, 1, [-0.3], 0.08, 0.8), 0.08, "one behind it");
  assert.equal(M.orbitPace(0, -1, 1, [-0.3], 0.08, 0.8), 0, "going the other way, ahead is the lower angle");
  assert.equal(M.orbitPace(6.2, 1, 1, [0.1], 0.08, 0.8), 0, "ahead across the turn of the circle");
  assert.ok(Math.abs(M.orbitPace(0, 1, 2, [0.3], 0.08, 0.8) - 0.04) < 1e-9, "on a wider circle the same angle is further along");
  assert.ok(T.orbitGap > 0.4, "more than a moth's width");
  // In the way round: one hovering on the circle (just broken away), not one off it, above it or inside it.
  const ring = { c: { x: 0, y: 5, z: 0 }, r: 1 };
  assert.ok(M.onCircle(ring, { x: 0, y: 5, z: 1.2 }));
  assert.ok(!M.onCircle(ring, { x: 0, y: 5, z: 1.6 }) && !M.onCircle(ring, { x: 0, y: 6, z: 1 }) && !M.onCircle(ring, { x: 0.3, y: 5, z: 0 }));
  // The stall rises and falls back; the inversion drops and climbs back.
  assert.deepEqual([M.stallLift(0, T), M.stallLift(1, T)].map((v) => Math.abs(v) < 1e-9), [true, true]);
  assert.ok(Math.abs(M.stallLift(0.5, T) - T.stallRise) < 1e-9 && Math.abs(M.invertDrop(0.5, T) + T.invertDrop) < 1e-9);
});

test("Moth rest, sip and caterpillars: the wall spots, the feeder's sides, the bait, the night's choice, the plants", async () => {
  const M = await import("../packs/BP/scripts/animals/mothRules.js");
  const T = BALANCE.moth;
  const house = mothHouse({ "0,5,0": { id: "minecraft:soul_lantern", states: { hanging: true } }, "0,1,0": "zoocraft:nectar_feeder" });
  const { out, soul, open } = await mothMeasure(house);
  const wallAt = (x, y, z) => classifyBlock(house.typeAt(x, y, z).id, { isAir: false, isLiquid: false, open: false, gecko: true }) === "solid";
  const spots = M.restSpots(out.cells, wallAt, soul.lights, T);
  // Up the walls only (the lantern and the feeder are no wall to hold to), restMin or more over the floor.
  assert.ok(spots.length > 0);
  for (const s of spots) {
    assert.ok(s.cell.y >= 1 + T.restMin, `${s.cell.y}`);
    assert.equal(Math.max(Math.abs(s.cell.x + s.dir.x), Math.abs(s.cell.z + s.dir.z)), 4, "against the wall");
  }
  // High up first, and near the light higher still.
  assert.equal(spots[0].cell.y, 5);
  assert.equal(spots[0].score, 4 + T.lightBonus);
  assert.ok(Math.hypot(spots[0].cell.x, spots[0].cell.y - 5, spots[0].cell.z) <= T.lightNear);
  for (let i = 1; i < spots.length; i++) assert.ok(spots[i - 1].score >= spots[i].score);
  // At rest: against the wall, facing it.
  const at = M.restPos({ cell: { x: 3, y: 4, z: 0 }, dir: { x: 1, z: 0 } });
  assert.ok(Math.abs(at.x - (4 - M.WALL_GAP)) < 1e-9 && at.z === 0.5 && Math.abs(at.y - 4.3) < 1e-9);
  assert.equal(at.yaw, -90, "facing +x (yawTo)");
  const used = new Set([M.spotKey(spots[0])]);
  assert.notEqual(M.spotKey(M.pickRest(spots, used, 6, () => 0)), M.spotKey(spots[0]), "a spot another moth is on is taken");
  assert.equal(M.pickRest([], new Set()), undefined);
  // The feeder's four sides, nearest first; a side another one sips at is taken; one into a wall is no side.
  const sides = M.sipSpots(open, { x: 0, y: 1, z: 0 }, { x: 3, y: 2, z: 0.5 });
  assert.equal(sides.length, 4);
  assert.ok(sides[0].at.x > 0.5 && Math.abs(sides[0].at.y - 1.52) < 1e-9, "the side toward it, level with the dish");
  assert.equal(sides[0].yaw, 90, "facing the dish (-x)");
  assert.equal(M.sipSpots(open, { x: 0, y: 1, z: 0 }, { x: 0, y: 2, z: 0 }, new Set([sides[0].side])).length, 3);
  assert.equal(M.sipSpots(open, { x: 3, y: 1, z: 3 }, { x: 0, y: 2, z: 0 }).length, 2, "in a corner, two sides");
  // Held up: in front of their hands, toward the moth.
  assert.deepEqual(M.besideHand({ x: 0, y: 64, z: 0 }, { x: 0, y: 66, z: 5 }, T.baitGap), { x: 0, y: 65.1, z: T.baitGap });
  // At night: the feeder at dusk first; later by chance once it hasn't sipped for a while; a light; a flit.
  assert.equal(M.nightChoice({ dusk: true, nectar: true, sippedAgo: Infinity, light: true }, T, () => 0.99), "sip");
  assert.equal(M.nightChoice({ dusk: true, nectar: false, sippedAgo: Infinity, light: true }, T, () => 0), "orbit");
  assert.equal(M.nightChoice({ dusk: false, nectar: true, sippedAgo: T.sipGap - 1, light: true }, T, () => 0), "orbit", "sipped not long ago");
  assert.equal(M.nightChoice({ dusk: false, nectar: true, sippedAgo: T.sipGap, light: false }, T, () => 0), "sip");
  assert.equal(M.nightChoice({ dusk: false, nectar: true, sippedAgo: T.sipGap, light: false }, T, () => 0.99), "flit");
  assert.equal(M.nightChoice({ dusk: false, nectar: false, sippedAgo: 0, light: true }, T, () => 0.99), "flit");
  // A caterpillar is a pupa through its last pupaDays of growing up.
  const sp = SPECIES["zoocraft:soul_moth"];
  const br = sp.breeding;
  assert.equal(M.pupaNow({ juvenile: true, juvenileDaysLeft: br.matureDays }, sp), false);
  assert.equal(M.pupaNow({ juvenile: true, juvenileDaysLeft: br.pupaDays + 1 }, sp), false);
  assert.equal(M.pupaNow({ juvenile: true, juvenileDaysLeft: br.pupaDays }, sp), true);
  assert.equal(M.pupaNow({ juvenile: false }, sp), false);
  assert.equal(M.pupaNow({ juvenile: true, juvenileDaysLeft: 0 }, SPECIES["zoocraft:cinder_boar"]), false, "a piglet isn't");
  // The next plant: the nearest within range no other caterpillar is at.
  const plants = [[1, 1, 1], [3, 1, 0], [9, 1, 9]];
  assert.deepEqual(M.pickPlant(plants, { x: 0.5, y: 1, z: 0.5 }, new Set(), T.larvaRange), { x: 1, y: 1, z: 1 });
  assert.deepEqual(M.pickPlant(plants, { x: 0.5, y: 1, z: 0.5 }, new Set(["1,1,1"]), T.larvaRange), { x: 3, y: 1, z: 0 });
  assert.equal(M.pickPlant(plants, { x: 1.5, y: 1, z: 1.5 }, new Set(["3,1,0"]), T.larvaRange), undefined, "the one it's on, and the far one");
});

test("Moth care: soul light caps comfort; the house light; the Nectar Feeder; the warnings, clipboard, species and breeding", async () => {
  const W = await import("../packs/BP/scripts/animals/welfare.js");
  const M = await import("../packs/BP/scripts/animals/mothRules.js");
  const N = await import("../packs/BP/scripts/animals/nightRules.js");
  const R = await import("../packs/BP/scripts/equipment/rules.js");
  const F = await import("../packs/BP/scripts/equipment/feeder.js").catch(() => undefined);
  const I = await import("../packs/BP/scripts/data/items.js");
  const C = await import("../packs/BP/scripts/quests/conservationRules.js");
  const { breedingCheck } = await import("../packs/BP/scripts/animals/breeding.js");
  const sp = SPECIES["zoocraft:soul_moth"];
  const T = BALANCE.moth;
  const day = BALANCE.clock.dayLength;
  // Without a soul light comfort stays at the cap.
  const g = { needs: { satiety: 90, comfort: 90, cleanliness: 90, enrichment: 90, social: 90 }, health: 100 };
  W.simulateAnimal(g, sp, { exhibitCleanliness: 100, spaceRatio: 1, groupSize: 3, feederUnits: 20, heat: true, soul: false }, day * 20, BALANCE);
  assert.equal(g.needs.comfort, T.soulComfortCap);
  assert.deepEqual(W.comfortCauses({ spaceRatio: 1, soul: false }, BALANCE), ["soul"]);
  assert.match(W.adviceFor("comfort", sp, ["soul"]), /a soul light inside \(a soul lantern, soul torch, soul campfire or soul fire\)/);
  // The moth house's light: soul light (10) counts as dark for them, where the Nocturnal Lamps' limit is 7.
  const readings = [{ sky: 0, light: 10 }, { sky: 0, light: 4 }, { sky: 0, light: 0 }];
  const owlHouse = N.houseFromReadings(readings, BALANCE);
  assert.deepEqual([owlHouse.bright, owlHouse.max], [1, undefined], "the Nocturnal Lamps' limit, as before");
  const mothHouseLight = N.houseFromReadings(readings, BALANCE, sp.houseLight);
  assert.deepEqual([mothHouseLight.bright, mothHouseLight.max, mothHouseLight.lit], [0, 10, 2]);
  assert.equal(N.isNocturnalHouse({ house: mothHouseLight }, BALANCE), true);
  assert.equal(N.isNocturnalHouse({ house: owlHouse }, BALANCE), false);
  const glow = N.houseFromReadings([{ sky: 0, light: 15 }], BALANCE, 10);
  assert.match(N.houseProblems(glow, BALANCE)[0], /brightest 15 of 10 allowed \(torches, lanterns and glowstone are too bright: light it with soul lanterns, soul torches or soul campfires, or Nocturnal Lamps\)/);
  assert.match(N.houseProblems(N.houseFromReadings([{ sky: 0, light: 9 }], BALANCE), BALANCE)[0], /of 7 allowed \(torches, lanterns and glowstone are too bright: light it with red or purple Nocturnal Lamps only\)/, "a hedgehog's as before");
  assert.equal(N.houseFromReadings([], BALANCE, BALANCE.nocturnal.maxLight).max, undefined);
  // The Nectar Feeder: Soul Moths eat from nothing else, and nothing else eats from it.
  assert.equal(R.reachesFeeder(sp, { nectar: true }), true);
  assert.equal(R.reachesFeeder(sp, {}), false);
  assert.equal(R.reachesFeeder(sp, { insect: true }), false);
  for (const other of ["zoocraft:cinder_boar", "zoocraft:warped_gecko", "zoocraft:owl", "zoocraft:crimson_grazer"]) assert.equal(R.reachesFeeder(SPECIES[other], { nectar: true }), false, other);
  assert.equal(R.reachesFeeder(SPECIES["zoocraft:cinder_boar"], {}), true, "a Basic Feeder as before");
  assert.equal(I.BLOCKS.nectarFeeder, "zoocraft:nectar_feeder");
  assert.equal(I.ITEMS.nectarRation, "zoocraft:nectar_ration");
  assert.deepEqual(I.RATIONS["zoocraft:nectar_ration"], { diet: "nectar", units: 1, label: "Nectar Ration" });
  assert.equal(I.FOOD_LOOK.nectar, 12);
  assert.deepEqual(BALANCE.shop["zoocraft:nectar_ration"], { price: 3, bundle: 8, sell: 1 });
  // The moth house: a roofed flight house, 9 blocks of floor for the first and 2 more each, 4 high.
  const prof = HABITAT_PROFILES.moth_house;
  assert.deepEqual([prof.baseArea, prof.extraArea, prof.minHeight, prof.aerial, prof.nectar], [9, 2, 4, true, true]);
  assert.equal(requiredArea(prof, 6), 19);
  // The species: a Nether flyer in a Thermal Carrier; nectar from a Nectar Feeder; a night animal; caterpillars.
  assert.deepEqual([sp.habitatProfile, sp.movementProfile, sp.carrierProfile, sp.dietTags, sp.baitItem, sp.rationUnitsPerParkDay, sp.origin, sp.homeDimension, sp.wildSource, sp.entityType], ["moth_house", "aerial", "thermal", ["nectar"], "zoocraft:nectar_ration", 1, "custom_nether", "minecraft:nether", "zoocraft:wild_soul_moth", "zoocraft:soul_moth"]);
  assert.equal(sp.flies && sp.heat && sp.soulLight && sp.nectarFeeder && sp.nightLife && sp.glows && sp.sexLook, true);
  assert.equal(sp.houseLight, 10);
  assert.equal(Boolean(sp.roosts || sp.nocturnal || sp.climbs || sp.clings || sp.dangerous || sp.boarProof || sp.social.prefersCompany), false, "its own flight, not the owl's or the Void Ray's");
  assert.deepEqual(sp.observe, ["spot", "orbit", "tumble", "sip"]);
  assert.deepEqual([sp.breeding.litter, sp.breeding.litterMax, sp.breeding.matureDays, sp.breeding.pupaDays, sp.breeding.hostPlants, sp.breeding.young, sp.breeding.youngPlural], [3, 6, 5, 2, 4, "caterpillar", "caterpillars"]);
  const others = Object.values(SPECIES).filter((s) => s !== sp).flatMap((s) => s.names ?? []);
  assert.deepEqual(sp.names.filter((n) => others.includes(n)), [], "names of its own");
  assert.equal(new Set(sp.names).size, 16);
  assert.deepEqual(validateData(), []);
  // Let out on soul soil or soul sand.
  assert.equal(C.groundText(sp), "on soul soil or soul sand");
  assert.equal(C.groundOk(sp, { id: "minecraft:soul_sand", isAir: false, isLiquid: false }), true);
  assert.equal(C.groundOk(sp, { id: "minecraft:basalt", isAir: false, isLiquid: false }), false);
  // The clipboard's lines and the warnings.
  const a = (name, sex, juvenile = false) => ({ name, sex, juvenile });
  const ex = { soul: { lights: [{ kind: "above" }, { kind: "wall" }, { kind: "wall" }], plants: 2, plantSpots: [] } };
  assert.deepEqual(M.mothLines(ex, [a("Candle", "female")], 1, sp, T), ["§fSoul lights: §a3§7 (1 hanging, 2 on the walls)", "§fNectar Feeders: §a1", "§fHost plants: §e2§7 (4 or more Nether roots, sprouts or fungi in the floor, for the caterpillars; a moth lays her eggs only where there are)"]);
  assert.match(M.mothLines({ soul: { lights: [], plants: 5 } }, [], 0, sp, T)[0], /^§fSoul lights: §c0§7 .*comfort can't rise above 40\)$/);
  assert.equal(M.mothLines({ soul: { lights: [], plants: 5 } }, [], 0, sp, T)[1], "§fNectar Feeders: §c0§7 (they sip only from a Nectar Feeder)");
  assert.match(M.mothLines({}, [], 0, sp, T)[0], /not measured yet/);
  assert.equal(M.mothWarnings({ soul: { lights: [], plants: 9 } }, [], "Soul Moths", sp, T).length, 1);
  assert.deepEqual(M.mothWarnings({}, [], "Soul Moths", sp, T), [], "nothing before the measure");
  const breeding = M.mothWarnings({ soul: { lights: [{}], plants: 1 }, breeding: { on: true } }, [], "Soul Moths", sp, T);
  assert.equal(breeding.length, 1);
  assert.match(breeding[0].text, /^Breeding is on, but a moth lays her eggs only on host plants: 4 or more .*\(1 now\)\.$/);
  assert.deepEqual(M.mothWarnings({ soul: { lights: [{}], plants: 1 }, breeding: { on: false } }, [], "Soul Moths", sp, T), []);
  // Breeding: eggs only where there are host plants (the rest of the check as for any species).
  const mom = { id: "m", name: "Candle", sex: "female", juvenile: false };
  const dad = { id: "d", name: "Flit", sex: "male", juvenile: false };
  const ctx = { species: sp, on: true, animals: [mom, dad], day: 10, cooldownUntil: 0, state: "occupied", issue: undefined, plural: "Soul Moths", required: (n) => requiredArea(prof, n), usable: 40, usableArea: 40, foodDays: 9, coveredCells: 40 };
  assert.match(breedingCheck({ ...ctx }, BALANCE.breeding).reason, /Measure the exhibit again .* host plants can be counted/);
  assert.match(breedingCheck({ ...ctx, hostPlants: 3 }, BALANCE.breeding).reason, /^Needs host plants for the caterpillars: 4 or more .* \(3 now\)/);
  const ok = breedingCheck({ ...ctx, hostPlants: 4, welfareOf: () => 90, goodDays: BALANCE.breeding.goodDays }, BALANCE.breeding);
  assert.equal(ok.ok, true, ok.reason);
  assert.equal(ok.litter, sp.breeding.litterMax, "room for a full clutch");
  assert.match(breedingCheck({ ...ctx, hostPlants: 4, animals: [{ ...mom, expecting: { daysLeft: 2 } }, dad] }, BALANCE.breeding).reason, /Candle has laid her eggs on the host plants: the caterpillars hatch in 2 park days\./);
  // The wiring: the cap, the caterpillars' food, the warnings, the clipboard, the measure, the breeding count.
  const src = (p) => readFileSync(new URL(p, import.meta.url), "utf8");
  const animals = src("../packs/BP/scripts/animals/animals.js");
  assert.match(animals, /const soul = hasSoulLight\(species, ex\);\n {6}const hostPlants = (species\.chorusFlowers \? hasChorusHosts\(species, ex\) : )?hasHostPlants\(species, ex\);/);
  assert.match(animals, /walls, hide, males, wallow, soul(, bed(, pads(, crevices, mineral(, rock, burrows(, flowers, dim(, endPlants, warmPads, retreat(, sand(, seagrass(, lush, clay(, burrow(, sculk, shriek(, bloom(, warmth(, hoard(, trunk(, snow(, soulfloor, beam(, mobfloor(, hay(, run, groomed: [\w.()]+(, rockLedges(, desertSand, desertShade(, lilyPads(, waterPlants, tankFloor(, deepStretch, openWater(, beeFlowers, beeHives(, restSpots(, sandFloor, chill(, mycelium(, digBed(, batRoosts, batFlight(, coolBiome(, skyView(, sulfur)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)? \}, BALANCE\);/);
  assert.match(animals, /const larva = Boolean\(a\.juvenile && species\.breeding\?\.hostPlants\);/);
  assert.match(animals, /feederUnits: larva \? \(hostPlants \? 100 : 0\) : (grub \? \(bed \? 100 : 0\) : (tadpole \? \(lilyPads \? 100 : 0\) : )?)?eats \? units : 0,/);
  assert.match(animals, /let left = larva( \|\| grub( \|\| tadpole)?)? \? 0 : unitsEaten;/, "caterpillars take nothing from the feeders");
  assert.match(animals, /populationWeight\(species\.breeding\?\.hostPlants( \|\| species\.breeding\?\.substrate)? \? residents\.filter\(\(a\) => !a\.juvenile\) : residents, /);
  assert.match(animals, /if \(species\.soulLight\) out\.push\(\.\.\.mothWarnings\(ex, residents, pluralOf\(species\), species, BALANCE\.moth\)\);/);
  assert.match(animals, /else if \(!reach\.length && species\.nectarFeeder\) out\.push/);
  assert.match(src("../packs/BP/scripts/ui/clipboard.js"), /\.\.\.\(moth \? mothLines\(ex, animalsIn\(ex\)\.filter\(\(a\) => a\.speciesId === moth\.id\), nectars, moth, BALANCE\.moth\) : \[\]\),/);
  assert.match(src("../packs/BP/scripts/animals/nursery.js"), /hostPlants: (species\?\.chorusFlowers \? ex\.chorus\?\.plants : )?ex\.soul\?\.plants,/);
  const room = src("../packs/BP/scripts/exhibits/room.js");
  assert.match(room, /if \(profile\.nectar\) \{\n {4}if \(!a\) return `\$\{label\}s fly: put a Nectar Feeder inside the exhibit, roof it over, then measure it again with the Habitat Marker\.`;/);
  // Feeders: a Nectar Feeder holds Nectar Rations only, and they go in nothing else (a basket aside).
  const feeder = src("../packs/BP/scripts/equipment/feeder.js");
  assert.match(feeder, /if \(block\.typeId === BLOCKS\.nectarFeeder\) rec\.nectar = true;/);
  assert.match(feeder, /if \(rec\.nectar && RATIONS\[item\]\?\.diet !== "nectar"\) return/);
  assert.match(feeder, /if \(!rec\.nectar && RATIONS\[item\]\?\.diet === "nectar"\) return/);
  assert.match(feeder, /rec\.nectar \? "Nectar Feeder" : (rec\.mineral \? "Mineral Feeder" : )?(rec\.aquarium \? "Aquarium Feeder" : )?"Feeder"/);
  if (F?.wrongRation) {
    assert.ok(F.wrongRation({ nectar: true }, "zoocraft:fungal_ration"));
    assert.equal(F.wrongRation({ nectar: true }, "zoocraft:nectar_ration"), undefined);
    assert.ok(F.wrongRation({}, "zoocraft:nectar_ration"));
  }
});

test("Moth measure wiring: the flight measure for moths and for an empty exhibit with a Nectar Feeder; ex.soul; the house light", () => {
  const src = (p) => readFileSync(new URL(p, import.meta.url), "utf8");
  const ex = src("../packs/BP/scripts/exhibits/exhibits.js");
  assert.match(ex, /yield\* floodAerial\(read, start, airOpts, out\);\n {12}air = out;\n {12}\/\/ [^\n]*\n {12}if \(\(wants\("nocturnal"\) \|\| wants\("nightLife"\)( \|\| wants\("lowLight"\))?\) && !out\.error\) yield\* measureHouse\(dim\(ex\.dimension\), out, BALANCE, houseLightOf\(ex\)\);\n {12}if \(wants\("soulLight"\) && !out\.error\) \{\n {14}soul = newMothResult\(\);\n {14}yield\* measureMoth\(lightReader\(dim\(ex\.dimension\)\), out\.cells, \{ cellsPerYield: airOpts\.cellsPerYield, keep: BALANCE\.moth\.plantKeep \}, soul\);/);
  assert.match(ex, /\} else if \(!species && !out\.error && nectarFeederInside\(ex, out\)\) \{/);
  assert.match(ex, /yield\* floodAerial\(read, start, \{ \.\.\.airOpts, minHeight: HABITAT_PROFILES\.moth_house\.minHeight, countEnd: false \}, air\);/);
  assert.match(ex, /resolve\(applyValidation\(exId, start, out, air, climb, croc, ape, walls, boar, soul(, hops(, crevices(, rock(, chorus(, tortoise(, okapi(, molebear(, skulker(, unicorn(, dragon(, griffin(, stag(, snow(, sloth(, mobPen, mobFloor(, bamboo(, goat(, pond(, tank(, pool(, bees(, parrots(, cats)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?\)\);/);
  assert.match(ex, /ex\.soul = soul \? \{ lights: soul\.lights\.slice\(0, 32\), plants: soul\.plants, plantSpots: soul\.plantSpots \} : undefined;/);
  assert.match(ex, /return \{ id: b\.typeId, states: isSoulLight\(b\.typeId\)( \|\| CAMPFIRES\.has\(b\.typeId\)( \|\| isHive\(b\.typeId\)( \|\| b\.typeId === BED)?)?)? \? b\.permutation\.getAllStates\(\) : undefined \};/);
  assert.match(ex, /return Math\.max\(BALANCE\.nocturnal\.maxLight, \.\.\.speciesIn\(ex\)\.map\(\(sp\) => sp\.houseLight \?\? 0\)\);/);
  assert.match(ex, /: !species && soul \? HABITAT_PROFILES\.moth_house : (!species && hops \? HABITAT_PROFILES\.hopper : )?profileOf\(ex\);/);
  assert.match(src("../packs/BP/scripts/exhibits/light.js"), /out\.house = houseFromReadings\(readings, balance, max\);/);
  // Moths in a moth house find the feeder from the air above the floor (isReachable on its land cells).
  assert.match(ex, /isReachable\(r\.cells, f\.pos, f\.aquarium \? "water" : f\.thermal \? "lava" : "land", f\.aquarium \? \[-1, 0, 1\] : f\.rack \? \[-1, 0\] : undefined\)/);
  // The shop names every ration (it showed the newer ones by their ids).
  const menu = src("../packs/BP/scripts/ui/parkMenu.js");
  assert.match(menu, /const itemLabel = \(item\) => ITEM_LABEL\[item\] \?\? \(RATIONS\[item\] \? rationPlural\(item\) : item\);/);
  assert.doesNotMatch(menu, /ITEM_LABEL\[item\] \?\? item\b/);
});

test("Moth Field Journal: circling a soul light, the flip over one, sipping nectar", async () => {
  const { TASKS, tasksSeen, levelOf } = await import("../packs/BP/scripts/discovery/rules.js");
  const sp = SPECIES["zoocraft:soul_moth"];
  assert.deepEqual(tasksSeen(sp, ["spot"], { orbiting: true, tumbling: false, sipping: true }), ["orbit", "sip"]);
  assert.deepEqual(tasksSeen(sp, ["spot", "orbit", "sip"], { tumbling: true }), ["tumble"]);
  assert.deepEqual(tasksSeen(sp, ["spot"], { gliding: true, looping: true, hooting: true, rooting: true }), [], "a Void Ray's, an owl's and a boar's tasks aren't a moth's");
  assert.equal(levelOf(sp, ["spot", "orbit", "tumble", "sip"]), 3);
  for (const t of sp.observe) assert.ok(TASKS[t], t);
  const src = (p) => readFileSync(new URL(p, import.meta.url), "utf8");
  const disc = src("../packs/BP/scripts/discovery/discovery.js");
  assert.match(disc, /\/\*\* @returns \{\{ orbiting\?: boolean, tumbling\?: boolean, sipping\?: boolean \}\} \*\/\nfunction mothSight/, "one return type (tsc)");
  assert.match(disc, /return \{ orbiting: act === MOTH_ACT\.orbit_l \|\| act === MOTH_ACT\.orbit_r \|\| act === MOTH_ACT\.stall, tumbling: act === MOTH_ACT\.invert, sipping: act === MOTH_ACT\.sip \};/);
  assert.match(disc, /\.\.\.mothSight\(species, hit\)/);
  assert.match(disc, /if \(!species\.flies \|\| species\.roosts \|\| species\.soulLight( \|\| species\.chorusFlowers( \|\| species\.warmth( \|\| species\.beeGarden( \|\| species\.dances( \|\| species\.batRoost)?)?)?)?)?\) return \{\};/, "no Void Ray properties read off a moth");
  const journal = src("../packs/BP/scripts/ui/fieldJournal.js");
  assert.match(journal, /if \(sp\.soulLight\) \{/);
  assert.match(journal, /if \(prof\.aerial && prof\.nectar\) lines\.push\(`§7Moth house: a roof and closed walls/);
  assert.match(journal, /if \(sp\.soulLight\) lines\.splice\(4, 0, `§7\$\{mothWildLine\(BALANCE\.moth\)\}`\);/);
});

