    for (const ev of ["zoocraft:sex_0", "zoocraft:sex_1"]) assert.ok(be.events[ev], `${name} ${ev}`);
    assert.equal(be.component_groups["zoocraft:sex_1"]["minecraft:mark_variant"].value, 1);
    // A male a little smaller: his box 0.92 of hers.
