  assert.ok(wild.components["minecraft:despawn"]);
  assert.equal(wild.components["minecraft:type_family"].family.includes("zoocraft_animal"), false);
  const spawn = json("../packs/BP/spawn_rules/wild_soul_moth.json")["minecraft:spawn_rules"].conditions[0];
  assert.deepEqual(spawn["minecraft:biome_filter"], { test: "has_biome_tag", operator: "==", value: "soulsand_valley" });
  assert.deepEqual(spawn["minecraft:spawns_on_block_filter"], ["minecraft:soul_soil", "minecraft:soul_sand"]);
  assert.deepEqual([spawn["minecraft:herd"].min_size, spawn["minecraft:herd"].max_size], [2, 4]);
  // The client: an animation for every act; the caterpillar and the pupa bones only on the young; the proboscis only
