  for (let a = 1; a <= ACTS; a++) assert.ok(ctrl.includes(`query.property('zoocraft:act') == ${a}`), `act ${a}`);
  const anims = json("../packs/RP/animations/soul_moth.animation.json").animations;
  for (const a of ["fly", "orbit_l", "orbit_r", "stall", "invert", "sip", "rest", "flash", "settled", "emerge", "crawl", "munch", "burrow", "larva_still", "pupa"]) assert.ok(anims[`animation.zoocraft.soul_moth.${a}`], a);
