  const T = BALANCE.crab;
  const day = BALANCE.clock.dayLength;
  for (const [key, cap] of [["rock", T.rockComfortCap], ["burrows", T.burrowComfortCap]]) {
    const g = { needs: { satiety: 90, comfort: 90, cleanliness: 90, enrichment: 90, social: 90 }, health: 100 };
    W.simulateAnimal(g, sp, { exhibitCleanliness: 100, spaceRatio: 1, groupSize: 1, feederUnits: 20, end: true, [key]: false }, day * 20, BALANCE);
    assert.equal(g.needs.comfort, cap, key);
    assert.deepEqual(W.comfortCauses({ spaceRatio: 1, [key]: false }, BALANCE), [key]);
  }
  assert.match(W.adviceFor("comfort", sp, ["rock"]), /rock to scrape: the sides of rock blocks standing at the floor's level, a wall of rock or boulders on the floor/);
  assert.match(W.adviceFor("comfort", sp, ["burrows"]), /Mineral Substrate to dig their burrows in \(2 blocks in the floor for each, 4 at least; 4 gravel, a nether quartz and a bone meal make 4\)/);
  // What an exhibit needs: 4 rock faces for the first and 2 more each; 2 Mineral Substrate each, 4 at least. Not
