  assert.match(animals, /males, wallow, soul, bed, pads, crevices, mineral, rock, burrows(, flowers, dim(, endPlants, warmPads, retreat(, sand(, seagrass(, lush, clay(, burrow(, sculk, shriek(, bloom(, warmth(, hoard(, trunk(, snow(, soulfloor, beam(, mobfloor(, hay(, run, groomed: [\w.()]+(, rockLedges(, desertSand, desertShade(, lilyPads(, waterPlants, tankFloor(, deepStretch, openWater(, beeFlowers, beeHives(, restSpots(, sandFloor, chill(, mycelium(, digBed(, batRoosts, batFlight(, coolBiome(, skyView(, sulfur)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)?)? \};/);
