  assert.deepEqual([K.madeSound({ x: 0, y: 0, z: 0 }, { x: 1, y: 0, z: 0 }, false, false, T.moveMin), K.madeSound({ x: 0, y: 0, z: 0 }, { x: 1, y: 0, z: 0 }, true, false, T.moveMin), K.madeSound({ x: 0, y: 0, z: 0 }, { x: 0.2, y: 0, z: 0 }, false, false, T.moveMin), K.madeSound(undefined, { x: 1, y: 0, z: 0 }, false, false, T.moveMin), K.madeSound({ x: 0, y: 0, z: 0 }, { x: 0, y: 1, z: 0 }, false, true, T.moveMin)], [true, false, false, false, false]);
  const ow = "minecraft:overworld";
  const heard = [{ id: "far", location: { x: 9, y: 0, z: 0 }, dimension: ow }, { id: "near", location: { x: 0, y: 0, z: 5 }, dimension: ow }, { id: "nether", location: { x: 1, y: 0, z: 0 }, dimension: "minecraft:nether" }];
  assert.deepEqual([K.hearing({ x: 0, y: 0, z: 0 }, ow, heard, T.hearRange)?.id, K.hearing({ x: 0, y: 0, z: 0 }, ow, heard.slice(0, 1), T.hearRange), K.hearing({ x: 0, y: 0, z: 0 }, "minecraft:nether", heard, T.hearRange)?.id], ["near", undefined, "nether"]);
  // The day: up by day, resting at night: dug into sculk (or a sculk vein), sitting elsewhere.
