  assert.deepEqual([K.restAct(K.SCULK, "minecraft:air"), K.restAct("minecraft:deepslate", "minecraft:sculk_vein"), K.restAct("minecraft:stone", "minecraft:air"), K.restAct(undefined, undefined)], [K.ACT.buried, K.ACT.buried, K.ACT.sit, K.ACT.sit]);
  // The journal: listening with its tendrils, sniffing someone, rising out of the sculk.
