  assert.match(src("discovery/discovery.js"), /return \{ tendrilsListening: act === SKULKER_ACT\.listen, sniffingSomeone: act === SKULKER_ACT\.sniff, emerging: act === SKULKER_ACT\.emerge \};/);
  assert.match(src("discovery/discovery.js"), /\.\.\.molebearSight\(species, hit\), \.\.\.skulkerSight\(species, hit\),/);
  assert.match(K.wildLine(T), /^In the wild they live only in the deep dark, very rarely.*The first time you walk into an Ancient City, one is somewhere near, resting out of sight\..*move within 8 blocks without sneaking.*Hold an Insect Ration and one comes over from 8 blocks$/);
  const journal = src("ui/fieldJournal.js");
  for (const s of ["if (sp.sculkFloor) lines.splice(4, 0, `§7${skulkerWildLine(BALANCE.skulker)}`);", "if (sp.sculkFloor) {", "Sneak and it never hears you. Never dangerous: it has no attack"]) assert.ok(journal.includes(s), s);
  // Ancient Cities: the city blocks counted in a sample round where someone stands (a hall of deepslate tiles with gray
  // carpet: many; the plain deep dark: none), stopping once enough are found; a city 160 blocks from every one found is
  // new; its Skulker is put out of their sight, 12 to 24 blocks off, on a floor with 2 blocks of air over it.
  const city = (x, y, z) => (y === -1 ? (Math.abs(x) < 20 && Math.abs(z) < 20 ? "minecraft:deepslate_tiles" : "minecraft:deepslate") : y === 0 && (x + z) % 4 === 0 ? "minecraft:gray_carpet" : y === 5 ? "minecraft:deepslate_bricks" : "minecraft:air");
  const plain = (x, y, z) => (y <= -1 ? "minecraft:deepslate" : y === 0 && x % 5 === 0 ? "minecraft:sculk_vein" : "minecraft:air");
  const at0 = { x: 0.5, y: 0, z: 0.5 };
  assert.equal(C.citySample(at0).length, 324);
  assert.ok(C.cityScore(city, at0) >= T.city.score && C.cityScore(plain, at0) === 0);
  assert.equal(C.cityScore(city, at0, 12, 3, [-3, -1, 1, 3], T.city.score), T.city.score, "stops once enough are found");
  assert.ok([...C.CITY_BLOCKS].every((b) => b.startsWith("minecraft:")) && !C.CITY_BLOCKS.has("minecraft:deepslate") && !C.CITY_BLOCKS.has("minecraft:sculk"));
  assert.deepEqual([C.isNewCity([], at0, 160), C.isNewCity([{ x: 100, z: 100 }], at0, 160), C.isNewCity([{ x: 200, z: 0 }], at0, 160), C.isNewCity(undefined, at0, 160)], [true, false, true, true]);
  // A hall: open floor everywhere at y 0, a wall along x = 5 hiding everything beyond it from someone at the origin.
  const kindAt = (x, y, z) => (y === -1 ? "solid" : x === 5 && y >= 0 && y <= 4 ? "solid" : y >= 0 && y <= 4 ? "air" : "solid");
  const blocked = (eye, to) => (eye.x < 5) !== (to.x < 5) || (eye.x > 6) !== (to.x > 6);
  const eye = { x: 0.5, y: 1.62, z: 0.5 };
  let r = 0;
  const rand = () => ((r = (r * 9301 + 49297) % 233280) / 233280);
  for (let i = 0; i < 20; i++) {
    const spot = C.hideSpot(kindAt, blocked, eye, at0, { min: T.city.hide[0], max: T.city.hide[1], rand });
    assert.ok(spot, "found one");
    const d = Math.hypot(spot.x - at0.x, spot.z - at0.z);
    assert.ok(d >= T.city.hide[0] - 1 && d <= T.city.hide[1] + 1 && spot.x > 6 && spot.y === 0, JSON.stringify(spot));
  }
  assert.equal(C.hideSpot(kindAt, () => false, eye, at0, { rand }), undefined, "nowhere out of sight: none");
  const beh = src("animals/skulker.js");
  for (const s of ['if (biomeAt(d, loc)?.id !== "minecraft:deep_dark") return;', "if (d.id !== \"minecraft:overworld\" || loc.y > C.depth || !memberOfAny(p)) return;", "if (cityScore(idAt, loc, 12, 3, [-3, -1, 1, 3], C.score) < C.score) return;", 'findPlace(p, "ancient_city", loc);', 'const e = d.spawnEntity("zoocraft:wild_skulker", spot, { initialPersistence: true });', "if (known && foundPlaces(p).ancient_city) return;"]) assert.ok(beh.includes(s), s);
  // The behaviour: never an attack; the tag its walk over follows, on the one it's walking to and off everyone else.
  for (const s of ['const TAG = "zoocraft_heard";', "if (visiting.has(p.id)) {", "if (p.hasTag(TAG)) p.removeTag(TAG);", "if (h) heardSomeone(e, s, now, h.player);", "if (LYING_ACTS.includes(s.act)) return finish(e, s, now); // up first: it listens after", "s.actUntil = now + T.emergeTicks + Math.max(0, s.downAt + T.digTicks - now);"]) assert.ok(beh.includes(s), s);
  assert.ok(!/applyDamage|\.kill\(|setType\(|setBlockType/.test(beh), "it hurts no one and changes no block");
  assert.match(src("main.js"), /loop\("skulkers", 10, 103, \(\) => tickSkulkers\(system\.currentTick\)\);/);
  assert.match(src("main.js"), /loop\("ancientCities", 20, 107, \(\) => tickAncientCities\(system\.currentTick\)\);/);
  // The measure in the exhibits; the dark is the nocturnal house's measure (lowLight).
