  // Places: the Deep Dark (its biome; directions after Cave Expeditions) and Ancient Cities (found only by the city check).
  assert.deepEqual(Object.keys(PLACES), ["deep_trench", "lush_caves", "deep_caves", "deep_dark", "ancient_city", "lava_falls", "chorus_meadow", "rift_willows", "mythical_glade", "yeti_lair", "sloth_lair", "drake_lair", "cyclops_camp", "necro_crypt", "void_rift"]);
  const at = (o) => ({ biome: "minecraft:deep_dark", dimension: "minecraft:overworld", y: -50, sky: 0, ...o });
  assert.deepEqual([inPlace(PLACES.deep_dark, at({})), inPlace(PLACES.deep_dark, at({ biome: "minecraft:plains" })), inPlace(PLACES.ancient_city, at({})), inPlace(PLACES.deep_caves, at({}))], [true, false, false, false]);
  assert.deepEqual([PLACES.deep_dark.directions, PLACES.ancient_city.directions, PLACES.ancient_city.byScript], [true, undefined, true]);
  assert.equal(placeLines({}, ["cave_expeditions"], { deep_dark: "The nearest from where you stand: about 300 blocks to the north (x 0, z -300), below the surface" })[6], `§8Deep Dark§7: not found yet. Where to look: ${PLACES.deep_dark.hint}. The nearest from where you stand: about 300 blocks to the north (x 0, z -300), below the surface.`);
  assert.match(placeLines({ ancient_city: { x: -312, y: -48, z: -216 } }, false)[8], /^§bAncient Cities§7: found at x -312, y -48, z -216\. Ruined halls of deepslate/);
  const places = src("world/places.js");
  for (const s of ["export function findPlace(player, id, loc) {", "if (!place || rec.found[id]) return false;"]) assert.ok(places.includes(s), s);
  // The entities: the act (0 to 6) and the heartbeat synced; walking, still, or walking over to the tagged player; 1.9
  // tall and 0.7 wide, a sculkling half that; never pushable; no attack of any kind.
