  for (const en of [zoo, wild]) {
    assert.deepEqual(en.description.properties, { "zoocraft:act": { type: "int", range: [0, 6], default: 0, client_sync: true }, "zoocraft:excited": { type: "bool", default: false, client_sync: true } });
    assert.deepEqual([en.components["minecraft:collision_box"], en.components["minecraft:pushable"], en.component_groups["zoocraft:still"]["minecraft:movement"].value], [{ width: 0.7, height: 1.9 }, undefined, 0]);
    const follow = en.component_groups["zoocraft:visit"]["minecraft:behavior.follow_mob"];
    assert.deepEqual([follow.search_range, follow.filters.all_of], [T.followRange, [{ test: "is_family", subject: "other", value: "player" }, { test: "has_tag", subject: "other", value: "zoocraft_heard" }]]);
    for (const e of ["zoocraft:move", "zoocraft:still", "zoocraft:visit"]) assert.equal(en.events[e].add.component_groups.length, 1, e);
    assert.ok(!/attack|melee|hurt_on_contact|nearest_attackable_target/.test(JSON.stringify(en)), "never hostile");
  }
  for (const e of ["zoocraft:seek_feeder", "zoocraft:seek_none", "zoocraft:juvenile", "zoocraft:home_8"]) assert.ok(zoo.events[e] && !wild.events[e], e);
  assert.deepEqual(zoo.component_groups["zoocraft:juvenile"]["minecraft:collision_box"], { width: 0.35, height: 0.95 });
  const tempt = wild.component_groups["zoocraft:moving"]["minecraft:behavior.tempt"];
  assert.deepEqual([tempt.within_radius, tempt.items], [T.baitRange, T.bait]);
  assert.ok(wild.components["minecraft:despawn"] && !zoo.components["minecraft:despawn"] && zoo.components["minecraft:persistent"]);
  // The spawn rule: the deep dark only, underground, on its sculk and deepslate, alone, one near a player at most.
