  const c = sr.conditions[0];
  assert.deepEqual([sr.description.population_control, c["minecraft:height_filter"], c["minecraft:herd"], c["minecraft:density_limit"], "minecraft:spawns_underground" in c, c["minecraft:biome_filter"]], ["animal", { min: -64, max: 0 }, { min_size: 1, max_size: 1 }, { underground: 1 }, true, { test: "has_biome_tag", value: "deep_dark" }]);
  assert.ok(c["minecraft:spawns_on_block_filter"].includes(K.SCULK));
  // The client: the model, the skin and its two glow layers drawn with the warden's glow material (ignoring the light,
  // their strength a Molang alpha), the heartbeat from the excited property, the sculkling at half size.
  for (const n of ["skulker", "wild_skulker"]) {
    const ce = read(`../packs/RP/entity/${n}.entity.json`)["minecraft:client_entity"].description;
    assert.deepEqual([ce.identifier, ce.geometry.default, ce.scripts.scale, ce.materials], [`zoocraft:${n}`, "geometry.zoocraft.skulker", `q.is_baby ? ${sk.breeding.juvenileScale} : 1`, { default: "entity_alphatest", glow: "warden_bioluminescent_layer" }]);
    assert.deepEqual(ce.render_controllers, ["controller.render.zoocraft.skulker", "controller.render.zoocraft.skulker_glow", "controller.render.zoocraft.skulker_heart"]);
    assert.ok(ce.scripts.pre_animation.includes("v.excited = q.property('zoocraft:excited');"));
    for (const t of Object.values(ce.textures)) assert.ok(existsSync(new URL(`../packs/RP/${t}.png`, import.meta.url)), t);
  }
  const rc = read("../packs/RP/render_controllers/skulker.render_controllers.json").render_controllers;
  assert.deepEqual([rc["controller.render.zoocraft.skulker_glow"].ignore_lighting, rc["controller.render.zoocraft.skulker_glow"].color.a, rc["controller.render.zoocraft.skulker_heart"].color.a], [true, "v.glow_alpha", "v.heart_alpha"]);
  const geo = read("../packs/RP/models/entity/skulker.geo.json")["minecraft:geometry"][0];
  const names = new Set(geo.bones.map((b) => b.name));
