  for (const b of ["head", "tendrilL", "tendrilR", "armL", "armR", "legL", "legR"]) assert.ok(names.has(b), b);
  const head = geo.bones.find((b) => b.name === "head").cubes[0];
  assert.equal(head.origin[1] + head.size[1], 30, "1.9 blocks to the top of its head (30 units: 1.875)");
  const ctl = JSON.stringify(read("../packs/RP/animation_controllers/skulker.animation_controllers.json"));
  for (const s of [`v.act == ${K.ACT.sit}`, `v.act == ${K.ACT.buried}`, `v.act != ${K.ACT.buried}`, `v.act == ${K.ACT.listen}`, `v.act == ${K.ACT.sniff}`]) assert.ok(ctl.includes(s), s);
  const lang = readFileSync(new URL("../packs/RP/texts/en_US.lang", import.meta.url), "utf8");
