  // The test zoo: a pair in a dark house with a sculk floor (52 exhibits); a sculk catalyst its one light (6).
  const bp = BLUEPRINTS.find((b) => b.id === "skulker");
  assert.deepEqual([bp.species, bp.w, bp.d, bp.sexes], ["zoocraft:skulker", 12, 12, "mf"]);
  assert.ok(bp.w * bp.d >= requiredArea(HABITAT_PROFILES.medium_terrestrial, 2), "room for the pair");
  const plan = planZoo({ x: 0, z: 0 }, -61, 100);
