  assert.deepEqual([dr.coats, dr.warmth, dr.social, dr.rationUnitsPerParkDay, dr.roosts, dr.soulLight, dr.dangerous], [["Emerald", "Ember", "Frost"], { min: 1 }, { minGroup: 1, recommendedMax: 3, prefersCompany: false }, 4, undefined, undefined, undefined]);
  assert.deepEqual([dr.breeding.litter, dr.breeding.juvenileScale, dr.breeding.young, dr.breeding.youngPlural], [1, 0.35, "hatchling", "hatchlings"]);
  assert.equal(new Set(dr.names).size, 16);
  assert.ok(Object.values(SPECIES).filter((o) => o !== dr).every((o) => !o.names.some((n) => dr.names.includes(n))), "names of its own");
  assert.deepEqual(validateData(), []);
