  assert.ok(T.bait.every((b) => RATIONS[b]?.diet === "meat") && T.hatchlingScale === dr.breeding.juvenileScale);
  // The hall: roofed, 16 blocks of air, 30 x 30 for the first and 300 more each; no perches. The Void Perch's height is
