  for (const s of ["if (sp.warmth) lines.splice(4, 0, `§7${dragonWildLine(BALANCE.dragon)}`);", "if (sp.warmth) {", "Carrying one: a Reinforced Crate.", "else if (prof.aerial && prof.lands) lines.push(`§7Dragon hall:"]) assert.ok(journal.includes(s), s);
