  for (const s of ['if (wants("warmth") && !out.error) {', "} else if (!species && !out.error && out.usableArea >= HABITAT_PROFILES.great_aerial.baseArea) {", "if (fires.campfires > 0 || gold.gold > 0 || endFloor >= (SPECIES[ZOO_DRAKE]?.endGround?.minCells ?? 100)) {", "air.height = HABITAT_PROFILES.great_aerial.minHeight;", "ex.dragon = dragon ? { campfires: dragon.campfires, spots: dragon.spots } : undefined;", "isSoulLight(b.typeId) || CAMPFIRES.has(b.typeId) || isHive(b.typeId) || b.typeId === BED ? b.permutation.getAllStates() : undefined", "{ cellsPerYield: airOpts.cellsPerYield, minHeight: airOpts.minHeight }, dragon);", "{ cellsPerYield: airOpts.cellsPerYield, minHeight: air.height }, dragon);", "(dragon && air === r ? dragon.lowTops : 0)) - (molebear?.tunnels ?? 0)); // floor under a roof", "(chorus?.lowTops ?? 0) + (dragon?.lowTops ?? 0))), escape", "running.set(exId, { gen, at: system.currentTick });", "if (running.get(exId)?.gen === gen) running.delete(exId);", "if (busy(id)) continue; // a measurement already under way finishes first", "if (pending.has(ex.id) || busy(ex.id)) continue;"]) assert.ok(exs.includes(s), s);
  // The Lava Falls' page names its dragons (0.1.156: the Mythical Glade's before; its test has the rest).
