    const c = en.components;
    assert.deepEqual([c["minecraft:collision_box"], c["minecraft:physics"], c["minecraft:movement"].value, c["minecraft:pushable"], c["minecraft:pushable_by_entity"], c["minecraft:fire_immune"]], [{ width: 2.4, height: 2.2 }, { has_gravity: false, has_collision: true }, 0, undefined, undefined, {}]);
    assert.ok(c["minecraft:navigation.hover"] && c["minecraft:movement.hover"]);
