  for (const e of ["zoocraft:juvenile", "zoocraft:home_4", "zoocraft:home_32"]) assert.ok(zoo.events[e] && !wild.events[e], e);
  assert.deepEqual(zoo.events["minecraft:entity_spawned"].add.component_groups, ["zoocraft:coat_0", "zoocraft:home_16"]);
  assert.deepEqual(wild.events["minecraft:entity_spawned"].randomize.map((r) => [r.weight, r.add.component_groups[0], r.remove.component_groups.length]), [[2, "zoocraft:coat_0", 2], [2, "zoocraft:coat_1", 2], [1, "zoocraft:coat_2", 2]]);
  assert.ok(wild.components["minecraft:despawn"] && !zoo.components["minecraft:despawn"] && zoo.components["minecraft:persistent"]);
  assert.deepEqual([zoo.description.is_spawnable, wild.description.is_spawnable], [false, true]);
