  // The flight: a hall 36 x 36 of floor with 16 of air. It flies to each spot it picks and reaches it in time.
  const cells = new Map();
  for (let x = 0; x < 36; x++) for (let z = 0; z < 36; z++) for (let y = 1; y <= 16; y++) cells.set(`${x},${y},${z}`, y === 1 ? "land" : "air");
  const kindAt = (x, y, z) => cells.get(`${x},${y},${z}`);
  const air = [...cells].filter(([, k]) => k === "air").map(([k]) => k.split(",").map(Number));
  const land = [...cells].filter(([, k]) => k === "land").map(([k]) => k.split(",").map(Number));
  let seed = 11;
  const rnd = () => (seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648;
  const G = GR.GRIFFIN_FLIGHT, DV = GR.DIVE_FLIGHT;
  const step = (st, spot, g, drifting = false) => {
    const fw = facing(st.yaw);
    const clear = Boolean(kindAt(Math.floor(st.pos.x + fw.x * g.lookAhead), Math.floor(spot.y), Math.floor(st.pos.z + fw.z * g.lookAhead))) && !D.tightTurn(st.pos, st.yaw, spot, g);
    const v = glideStep({ pos: st.pos, yaw: st.yaw, spot, drifting, clearAhead: clear, trim: st.trim }, g);
    st.trim = v.trim;
    const next = { x: Math.max(1.2, Math.min(34.8, st.pos.x + v.x)), y: Math.max(2, st.pos.y + v.y), z: Math.max(1.2, Math.min(34.8, st.pos.z + v.z)) };
    if (next.x !== st.pos.x + v.x || next.z !== st.pos.z + v.z) st.bumps++;
    if (next.y !== st.pos.y + v.y) st.grounded++;
    st.pos = next;
    st.yaw = v.yaw;
  };
  const st = { pos: { x: 18, y: 8, z: 18 }, yaw: 0, trim: 0, bumps: 0, grounded: 0 };
  let legs = 0, worst = 0;
  for (let leg = 0; leg < 200; leg++) {
    const spot = D.pickAirSpot(air, st.pos, kindAt, G, rnd);
    if (!spot) continue;
    legs++;
    assert.ok(D.roomToFly(kindAt, Math.floor(spot.x), Math.floor(spot.y), Math.floor(spot.z), G) && spot.y >= 3, JSON.stringify(spot));
    let t = 0;
    for (; t < G.spotTicks && !reached(st.pos, spot, G); t++) step(st, spot, G);
    worst = Math.max(worst, t);
  }
  assert.ok(legs > 190 && worst < G.spotTicks && st.bumps === 0, JSON.stringify({ legs, worst, bumps: st.bumps }));
  // The dive: from the top of the hall (3 blocks under the roof's air at most, 8 or more over the floor) down at a spot 2
  // or 3 blocks over the floor ahead of it (within 50 degrees, at least as far as the drop): every dive comes down within
  // its time, never into a wall or the floor. A hall under 10 blocks of air has no dives.
  const span = GR.hallSpan(air, land);
  assert.deepEqual(span, { floor: 1, top: 16 });
  assert.equal(GR.pickDiveTop(air, { x: 18, y: 8, z: 18 }, kindAt, { floor: 1, top: 9 }, G, rnd), undefined);
  let dives = 0, slowest = 0, lowest = Infinity;
  const shallow = [];
  for (let i = 0; i < 120; i++) {
    const top = GR.pickDiveTop(air, st.pos, kindAt, span, G, rnd);
    if (!top) continue;
    assert.ok(top.y - 0.5 >= span.top - 3 && top.y - 0.5 >= span.floor + 8 && D.roomToFly(kindAt, Math.floor(top.x), Math.floor(top.y), Math.floor(top.z), G), JSON.stringify(top));
    for (let t = 0; t < G.spotTicks && !GR.atDiveTop(st.pos, top, G); t++) step(st, top, G);
    if (!GR.atDiveTop(st.pos, top, G)) continue;
    const from = st.pos.y;
    const low = GR.pickDiveLow(air, st.pos, st.yaw, kindAt, span, G, rnd);
    if (!low) continue;
    const dx = low.x - st.pos.x, dz = low.z - st.pos.z;
    const off = Math.abs(((((Math.atan2(-dx, dz) * 180) / Math.PI - st.yaw) % 360) + 540) % 360 - 180);
    assert.ok([span.floor + 2, span.floor + 3].includes(Math.floor(low.y)) && off <= 50 && Math.hypot(dx, dz) >= Math.max(9, (st.pos.y - Math.floor(low.y)) * GR.DIVE_SLOPE) && Math.hypot(dx, dz) <= 22, JSON.stringify({ low, off }));
    dives++;
    let t = 0;
    for (; t < DV.spotTicks && !reached(st.pos, low, DV) && st.pos.y - low.y >= 0.6; t++) {
      step(st, low, DV);
      lowest = Math.min(lowest, st.pos.y);
    }
    slowest = Math.max(slowest, t);
    // (all the way down: within 1.5 blocks of the low spot's height, a drop of 6 or more)
    if (st.pos.y - low.y >= 1.5 || from - st.pos.y < 6) shallow.push([+(from - st.pos.y).toFixed(1), +(st.pos.y - low.y).toFixed(1)]);
  }
