  for (const en of [zoo, wild]) {
    assert.deepEqual(en.description.properties, { "zoocraft:act": { type: "int", range: [0, 9], default: 0, client_sync: true } });
    const c = en.components;
    assert.deepEqual([c["minecraft:collision_box"], c["minecraft:pushable"], c["minecraft:navigation.walk"].avoid_water, c["minecraft:health"].max], [{ width: 1.3, height: 2.2 }, undefined, false, 30]);
    for (const n of [0, 1]) assert.deepEqual([en.component_groups[`zoocraft:coat_${n}`]["minecraft:variant"].value, en.events[`zoocraft:coat_${n}`].add.component_groups], [n, [`zoocraft:coat_${n}`]]);
    assert.ok(!/attack|melee|hurt_on_contact|nearest_attackable_target|shooter/.test(JSON.stringify(en)), "never hostile");
    assert.ok(c["minecraft:type_family"].family.includes("glowhorn"));
    assert.ok(en.component_groups["zoocraft:seek_trunk"] && en.events["zoocraft:seek_trunk"] && en.events["zoocraft:seek_none"]);
  }
  assert.deepEqual(zoo.component_groups["zoocraft:juvenile"]["minecraft:collision_box"], { width: 0.65, height: 1.1 });
  assert.ok(zoo.component_groups["zoocraft:seek_feeder"] && !wild.component_groups["zoocraft:seek_feeder"], "only a zoo one walks to a feeder");
  const moving = wild.component_groups["zoocraft:moving"];
  const shy = moving["minecraft:behavior.avoid_mob_type"].entity_types[0];
  const flee = moving["minecraft:behavior.avoid_mob_type"];
  assert.ok(flee.max_dist === shy.max_dist && flee.max_flee > flee.max_dist && !("sprint_distance" in shy) && !("max_flee" in shy), "it runs on past where it noticed you: max_flee at the top, as the panda's (and no sprint_distance in the entry: the game rejects the entity)");
  assert.deepEqual([shy.max_dist, moving["minecraft:behavior.avoid_mob_type"].ignore_visibility, moving["minecraft:behavior.tempt"].within_radius, moving["minecraft:behavior.tempt"].items], [T.shyRange, true, T.baitRange, ["zoocraft:leafy_ration"]]);
  assert.deepEqual(wild.events["minecraft:entity_spawned"].randomize.map((x) => [x.weight, x.add.component_groups[0]]), [[3, "zoocraft:coat_0"], [2, "zoocraft:coat_1"]]);
  assert.ok(wild.components["minecraft:despawn"] && !zoo.components["minecraft:despawn"] && zoo.components["minecraft:persistent"]);
  assert.deepEqual([zoo.description.is_spawnable, wild.description.is_spawnable], [false, true]);
  // The spawn rule: the Mythical Glade only, on its grass in daylight, in herds of 2 to 4.
