  const c = sr.conditions[0];
  assert.deepEqual([sr.description.population_control, c["minecraft:spawns_on_block_filter"], c["minecraft:herd"], c["minecraft:density_limit"], "minecraft:spawns_on_surface" in c, c["minecraft:biome_filter"], c["minecraft:weight"]], ["animal", ["minecraft:grass_block"], { min_size: 2, max_size: 4 }, { surface: 6 }, true, { test: "has_biome_tag", value: "zoocraft_mythic" }, { default: 15 }]);
  // The client: the model, a stag's and a hind's coat and a fawn's, each by day and by night (the night one from dusk to
