    dip: (y) => (y <= 61 ? "minecraft:soul_soil" : "minecraft:air"),
    step: (y) => (y <= 64 ? "minecraft:soul_soil" : "minecraft:air"),
    lava: (y) => (y <= 62 ? "minecraft:lava" : "minecraft:air"),
    carpet: (y) => (y <= 63 ? "minecraft:soul_soil" : y === 64 ? "minecraft:black_carpet" : "minecraft:air"),
    deep: (y) => (y <= 58 ? "minecraft:soul_soil" : "minecraft:air"),
