  assert.deepEqual(N.clampBox({ from: { x: 0, y: -5, z: 0 }, to: { x: 1, y: 140, z: 1 } }, { min: 0, max: 128 }), { from: { x: 0, y: 0, z: 0 }, to: { x: 1, y: 127, z: 1 } });
  assert.equal(N.CRYPT_APART, 40);
  assert.deepEqual([R.site.min, R.site.max, R.site.parks, R.site.tries, R.findRange, R.lookAgain], [28, 44, 160, 48, 16, 600]);
  // The ground under a crypt site: Nether ground with 6 open over it; the small plants and fire count as open (the crypt
