    roots: (y) => (y <= 40 ? "minecraft:warped_nylium" : y === 41 ? "minecraft:warped_roots" : "minecraft:air"),
    fungus: (y) => (y <= 40 ? "minecraft:crimson_nylium" : y === 41 ? "minecraft:crimson_fungus" : y <= 46 ? "minecraft:weeping_vines" : "minecraft:air"),
    tree: (y) => (y <= 40 ? "minecraft:warped_nylium" : y <= 45 ? "minecraft:warped_stem" : "minecraft:air"),
    lava: (y) => (y <= 38 ? "minecraft:lava" : "minecraft:air"),
    soulfire: (y) => (y <= 40 ? "minecraft:soul_soil" : y === 41 ? "minecraft:soul_fire" : "minecraft:air"),
