  assert.deepEqual(gkeys.map((k, i) => N.cryptGroundY(gAt, i, 0, 60, 30, 6)), [40, 40, 40, undefined, "wet", 40, 44, undefined]);
  // A site: the ground round the middle (every 2 blocks out to radius 6) at most 5 over it and 4 under it.
  const site = (f) => N.cryptSiteLevel((x, z) => f(x, z), { x: 0, z: 0 }, 50);
  assert.equal(site(() => 40), 40);
  assert.equal(site((x) => (x === 6 ? 45 : 40)), 40, "a rise of 5 at the rim: cut away");
  assert.equal(site((x) => (x === 6 ? 46 : 40)), undefined, "6: too high");
  assert.equal(site((x) => (x === -6 ? 36 : 40)), 40, "a dip of 4: filled");
  assert.equal(site((x) => (x === -6 ? 35 : 40)), undefined, "5: too deep");
  assert.equal(site((x, z) => (x === 2 && z === 2 ? "wet" : 40)), undefined, "lava in it");
  assert.equal(site((x, z) => (x === 0 && z === 0 ? undefined : 40)), undefined, "no ground at the middle");
  assert.deepEqual([R.site.up, R.site.down, N.CRYPT.clearUp, N.CRYPT.fillDown], [5, 4, 8, 4], "what it cuts and fills covers them");
  // Its crypt: a round floor of radius 6, the altar at the back with the black carpet before it, four pillars topped with
  // soul lanterns, the way in at the front clear; the same look from the same seed.
  const c = { x: 40, y: 50, z: -12 };
  const above0 = (bl, c0) => bl.filter((q) => q.y > c0.y);
  for (const facing of [0, 1, 2, 3]) {
    const bl = N.cryptBlocks(c, facing, 777);
    assert.deepEqual(N.cryptBlocks(c, facing, 777), bl, "seeded");
    const frame = Y.lairFrame(c, facing);
    const uv = (b) => {
      for (let u = -13; u <= 13; u++) for (let w = -13; w <= 13; w++) { const p = frame(u, w, 0); if (p.x === b.x && p.z === b.z) return [u, w]; }
      return undefined;
    };
    assert.ok(bl.every((b) => uv(b) && Math.hypot(...uv(b)) <= N.CRYPT.radius + 0.5 && b.y >= c.y && b.y <= c.y + 4), "inside the floor");
    const ids = (id) => bl.filter((b) => b.id === id);
    assert.equal(ids("minecraft:black_carpet").length, 6);
    assert.ok(ids("minecraft:black_carpet").every((b) => [3, 4].includes(uv(b)[1]) && Math.abs(uv(b)[0]) <= 1 && b.y === c.y + 1), "the carpet before the altar");
    assert.deepEqual(ids("minecraft:chiseled_polished_blackstone").filter((b) => b.y === c.y + 1).map((b) => uv(b)).sort(), [[-1, 5], [0, 5], [1, 5]], "the altar at the back");
    const lanterns = ids("minecraft:soul_lantern");
    assert.equal(lanterns.length, 6);
    assert.ok(lanterns.every((b) => b.states?.hanging === false));
    assert.equal(ids("minecraft:polished_blackstone_brick_slab").length, 2, "two headstones");
    assert.ok(ids("minecraft:polished_blackstone_brick_slab").every((b) => b.states["minecraft:vertical_half"] === "bottom"));
    assert.equal(ids("minecraft:bone_block").length, 4);
    const key = (o) => `${o.x},${o.y},${o.z}`;
    assert.ok(ids("minecraft:bone_block").every((o) => above0(bl, c).filter((q) => key(q) === key(o)).length === 1), "each bone on a spot of its own");
    assert.ok(!bl.some((b) => /nether_brick/.test(b.id)), "none of a fortress's own blocks: a crypt never counts as a fortress");
    const above = bl.filter((b) => b.y > c.y);
    assert.ok(above.every((b) => { const [u, w] = uv(b); return !(Math.abs(u) <= 1 && w < 0); }), `facing ${facing}: the way in at the front is clear`);
    const floor = bl.filter((b) => b.y === c.y);
    assert.ok(floor.every((b) => ["minecraft:soul_soil", "minecraft:soul_sand", "minecraft:polished_blackstone_bricks"].includes(b.id)));
    assert.ok(floor.filter((b) => b.id === "minecraft:soul_soil" || b.id === "minecraft:soul_sand").length >= floor.length * 0.7, "mostly soul soil and sand");
    assert.equal(N.cryptColumns(c, facing).length, floor.length, "a floor block for every column cleared");
    // The way out: 3 wide and 6 long, in front of the way in, just past the rim.
    const path = N.cryptPath(c, facing);
    const inCrypt = new Set(N.cryptColumns(c, facing).map((q) => `${q.x},${q.z}`));
    assert.equal(new Set(path.map((q) => `${q.x},${q.z}`)).size, 18);
    assert.ok(path.every((q) => !inCrypt.has(`${q.x},${q.z}`)), "past the rim");
    assert.ok(path.every((q) => { const [u, w] = uv({ ...q, y: c.y }); return Math.abs(u) <= 1 && w <= -7 && w >= -12; }), `facing ${facing}: in front of the way in`);
    const den = N.cryptDen(c, facing);
    const a = frame(0, 3, 1), b2 = frame(0, 4, 1);
    assert.deepEqual([den.x, den.y, den.z], [(a.x + b2.x) / 2 + 0.5, c.y + 1, (a.z + b2.z) / 2 + 0.5], "put on the middle of its carpet");
    assert.deepEqual(den.bed, { x: den.x, y: den.y, z: den.z });
  }
