  assert.deepEqual([imitationFor("zoocraft:zoo_zombified_piglin")?.sound, imitationFor("minecraft:zombie_pigman")?.sound, imitationFor("zoocraft:zoo_piglin"), imitationFor("zoocraft:zoo_piglin_brute")], ["mob.imitate.zombiepig", "mob.imitate.zombiepig", undefined, undefined]);
  for (const [sp, , , plural] of ALL) assert.deepEqual(breedingCheck({ species: sp, plural, on: true, animals: [] }, BALANCE.breeding), breedingCheck({ species: zom, plural, on: true, animals: [] }, BALANCE.breeding));
  // The Bastion: piglins and brutes; zombified piglins keep a pen of their own.
