  for (const o of ["zoocraft:zoo_zombie", "zoocraft:zoo_creaking", "zoocraft:zoo_breeze", "zoocraft:zoo_ravager"]) assert.ok(!canShare(wa.id, o), o);
  assert.deepEqual(M.lookEvents(wa.wildSource, 0, 0), []);

