    assert.deepEqual(c["minecraft:type_family"].family, bcs["minecraft:type_family"].family.map((f) => (f === `${stage}_zombie` ? `${stage}_warden` : f)));
    const t = JSON.stringify(e);
    for (const bad of ["minecraft:attack", "melee", "sonic_boom", "roar", "sniff", "behavior.dig", "emerge", "anger_level", "investigate_suspicious", "suspect_tracking", "vibration", "mob_effect", "darkness", "nearest_attackable_target", "minecraft:timer", "minecraft:despawn", "minecraft:loot", "freezing_immune", "ambient_sound_interval", '"minecraft:pushable"', '"monster"', '"warden"']) assert.ok(!t.includes(bad), `${stage}_warden: ${bad}`);
    const own = ["minecraft:type_family", "minecraft:health", "minecraft:collision_box", "minecraft:movement", "minecraft:breathable", "minecraft:behavior.random_stroll", "minecraft:knockback_resistance", "minecraft:fire_immune", "minecraft:heartbeat", "minecraft:movement_sound_distance_offset", "minecraft:behavior.look_at_player"];
    const strip = (x) => Object.fromEntries(Object.entries(x).filter(([k]) => !own.includes(k)));
