  for (const n of ["root", "body", "head", "jaw", "neck1", "neck5", "tail1", "tail12", "wing", "wingtip", "wing1", "wingtip1", "rearleg", "rearfoot1", "frontleg1", "frontfoot"]) assert.ok(bones.has(n), n);
  assert.ok(geo.bones.every((b) => b.name === "root" || b.parent), "every part on the root");
  const anim = read("../packs/RP/animations/zoo_ender_dragon.animation.json");
  assert.equal(anim.format_version, "1.8.0");
